Tự động tạo quy tắc viết lại cho nhiều phân loại Tôi đã quay trở lại với các câu lệnh viết lại... Tôi đang tìm kiếm một giải pháp tự động hóa hơn. Tôi tình cờ bắt gặp điều này trên mạng:

/**
* Tạo tất cả các quy tắc viết lại cho một loại bài đăng nhất định.
*
* Các quy tắc viết lại cho phép một loại bài đăng được lọc theo tất cả các tổ hợp và biến thể
* của các phân loại áp dụng cho loại bài đăng được chỉ định và các query_vars bổ sung được chỉ định với
* tham số $query_vars.
*
* Phải được gọi từ một hàm được gắn vào hành động 'generate_rewrite_rules' để rằng toàn cầu
* $wp_rewrite->preg_index hàm trả về giá trị chính xác.
*
* @param string|object $post_type Loại bài đăng mà bạn muốn tạo các quy tắc viết lại
* @param mảng $query_vars tùy chọn các biến query không phải phân loại mà bạn muốn tạo các quy tắc viết lại. Các quy tắc sẽ được tạo để bắt bất kỳ chuỗi duy nhất cho query_var, đó là, một quy tắc dưới dạng '/ query_var / (. +)'
*
* @author Brent Shepherd <me@brentshepherd.com>
* @since 1.0
*/
hàm eg_generate_rewrite_rules( $post_type, $query_vars = mảng() ) {
toàn cầu $wp_rewrite;
nếu( ! is_object( $post_type ) )
$post_type = get_post_type_object( $post_type );
mảng $new_rewrite_rules = mảng();
$taxonomies = get_object_taxonomies( $post_type->name, 'objects' );
// Thêm bộ lọc phân loại vào mảng biến query
foreach( $taxonomies as $taxonomy ){
// $query_vars[$taxonomy->rewrite['slug']] = $taxonomy->query_var;
$query_vars[] = $taxonomy->rewrite['slug'] ;
add_rewrite_tag('%'.$taxonomy->rewrite['slug'].'%','([^&]+)');
}
// Vòng lặp qua tất cả các tổ hợp có thể của các biến query
for( $i = 1; $i <= count( $query_vars ); $i++ ) {
$new_rewrite_rule = $post_type->rewrite['slug'] . '/';
$new_query_string = 'index.php?post_type=' . $post_type->name;
// Đặt tiền tố các bản ghi lại & truy vấn
for( $n = 1; $n <= $i; $n++ ) {
$new_rewrite_rule .= '(' . implode( '|', $query_vars ) . ')/(.+?)/';
$new_query_string .= '&' . $wp_rewrite->preg_index( $n * 2 - 1 ) . '=' . $wp_rewrite->preg_index( $n * 2 );
}
// Cho phép trang của loại bài đăng được lọc - WordPress mong đợi 'page' trong URL nhưng sử dụng 'paged' trong chuỗi truy vấn để trang không phù hợp với regex của chúng tôi
$new_paged_rewrite_rule = $new_rewrite_rule . 'page/([0-9]{1,})/';
$new_paged_query_string = $new_query_string . '&paged=' . $wp_rewrite->preg_index( $i * 2 + 1 );
// Làm cho dấu gạch chéo cuối cùng tùy chọn
$new_paged_rewrite_rule = $new_paged_rewrite_rule . '?$';
$new_rewrite_rule = $new_rewrite_rule . '?$';
// Thêm các bản ghi lại mới
$new_rewrite_rules = mảng( $new_paged_rewrite_rule => $new_paged_query_string,
$new_rewrite_rule
=> $new_query_string
) + $new_rewrite_rules;
}
trả về $new_rewrite_rules;
}
