function facebook_callback() {
$item ='facebook';
$default ='http://facebook.com/samplefacebooktitle';
$group = 'general_display_options';
$input = create_input($item,$default,$group);
echo $input;
}

Và sau đó là hàm create_input:

function create_input($item,$default,$group) {
$obj = $group.'['.$item.']';
$options = get_option($group);
nếu ($options[$item] != '') {
$value= $options[$item];
} khác {
$value = $default;
}
return '<input type="text" id="'.$item.'" name="'.$obj.'" value="'. $value .'" />';
}

Để khởi tạo các giá trị mặc định, chúng tôi cần lưu trữ từng tab một cách riêng biệt lần đầu tiên khi chủ đề tải và chủ đề này sẽ được tùy chỉnh cho quốc tế hóa bởi nhiều công ty ở các nước khác. Vì vậy, câu hỏi là, liệu có cách nào đơn giản để tải trước các giá trị mặc định này và có chúng được lưu tự động trước khi các tùy chọn chủ đề được lưu lần đầu tiên không? Và nếu không, ai biết cách nào để lưu tất cả các tùy chọn chủ đề cùng một lúc khi bạn nhấp vào nút Lưu trên bất kỳ tab nào?

