Sử dụng kết quả của một hàm và gọi nó vào một hàm khác Tôi đang cố gắng nắm bắt một khái niệm khá đơn giản trong PHP nhưng tôi chưa quen lắm. Tôi có một hàm như sau:

function pa_insertPage($atts, $content = null) {
    // Giá trị mặc định nếu không có pageid được cung cấp
    $output = NULL;

    // Tách các tham số và gán vào mảng
    extract(shortcode_atts(array("page" => '2404' // Giá trị cho trang Course Descriptions), $atts));

    // Nếu có một ID trang được chỉ định, thực hiện truy vấn
    if (!empty($page)) {
        $pageContent = new WP_query();
        $pageContent->query(array('page_id' => $page));

        while ($pageContent->have_posts()) : $pageContent->the_post();
            // Gán nội dung vào $output
            $output = apply_filters( 'the_content', get_the_content() );
        endwhile;
    }

    return $output;
}

Và tôi muốn sử dụng giá trị trả về của hàm này trong một hàm khác có tên là naada_assess(). Trong hàm naada_assess(), tôi đã gọi $recClasses = pa_insertPage($output); nhưng điều đó không hoạt động như mong đợi.

