        );
        $pid = wp_insert_user($new_user);

        if($pid) :
            $field_key = "field_52f4fedbcdb79";
            $post_id = $pid;
            $value = get_field($field_key, $post_id);
            $value[] = array(
                "more_contacts_name" => $row->ContactName,
                "more_contacts_email" => $row->ContactEmail,
                "acf_fc_layout" => "row_1"
            );
            $value[] = array(
