Cách hạn chế nội dung bài viết và xóa chú thích hình ảnh ra khỏi nó Tôi đang sử dụng hàm này để giới hạn nội dung trong chủ đề của tôi. Nhưng vấn đề là mỗi khi tôi gọi hàm, nó cũng hiển thị chú thích hình ảnh. Tôi muốn loại bỏ chú thích hình ảnh khi gọi hàm the_content_limit. Đây là mã:

function the_content_limit($max_char, $more_link_text = '', $stripteaser = 0, $more_file = '') {
$content = get_the_content($more_link_text, $stripteaser, $more_file);
$content = apply_filters('the_content', $content);
$content = str_replace(']]>', ']]&gt;', $content);
$content = strip_tags($content);
if (strlen($_GET['p']) > 0) {
echo "";
echo $content;
echo "&nbsp;<a href='";
the_permalink();
echo "'>"."Read More &rarr;</a>";
echo "";
}
else if ((strlen($content)>$max_char) && ($espacio = strpos($content, " ", $max_char ))) {
$content = substr($content, 0, $espacio);
$content = $content;
echo "";
echo $content;
echo "...";
echo "&nbsp;<a href='";
the_permalink();
echo "'>"."</a>";
echo "";
}
else {
echo "";
echo $content;
echo "&nbsp;<a href='";
the_permalink();
echo "'>"."Read More &rarr;</a>";
echo "";
}
}

Chỉnh sửa sau khi đăng bài - thay đổi không được lưu lại Tôi đang phát triển một plugin đơn giản thực hiện xử lý bổ sung trên nội dung bài viết khi người dùng lưu/cập nhật bài viết (ví dụ nhấp vào nút "Xuất bản bài viết" hoặc "Cập nhật bài viết").

function call_my_function_after_edit_post($post_id) {
    // Nếu đây chỉ là bản sửa đổi, không làm gì cả
    if (wp_is_post_revision( $post_id ) || wp_is_post_autosave( $post_id ))
        return $post_id;

    $text = my_string_manipulation_function($_POST['post_content']);
    $excerpt = my_string_manipulation_function($_POST['post_excerpt']);

    /* Đang thử nghiệm */
    $content = "Nội dung cũ: \r\n".$_POST['post_content']."\r\n\r\nNội dung mới: \r\n".$text;
    $fp = fopen($_SERVER['DOCUMENT_ROOT'] . "/test.txt","wb");
    fwrite($fp,$content);
    fclose($fp);
    /* KẾT THÚC THỬ NGHIỆM */

    // Gỡ bỏ hàm này để tránh vòng lặp vô hạn
    remove_action('publish_post', 'call_my_function_after_edit_post');
    wp_update_post(array('ID' => $post_id, 'post_content' => $text, 'post_excerpt' => $excerpt));
    add_action('publish_post', 'call_my_function_after_edit_post');
}

add_action('publish_post', 'call_my_function_after_edit_post');

