Cách tôi lưu dữ liệu:

// Lưu dữ liệu
function save_custom_meta($post_id) {
global $custom_meta_fields;

// xác minh nonce
if (!wp_verify_nonce($_POST['custom_meta_box_nonce'], basename(__FILE__)))
return $post_id;

// kiểm tra autosave
if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE)
return $post_id;

// kiểm tra quyền truy cập
if ('page' == $_POST['post_type']) {
if (!current_user_can('edit_page', $post_id))
return $post_id;
} elseif (!current_user_can('edit_post', $post_id)) {
return $post_id;
}

// lặp qua các trường và lưu dữ liệu
foreach ($custom_meta_fields as $field) {
if($field['type'] == 'tax_select') continue;
$old = get_post_meta($post_id, $field['id'], true);
$new = $_POST[$field['id']];
if ($new && $new != $old) {
update_post_meta($post_id, $field['id'], $new);
} elseif ('' == $new && $old) {
delete_post_meta($post_id, $field['id'], $old);
}
} // kết thúc foreach

// lưu phân loại
$post = get_post($post_id);
$category = $_POST['category'];
wp_set_object_terms( $post_id, $category, 'category' );
}
add_action('save_post', 'save_custom_meta');

Cách hiển thị widget trên trang chủ? **Xin lỗi vì tiếng Anh của tôi. Tôi là một người mới trong wordpress. Tôi đang cố gắng tạo một widget nhỏ để nhúng video từ youtube hoặc các dịch vụ lưu trữ video khác. Mọi thứ đều hoạt động tốt ở phía sau (Wordpress adminsitrator). Đây là bản in màn hình >> http://i.imgur.com/jfedV4R.gif Khi tôi xuất bản widget vào thanh bên của mình, widget không hiển thị bất cứ điều gì. Nhưng hoạt động tốt ở phía sau. Đây là mã widget của tôi:

<?php
/**
* Today Video Widget Class
*/
class Today_video extends WP_Widget {
/**
* Widget setup.
*/
function Today_video() {
/* Widget settings. */
$widget_ops = array(
'classname' => 'tm_widget_today_video',
'description' => __('Display today video on your site', 'today_video')
);
/* Widget control settings. */
$control_ops = array(
'width' => 300,
'height' => 350,
'id_base' => 'today_video'
);
/* Create the widget. */
$this->WP_Widget( 'today_video' , __( 'Today Video' , 'today_video' ), $widget_ops, $control_ops );
}
/**
* The frontend function
*/
function widget( $args, $instance ) {
extract( $args );
/* Our variables from the widget settings. */
if(isset($instance))
{
if( isset( $instance[ 'title' ] ) ) {
$title =
apply_filters( 'widget_title', $instance[ 'title' ] );
}
if( isset( $instance[ 'template' ] ) ) {
$template =
htmlspecialchars_decode( $instance[ 'template' ] );
}
}
}
/**
* Backend widget settings
*/
function update( $new_instance, $old_instance ) {
$instance = $old_instance;
/* Strip tags for title and name to remove HTML (important for text inputs). */
$instance['title'] =
strip_tags( $new_instance['title'] );
// htmlspecialchars to save html markup in database, at frontend we use htmlspecialchars_decode
$instance['template'] =
htmlspecialchars($new_instance['template']);
return $instance;
}
/**
* Displays the widget settings controls on the widget panel.
*
* Backend widget options form
*/
function form( $instance ) {
$defaults = array(
'title' => __(  'Today Video', 'today_video'),
'template' => __('<iframe width="200" height="150" src="http://www.youtube.com/embed/tv49TbW5rEg" frameborder="0" allowfullscreen></iframe>', 'today_video'),
);
$instance = wp_parse_args( (array) $instance, $defaults ); ?>
<p>
<label for="<?php echo $this->get_field_id( 'title' ); ?>"><?php _e('Title:', 'hybrid'); ?></label>
<input id="<?php echo $this->get_field_id( 'title' ); ?>" name="<?php echo $this->get_field_name( 'title' ); ?>" value="<?php echo $instance['title']; ?>" style="width:96%;float:right;" />
</p>
<p>
<textarea id="<?php echo $this->get_field_id( 'template' ); ?>" name="<?php echo $this->get_field_name( 'template' ); ?>"  style="width:100%;height:100px;"><?php echo $instance['template']; ?></textarea>
</p>
<?php
}
}
//Add function to widgets_init that'll load today_video
add_action( 'widgets_init', create_function( '', 'register_widget( "Today_video" );' ) );
