hàm paginate_categories( $query )
{
// không phải là trang quản trị và đó là truy vấn chính
nếu (! is_admin() && $ query-> is_main_query () )
{
nếu (is_category ())
{
nếu (get_page_by_title(get_queried_object()-> cat_name) != null)
$ startpage_total = 4; // hiển thị 4 bài viết trên trang bắt đầu nếu có nội dung (ví dụ: có một trang với cùng tiêu đề)
khác
$ startpage_total = 16;
$ pages_total = 16; // hiển thị 16 bài viết trên tất cả các trang khác
nếu (! is_paged ()) {
$ query-> set ('posts_per_page', $ startpage_total);
} khác {
// một trang phân trang
$ query-> set ('posts_per_page', $ pages_total);
$ paged = (get_query_var ('paged'))? get_query_var ('paged'): 1;
$ offset = $ startpage_total + ($ pages_total * ($ paged-2));
$ query-> set ('offset', $ offset );
}
}
}
}
add_action ('pre_get_posts', 'paginate_categories');

hàm itsme_adjust_category_offset_pagination ( $ found_posts, $ query ) {
$ ppp = get_option ('posts_per_page');
nếu ($ query-> is_main_query () && is_category () && (get_page_by_title (get_queried_object () -> cat_name) != null))
{
$ first_page_ppp = 4;
nếu (! is_paged ()) {
trả về ( $ found_posts);
} khác {
trả về ( $ found_posts - ($ first_page_ppp - $ ppp));
}
}
}
add_filter ('found_posts', 'itsme_adjust_category_offset_pagination', 10, 2);

