jQuery Validate wp_editor Tôi có một biểu mẫu, và trong biểu mẫu, tôi sử dụng  để tạo ra một TinyMCE thay vì một "textarea" đơn giản. Vấn đề là tôi không thể xác thực wp_editor bằng jQuery Validation. Đây là mã của tôi cho jQuery Validation:

$(document).ready(function() {
    $("#user_submitted_post").validate({
        errorPlacement: function(error, element) {},
        debug: false,
        rules: {
            user_submitted_title: {required: true},
            user_submitted_progress: {required: true},
            user_submitted_goals: {required: true},
            user_submitted_categories: {required: true},
            user_submitted_tags: {required: true},
        },
        invalidHandler: function(form, validator) {
            var errors = validator.numberOfInvalids();
            if (errors) {
                $("#error-message").show().text("Vui lòng đảm bảo rằng tất cả các trường bắt buộc đã được điền đầy đủ.");
            } else {
                $("#error-message").hide();
            }
        },
        submitHandler: function(form) {
            tinyMCE.triggerSave();
            var serialized = $(form).serialize();
            console.log(serialized);
            $(form).ajaxSubmit();
        }
    })
})

