hướng đến trang không mong muốn khi lưu bài viết tùy chỉnh / bài viết tùy chỉnh không lưu Tôi đã thêm (hoặc ít nhất là cố gắng thêm) một loại bài viết tùy chỉnh có hộp meta tùy chỉnh cho phép đính kèm tệp vào bài viết. Chức năng này hoạt động không ổn định, cho phép tải lên một số tệp nhưng lại không thành công với những tệp khác mà không hiển thị thông báo lỗi. Khi không thành công, bài viết được lưu tự động dưới dạng nháp và người dùng bị chuyển hướng đến trang "Bài viết" trong khu vực quản trị mà không có cảnh báo nào. Tôi đã kiểm tra kỹ mã code nhưng vẫn không thể tìm ra lý do tại sao điều này xảy ra, vì vậy nếu ai có ý tưởng gì, tôi rất muốn được nghe. Dưới đây là mã code tôi đang sử dụng:

function save_custom_meta_data($id) {
/* --- Xác minh bảo mật --- */
if(!wp_verify_nonce($_POST['file_upload_nonce'], "nonce_for_uploads")) {
return; //$id;
} // kết thúc if

if(defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
return;// $id;
} // kết thúc if

if( !current_user_can( 'edit_post' ) ) return;
/* - Kết thúc xác minh bảo mật - */

// Đảm bảo mảng tệp không rỗng
if(!empty($_FILES['wp_custom_attachment']['name'])) {
// Sử dụng API của WordPress để tải tệp lên
$upload = wp_upload_bits($_FILES['wp_custom_attachment']['name'], null, file_get_contents($_FILES['wp_custom_attachment']['tmp_name']));

if(isset($upload['error']) && $upload['error'] != 0) {
wp_die('Có lỗi xảy ra khi tải tệp lên. Lỗi là: ' . $upload['error']);
} else {
$upload['file'] = str_replace('\\', '/', $upload['file']);
add_post_meta($id, 'wp_custom_attachment', $upload);
update_post_meta($id, 'wp_custom_attachment', $upload);

add_post_meta($id, 'wp_custom_attachment_url', $_POST['wp_custom_attachment_url']);
update_post_meta($id, 'wp_custom_attachment_url', $_POST['wp_custom_attachment_url']);
} // kết thúc if/else
} else {
// Lấy tham chiếu đến tệp liên quan đến bài viết này
$doc = get_post_meta($id, 'wp_custom_attachment', true);

// Lấy giá trị URL dẫn đến tệp được lưu trữ trong phần tử văn bản
$delete_flag = get_post_meta($id, 'wp_custom_attachment_url', true);

// Xác định xem có tệp nào liên quan đến bài viết này hay không và xem cờ xóa đã được đặt hay chưa (bằng cách xóa nội dung trong hộp nhập)
if(strlen(trim($doc['file'])) > 0 && strlen(trim($delete_flag)) == 0) {
// Thử xóa tệp. Nếu xóa không thành công, hiển thị lỗi của WordPress.
$doc['file'] = str_replace('\\', '/', $doc['file']);
if(unlink($doc['file'])) {
// Việc xóa đã thành công, vì vậy đặt lại dữ liệu meta của WordPress
update_post_meta($id, 'wp_custom_attachment', null);
update_post_meta($id, 'wp_custom_attachment_url', '');
} else {
wp_die('Có lỗi xảy ra khi cố gắng xóa tệp của bạn.');
} // kết thúc if/else
} // kết thúc if
} // kết thúc if/else
}

