Lưu dữ liệu meta box? Tất cả những gì tôi thực sự muốn là dữ liệu meta box được lưu A) như một biến toàn cục có thể truy cập bên trong vòng lặp và B) để lưu dữ liệu vào hộp văn bản để khi người dùng nhấn nút cập nhật, nội dung họ viết sẽ hiện ra trong hộp văn bản sau khi được cập nhật. Hiện tại, tôi biết nó không phù hợp với tiêu chí B), và tôi không chắc liệu nó có thể truy cập như một biến toàn cục trong vòng lặp hay không. Xin giúp đỡ?

add_action( 'add_meta_boxes', 'testimonial_text_box' );

function testimonial_text_box() {
    add_meta_box(
        'testimonial_text_box',
        __( 'Text Testimonial:', 'myplugin_textdomain' ),
        'testimonial_text_box_content',
        'testimonial',
        'normal',
        'high'
    );
}

function testimonial_text_box_content( $post ) {
    $values = get_post_custom( $post->ID );

    $text = isset( $values['my_meta_box_text'] ) ? esc_attr( $values['my_meta_box_text'][0] ) : ”;
    $selected = isset( $values['my_meta_box_select'] ) ? esc_attr( $values['my_meta_box_select'][0] ) : ”;
    $check = isset( $values['my_meta_box_check'] ) ? esc_attr( $values['my_meta_box_check'][0] ) : ”;

    wp_nonce_field( plugin_basename( __FILE__ ), 'testimonial_text_box_content_nonce' );

    $value = get_post_meta( $post->ID, '_my_meta_value_key', true );

    echo '<label for="testimonial_text">';
    _e("Nội dung của bài chứng nhận:", 'myplugin_textdomain' );
    echo '</label> ';

    echo '<br/>';

    echo '<textarea align="top" id="testimonial_text" name="testimonial_text" value="'.esc_attr($value).'" style="width:100%;height:200px;margin:5px -20px 3px 0;" /></textarea>';
}

add_action( 'save_post', 'testimonial_text_box_save' );

function testimonial_text_box_save( $post_id ) {
    if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE )
        return;

    if ( !wp_verify_nonce( $_POST['testimonial_text_box_content_nonce'], plugin_basename( __FILE__ ) ) )
        return;

    if ( 'testimonial' == $_POST['post_type'] ) {
        if ( !current_user_can( 'edit_page', $post_id ) )
            return;
    } else {
        if ( !current_user_can( 'edit_post', $post_id ) )
            return;
    }

    $testimonial_text = $_POST['testimonial_text'];

    update_post_meta( $post_id, 'testimonial_text', $testimonial_text );
}

Cách sử dụng/bật Phân trang? Tôi đang tạo một mã ngắn để hiển thị danh sách người dùng với một hồ sơ cụ thể trong WordPress. Nhưng tôi không thể kích hoạt hoặc hiển thị phân trang. Tôi có 25 người dùng trên trang web của mình và muốn hiển thị 5 hồ sơ người dùng mỗi trang và bao gồm phân trang. Tôi đã thêm một vai trò mới là "sinh viên", và nhiều trường tùy chỉnh sử dụng Advanced Custom Fields cho hồ sơ sinh viên. Vì vậy, tôi cần hiển thị một danh sách các sinh viên với các trường phù hợp. Cho đến nay vẫn tốt, vấn đề là ở việc phân trang mà tôi không thể kích hoạt được. Dưới đây là một ví dụ về mã của tôi:

add_shortcode('list-users', 'list_users');

function list_users($atts) {
    global $wpdb;

    $args = array(
        'blog_id' => '',
        'role' => 'student',
        'meta_key' => 'pw_user_status', // Tôi đang sử dụng plugin New User Approve
        'meta_value' => 'approved', // Nếu người dùng bị từ chối, họ sẽ không xuất hiện trong danh sách
        'meta_compare' => '',
        'meta_query' => array(),
        'include' => array(),
        'exclude' => array(),
        'orderby' => 'display_name',
        'order' => 'ASC',
        'offset' => '',
        'search' => '',
        'number' => '2',
        'count_total' => true,
        'fields' => 'all',
        'who' => ''
    );

    $students = get_users($args);

    if (is_user_logged_in()) {
        $content = "<div id='list-of-users'>";
        foreach ($students as $student) {
            $content .= "<li>";
            $content .= "<div class=\"edit-profile\">";
            if (current_user_can('administrator')) {
                $link_of_profile_of_user = get_edit_user_link($student->ID);
                $content .= "<a href=".$link_of_profile_of_user." class=\"edit-profile\"> Chỉnh sửa hồ sơ này</a>";
            }
            $content .= "</div>";
            $content .= get_avatar($student->ID);
            $content .= "<span class='item'>Tên: </span>" . get_the_author_meta('display_name', $student->ID) . "<br />";
            $content .= "<span class='item'>Ngày sinh: </span>" . get_the_author_meta('date_of_birth_acf_student', $student->ID) . "<br />";
            $content .= "<span class='item'>Khóa học: </span>" . get_the_author_meta('course_acf_student', $student->ID) . "<br />";
            $content .= "<span class='item'>Email: </span>" . get_the_author_meta('user_email', $student->ID) . "<br />";
            $content .= "<span class='item'>Điện thoại: </span>" . get_the_author_meta('phone_acf_student', $student->ID) . "<br />";
            $content .= "<span class='item'>Thành phố: </span>" . get_the_author_meta('city_acf_student', $student->ID) . "<br />";
            $content .= "</li>";
        } // Đóng vòng lặp foreach
        $content .= "</div>";
        return $content;
    } // Đóng điều kiện cho người dùng đã đăng nhập
} // Đóng hàm

Chức năng cập nhật widget không lưu giá trị Xin chào WordPress Answers! Tôi đang gặp khó khăn với chức năng "update" của widget lưu trữ giá trị một cách chính xác, nhưng trước tiên hãy để tôi giải thích tình huống. Tôi đang viết một plugin widget news ticker đơn giản, lọc các bài viết được hiển thị theo kiểu bài viết với các hộp kiểm trong biểu mẫu cài đặt widget. Để tạo ra các hộp kiểm, tôi đang sử dụng một vòng lặp "foreach" trên các kiểu bài viết có sẵn. Tuy nhiên, chức năng cập nhật widget không lưu trữ các giá trị kiểu bài viết. Tôi đã xác nhận điều này bằng cách thực hiện một "print_r" trong hàm biểu mẫu (các giá trị tồn tại) và một lần nữa trong hàm widget (các giá trị không tồn tại). Đây là mã của tôi:

class ami_newsticker_widget extends WP_Widget {
// xử lý widget
function ami_newsticker_widget () {
$widget_ops = array(
'classname' => 'ticketcontainer',
'description' => 'Hiển thị một thanh cuộn tin tức'
);
$this->WP_Widget( 'ami_newsticker_widget', 'AMI News Ticker Widget', $widget_ops );
}

