Tạo một vòng lặp thông qua các bài viết của một loại bài viết tùy chỉnh (sự kiện) và tạo tệp .ics (iCal)? Tôi thực sự cần sự giúp đỡ của bạn về một tính năng mà tôi chưa từng làm việc với nó cho đến nay. Tôi có một loại bài viết tùy chỉnh tên là `wr_event`. Và tôi tạo ra hàm `WP_Query` tùy chỉnh này để thu hồi tất cả các bài viết của loại bài viết đó được sinh ra sau ngày hôm qua. Nó khá đơn giản và hoạt động rất tốt.

```php
function event_list_iCal() {
    $yesterday = time() - 24*60*60;
    $args = array(
        'post_type' => 'wr_event',
        'posts_per_page' => -1, // hiển thị tất cả bài viết
        'meta_key' => 'event_date',
        'orderby' => 'meta_value_num',
        'order' => 'ASC',
        'meta_value' => $yesterday,
        'meta_compare' => '>',
    );
    $loop = new WP_Query( $args );
    $ical = "BEGIN:VCALENDAR
    VERSION:2.0
    PRODID:-//hacksw/handcal//NONSGML v1.0//EN";
    $posts = get_posts( $args );
    foreach( $posts as $post ) : setup_postdata($post);
        $ical .= "BEGIN:VEVENT
        UID:" . md5(uniqid(mt_rand(), true)) . "mysite.com
        DTSTAMP:" . gmdate('Ymd').'T'. gmdate('His') . "Z
        DTSTART:".unixToiCal(get_event_date($post), get_event_time($post))."00Z
        DTEND:".unixToiCal(get_event_end_date($post), get_event_end_time($post))."00Z
        SUMMARY:".get_the_title($post->ID)."
        DESCRIPTION:".get_the_content($post->ID)."
        END:VEVENT";
    endforeach;
    $ical .= "END:VCALENDAR";
    header('Content-type: text/calendar; charset=utf-8');
    header('Content-Disposition: inline; filename=calendar.ics');
    echo $ical;
    exit;
}

function unixToiCal($uStamp = 0, $tzone = 0.0) {
    $uStampUTC = $uStamp + ($tzone * 3600);
    $stamp  = date("Ymd\THis\Z", $uStampUTC);
    return $stamp;
}
```

