Xin vui lòng cho tôi biết làm thế nào tôi có thể thực hiện điều này từ hàm Walker tùy chỉnh của tôi. Tôi đã thử thực hiện điều này theo cách tĩnh nhưng không biết cách đặt nó sau khi đóng thẻ </UL>. Ai đó xin hãy giúp tôi.

class custom_menu_walker extends Walker_Nav_Menu {
    private $curItem;

    function start_lvl(&$output, $depth) {
        $thisItem = $this->curItem;
        $output .= '<ul class="sub-menu"><li>
            <div class="yamm-content">';
        $output .= ( $depth == 0 && $thisItem->object == 'category' ) ? '<ul class="col-sm-4 list-unstyled">' : '<ul class="col-sm-12 list-unstyled">';
    }

    function end_lvl(&$output, $depth) {
        $output .= '</ul></div> </li></ul>';
    }

    // Thêm các lớp chính/phụ vào các thẻ li và liên kết
    function start_el( &$output, $item, $depth = 0, $args = array(), $id = 0 ) {
        $this->curItem = $item;
        $indent = ( $depth > 0 ? str_repeat( "\t", $depth ) : '' ); // mã thụt lề
        // các lớp phụ thuộc vào độ sâu
        $depth_classes = array(
            ( $depth == 0 ? 'dropdown' : '' ),
            (( $depth == 0 && $item->object == 'category' ) ? 'yamm-first' : ''),
            ( $depth % 2 ? 'menu-item-odd' : 'menu-item-even' ),
            'menu-item-depth-' . $depth
        );
        $depth_class_names = esc_attr( implode( ' ', $depth_classes ) );
        // các lớp được truyền vào
        $classes = empty( $item->classes ) ? array() : (array) $item->classes;
        $class_names = esc_attr( implode( ' ', apply_filters( 'nav_menu_css_class', array_filter( $classes ), $item ) ) );
        // xây dựng html
        $output .= $indent . '<li id="nav-menu-item-'. $item->ID . '" class="' . $depth_class_names . ' ' . $class_names . '">';
        // các thuộc tính liên kết
        $attributes = ' class="menu-link ' . ( $depth == 0 ? 'dropdown-toggle' : '' ) . '"';
        $item_output = sprintf( '%1$s<a%2$s>%3$s%4$s%5$s</a>%6$s',
            $args->before,
            $attributes,
            $args->link_before,
            apply_filters( 'the_title', $item->title, $item->ID ),
            $args->link_after,
            $args->after
        );
        // xây dựng html
        $output .= apply_filters( 'walker_nav_menu_start_el', $item_output, $item, $depth, $args );
    }

    function end_el( &$output, $item, $depth = 0, $args = array(), $current_object_id = 0 ) {
        if ( $depth == 0 && $item->object == 'category' ) {
            ?>
            <div class="imgmenu">
                <img src="$imageUrl" alt="" />
                <div class="info">
                    <h2>title text come here</h2>
                    <a href="#">learn more</a>
                </div>
            </div>
            <?php
        }
    }
}

Sử dụng add_filter() trong Widgets Chỉ có một câu hỏi tham khảo hàm `add_filter()`. Bạn có thể sử dụng hàm này trong lớp widget của WordPress không?

