/** Tên người dùng cơ sở dữ liệu MySQL */

define('DB_USER', 'wpms_user_2012');

/** Mật khẩu cơ sở dữ liệu MySQL */

define('DB_PASSWORD', 'wpms_password');

/** Tên máy chủ cơ sở dữ liệu MySQL */

define('DB_HOST', 'localhost');

/** Bộ ký tự cơ sở dữ liệu để sử dụng khi tạo bảng cơ sở dữ liệu. */

define('DB_CHARSET', 'utf8');

/** Loại sắp xếp cơ sở dữ liệu. Không thay đổi nếu không chắc chắn. */

define('DB_COLLATE', '');

Tôi đã kiểm tra lại tên người dùng và mật khẩu và thậm chí thay đổi chúng nhiều lần để đảm bảo rằng chúng khớp nhau. Tôi đã thử 'localhost', '127.0.0.1' và địa chỉ IP của máy chủ của tôi cho DB_NAME. Không có tác dụng gì cả.

