add_action( 'save_post', 'get_video_file' );

function get_video_file( $post_id ) {
    if('post' != get_post_type())
        return;

    if ( $attachments = get_attached_media( 'video', $post->ID ) ) {
        foreach ($attachments as $attachment) {
            $meta_value = wp_get_attachment_url( $attachment->ID );
            update_post_meta( $post_id, 'tm_video_file', $meta_value );
        }
    }

    // Để tránh vòng lặp vô hạn
    remove_action( 'save_post', 'get_video_file' );
    wp_update_post($post);
    add_action( 'save_post', 'get_video_file' );
}

