Thời gian & Ngày tháng trên bài viết - Custom Function Tôi đang sử dụng hàm tùy chỉnh sau để hiển thị thời gian đăng bài của một bài viết dưới dạng "X phút trước" hoặc "X ngày trước" trong vòng 14 ngày, sau đó nó sẽ chuyển sang thời gian thực (ví dụ: "17/12/2010"):

add_filter('the_time', 'dynamictime');

function dynamictime() {
  global $post;
  $date = $post->post_date;
  $time = get_post_time('G', true, $post);
  $mytime = time() - $time;

  if($mytime > 0 && $mytime < 14*24*60*60)
    $mytimestamp = sprintf(__('%s ago'), human_time_diff($time));
  else
    $mytimestamp = date(get_option('date_format'), strtotime($date));

  return $mytimestamp;
}

