áp dụng tùy chỉnh vào mặc định $wp_query Tôi có thể đọc trên tài liệu rằng nếu tôi cần thực hiện một điều kiện WHERE tùy chỉnh trên WP_Query, tôi cần thực hiện theo hướng dẫn sau:

// Tạo một hàm lọc mới để thêm điều kiện WHERE của chúng ta vào câu truy vấn
function filter_where( $where = '' ) {
    // bài viết từ 30 đến 60 ngày tuổi
    $where .= " AND post_date >= '" . date('Y-m-d', strtotime('-60 days')) . "'" . " AND post_date <= '" . date('Y-m-d', strtotime('-30 days')) . "'";
    return $where;
}
add_filter( 'posts_where', 'filter_where' );
$query = new WP_Query( $query_string );
remove_filter( 'posts_where', 'filter_where' );

Nhưng nếu tôi cần áp dụng một điều kiện WHERE như vậy cho câu truy vấn mặc định? Tôi đã có các điều kiện khác được áp dụng trong hàm pre_get_posts, giống như thế này:

function homepage_load_posts($query) {
    if ($query->is_home()) {
        $params = querystring_var('filter');
        $query->query_vars['post_type'] = array('blog_post', 'post', 'dossier');
        $query->query_vars['posts_per_page'] = 12;
        if ($params) {
            $valid_categories = valid_categories($params['cat']);
            $valid_formats    = valid_formats($params['format']);
            $valid_post_types = valid_post_types($params['type']);
            if ($valid_categories) $query->query_vars['cat'] = $valid_categories;
            if ($valid_formats)    $query->query_vars['tax_query'] = $valid_formats;
            if ($valid_post_types) $query->query_vars['post_type'] = $valid_post_types;
        }
    }
}
add_action('pre_get_posts', 'homepage_load_posts');

