    function numeric_pagination ($pageCount = 9, $query = null) {
        if ($query == null) {
            global $wp_query;
            $query = $wp_query;
        }

        if ($query->max_num_pages <= 1) {
            return;
        }

        $pageStart = 1;
        $paged = $query->query_vars['paged'];

        // Đặt trang hiện tại nếu đang ở trang đầu tiên
        if ($paged == null) {
            $paged = 1;
        }

        // Xác định xem trang bắt đầu có nằm giữa các trang hiển thị hay không và nếu đúng thì di chuyển nó theo cách thích hợp
        if ($paged > floor($pageCount / 2)) {
            $pageStart = $paged - floor($pageCount / 2);
        }

        if ($pageStart < 1) {
            $pageStart = 1;
        }

        // Đảm bảo trang bắt đầu là
        if ($pageStart + $pageCount > $query->max_num_pages) {
            $pageCount = $query->max_num_pages - $pageStart;
        }

        ?>
        <div id="pagination">
        <?php
        if ($paged != 1) {
        ?>
        <a href="<?php echo get_pagenum_link(1); ?>" class="numbered page-number-first">
        <span>&lsaquo; <?php _e('Newest', 'rhinoplasty'); ?></span></a>
        <?php
        }

        // Trang đầu tiên không hiển thị...
        if ($pageStart > 1) {
            //echo 'previous';
        }

        for ($p = $pageStart; $p <= $pageStart + $pageCount; $p ++) {
            if ($p == $paged) {
        ?>
        <span class="numbered page-number-<?php echo $p; ?> current-numeric-page"><?    php echo $p; ?></span>
        <?php
            } else {
        ?>
        <a href="<?php echo get_pagenum_link($p); ?>" class="numbered page-number-<?    php echo $p; ?>"><span><?php echo $p; ?></span></a>
        <?php
            }
        }

        // Trang cuối cùng không hiển thị
        if ($pageStart + $pageCount < $query->max_num_pages) {
            //echo "last";
        }

        if ($paged != $query->max_num_pages) {
        ?>
        <a href="<?php echo get_pagenum_link($query->max_num_pages); ?>" class="numbered page-number-last"><span><?php _e('Oldest', 'rhinoplasty'); ?> &rsaquo;</span></a>
        <?php
        }
        ?>
        </div>
        <?php
    }

