Mã plugin sẽ không hoạt động đúng cách bên trong một lớp Tôi đã viết một đoạn mã đơn giản (lắp ráp từ các hướng dẫn trên mạng) tạo ra một hộp siêu dữ liệu đơn giản (được gọi là "Subheading") và xóa các trường tùy chỉnh khỏi khu vực quản trị. Tất cả hoạt động tốt cho đến khi tôi đặt mã bên trong một lớp. Khi tôi làm điều này, hộp siêu dữ liệu ngừng lưu vào cơ sở dữ liệu. Tôi nghi ngờ rằng điều đó là do tôi cần phải xác định một số đối số cho hàm khởi tạo để thực hiện, nhưng bất cứ điều gì tôi thử đều không thành công. Tôi không thể tìm ra vấn đề, vì vậy bất kỳ sự giúp đỡ nào sẽ được đánh giá cao! Đây là mã:
class MySubBoxClass {
  function __construct() {
    add_action( 'add_meta_boxes', array( $this, 'meta_box_add' ) ); // Gắn meta_box_add() vào móc add_meta_boxes
    add_action( 'save_post', array( $this, 'save_meta_box', 10, 2 ) ); // Gắn save_meta_box() vào móc save_post
    add_action('admin_init', array( $this, 'remove_custom_meta_boxes') ); // Gắn remove_custom_meta_boxes() vào admin_init
  }
  public function meta_box_add() { // Hàm kích hoạt hàm add_meta_box() của Wordpress
    add_meta_box( 'meta-box-id', 'SUBHEADING', array($this, 'html_form_func'), 'post', 'normal', 'high' );
