  public function save_meta_box( $post_id, $post ) {
    // Xác minh nonce trước khi tiếp tục.
    if ( !isset( $_POST['meta_box_nonce'] ) || !wp_verify_nonce( $_POST['meta_box_nonce'], basename( __FILE__ ) ) )
      return $post_id;
    // Lấy đối tượng loại bài viết
    $post_type = get_post_type_object( $post->post_type );
    // Gán biến $new_meta_value giá trị mới được gửi qua đầu vào biểu mẫu HTML có tên 'subheading'
    $new_meta_value = ( isset( $_POST['subheading'] ) ? esc_attr( $_POST['subheading'] ) : '' );
    // Gán biến $meta_key giá trị 'subheading'
    $meta_key = 'subheading';
    // Gán biến $meta_value giá trị của trường tùy chỉnh (xác định bằng khóa $meta_key) hiện đang liên kết với bài viết đó
    $meta_value = get_post_meta( $post_id, $meta_key, true );
    // Nếu một giá trị siêu dữ liệu mới được thêm và giá trị siêu dữ liệu trước đó không có giá trị (== ''), thêm giá trị siêu dữ liệu mới
    if ( $new_meta_value && $meta_value == '' )
      add_post_meta( $post_id, $meta_key, $new_meta_value, true );
    // Nếu giá trị siêu dữ liệu mới không khớp với giá trị cũ, cập nhật nó
    elseif ( $new_meta_value && $new_meta_value != $meta_value )
      update_post_meta( $post_id, $meta_key, $new_meta_value );
    // Nếu không có giá trị siêu dữ liệu mới nhưng có giá trị cũ, xóa nó
    // elseif ( $new_meta_value == '' && $meta_value )
    // delete_post_meta( $post_id, $meta_key, $meta_value );
  }
