Để có được mối quan hệ cha mẹ - container con tôi đã đơn giản thêm div và ul vào hàm start_lvl... Đây là nơi tôi gặp khó khăn trong việc xác định cách tôi có thể tạo ra nhiều anh chị em...
function start_lvl( &$output, $depth = 0, $args = array()) {
$indent = str_repeat("\t", $depth);
$output .=  "\n$indent<div>\n";
$output .=  "\n$indent<ul>\n";
}
Để thêm các lớp vào các phần tử neo cấp cao nhất tôi có một bộ đi bộ tùy chỉnh. Trong hàm start_el tôi đã tiêm các lớp cho các mục neo dựa trên lớp cha.
function start_el( &$output, $item, $depth = 0, $args = array(), $id = 0 ) {
global $wp_query;
$indent = ( $depth ) ? str_repeat( "\t", $depth ) : '';
$indent = ( $depth ) ? str_repeat( "\t", $depth ) : '';
$class_names = $value = '';
$classes = empty( $item->classes ) ? array() : (array) $item->classes;
$classes[] = 'menu-item-' . $item->ID;
$class_names = join( ' ', apply_filters( 'nav_menu_css_class', array_filter( $classes ), $item, $args ) );
$class_names = $class_names ? ' class="' . esc_attr( $class_names ) . '"' : '';
$id = apply_filters( 'nav_menu_item_id', 'menu-item-'. $item->ID, $item, $args );
$id = $id ? ' id="' . esc_attr( $id ) . '"' : '';
/* tiêm một số lớp neo */
if(  $this->$depth == 0) {
if ( in_array( 'two', $item->classes ) || in_array( 'three', $item->classes )) {
$item->class = 'oneCol fly';
}
if ( in_array( 'four', $item->classes )) {
$item->class = 'twoCol fly';
}
};
$output .= $indent . '<li' . $id . $value . $class_names .'>';
$output .= in_array( 'sub_nav_h4', $item->classes ) ? "\n" . $indent . "<h4>\n" : '';
$attributes  = ! empty( $item->attr_title ) ? ' title="'  . esc_attr( $item->attr_title ) .'"' : '';
$attributes .= ! empty( $item->target )     ? ' target="' . esc_attr( $item->target     ) .'"' : '';
$attributes .= ! empty( $item->xfn )        ? ' rel="'    . esc_attr( $item->xfn        ) .'"' : '';
$attributes .= ! empty( $item->url )        ? ' href="'   . esc_attr( $item->url        ) .'"' : '';
/* Điều này 'nên' luôn là đúng vì WP không hỗ trợ các lớp neo */
$attributes .= ! empty( $item->class    )       ?   ' class="'  . esc_attr( $item->class            ) . '"' : '';
$item_output = $args->before;
$item_output .= '<a' . $attributes .'>';
$item_output .= $args->link_before . apply_filters( 'the_title', $item->title, $item->ID ) . $args->link_after;
$item_output .= '</a>';
$item_output .= $args->after;
$output .= apply_filters( 'walker_nav_menu_start_el', $item_output, $item, $depth, $args );
}
