Sử dụng add_rewrite_tag để tạo các url cho các phần trang Tôi đang chia các mẫu trang của tôi thành các vùng có thể liên kết với nhau. Tôi muốn có thể sử dụng các URL sạch sẽ để thực hiện việc đó. Các URL trang của tôi trông giống như thế này "www.example.com/page-name/?section=example" Tôi muốn viết lại URL thành "www.example.com/page-name/example". Tôi đã tìm kiếm câu trả lời nhưng vẫn chưa tìm được.

add_action('init','thick_section_rewrite');

function thick_section_rewrite(){
    add_rewrite_tag([cái gì ở đây?], '([^&/]+)');
    add_rewrite_rule( [cái gì ở đây?], '?section=$matches[1]', 'top' );
}

