update_post_meta không hoạt động trong action hook Tôi đang gặp phải một vấn đề thực sự khi cập nhật các trường tùy chỉnh (trong loại bài viết tùy chỉnh) với dữ liệu từ cơ sở dữ liệu. Tôi có một bảng trong cơ sở dữ liệu được gọi là "wp_company_profiles" với các trường địa chỉ (ví dụ: address_1, address_2). Tôi đã thiết lập các trường tùy chỉnh cho mỗi trong khu vực bài viết quản trị với cùng giá trị. Tôi đang cố gắng kết hợp một hook sẽ lấy dữ liệu từ cơ sở dữ liệu để cập nhật các trường tùy chỉnh. Dưới đây là mã, nhưng tôi không thể tìm ra điều gì còn thiếu.

function get_fields_company_profile($post_id) {

    global $wpdb;

    if ($parent_id = wp_is_post_revision( $post_id )) $postid = $parent_id;

    $postid = $_GET['post'];

    $row = $wpdb->get_row( "SELECT * FROM wp_company_profiles WHERE pid = '$postid' " );

    if ($row) {

        // Lấy các trường từ cơ sở dữ liệu

        $address1 = $row->address_1;

        $address2 = $row->address_2;

        $postcode = $row->postcode;

        $city = $row->city;

        // Cập nhật các trường tùy chỉnh trong khu vực quản trị

        update_post_meta($post_id, 'address_1', $address1);

        update_post_meta($post_id, 'address_2', $address2);

        update_post_meta($post_id, 'postcode', $postcode);

        update_post_meta($post_id, 'city', $city);

    }

}

add_action('init', 'get_fields_company_profile');

