Thiết lập tạm thời với lỗi bài đăng Tôi có một trang wordpress lớn với hơn 200.000 bài viết, với tính năng tự động đăng bài. Nội dung bài viết của tôi chứa "một số thẻ HTML, một số văn bản, một số thẻ <img>". Tôi cần xóa tất cả các thẻ <img> từ nội dung bài viết từ các bài viết cụ thể. Vì vậy tôi có hàm này để thực hiện công việc này:

function remove_images_form_past_posts() {
    if ( get_transient('images_removed_from_past') )
        return;

    $args = array(
        'post_type' => 'post',
        'year' => 2013,
        'monthnum' => 1,
        'day' => 28,
        'post_status' => 'publish',
        'category' => 30,
        'post_author' => 3,
        'nopaging' => 1
    );

    $posts = get_posts( $args );

    if ( $posts ) {
        foreach ( $posts as $post ); setup_postdata( $post ); {
            $newcontent = preg_replace('/<img[^>]+\>/i', '', $post->post_content);
            $newpost = array(
                'ID' => $post->ID,
                'post_content' => $newcontent
            );
            wp_update_post($newpost);
            wp_reset_postdata();
        }
        set_transient('images_removed_from_past', 60 * 60 * 24);
    }
}

add_action('admin_init','remove_images_form_past_posts');

