tắt chức năng gửi email cho admin khi có người dùng mới đăng ký (chức năng không hoạt động) Tôi có đoạn code sau trong file functions.php của tôi. Tôi đang cố gắng vô hiệu hóa việc gửi email cho quản trị viên mỗi khi có người dùng mới đăng ký vào trang web. Tuy nhiên, quản trị vẫn nhận được email. Có gì sai với đoạn code trên không? Và đây có phải là một phần trong các tùy chọn của WP hay không? Tôi không thể tìm thấy tùy chọn này ở bất cứ nơi nào.

// Vô hiệu hóa Email Đăng ký Người dùng Mới
if ( ! function_exists( 'wp_new_user_notification' ) ) :
    function wp_new_user_notification( $user_id, $plaintext_pass = '' ) {
        /** Trở về sớm nếu không có mật khẩu được thiết lập */
        if ( empty( $plaintext_pass ) )
            return;

        $user       = get_userdata( $user_id );
        $user_login = stripslashes( $user->user_login );
        $user_email = stripslashes( $user->user_email );

        // Tùy chọn blogname được thoát mã HTML khi lưu vào cơ sở dữ liệu bằng sanitize_option
        // Chúng tôi muốn đảo ngược điều này cho lĩnh vực văn bản thuần của email.
        $blogname = wp_specialchars_decode( get_option( 'blogname' ), ENT_QUOTES );

        $message  = sprintf( __( 'Tên đăng nhập: %s' ), $user_login) . "\r\n";
        $message .= sprintf( __( 'Mật khẩu: %s' ), $plaintext_pass) . "\r\n";
        $message .= wp_login_url() . "\r\n";

        wp_mail( $user_email, sprintf( __( '[%s] Tên đăng nhập và mật khẩu của bạn' ), $blogname ), $message );
    }
endif;

Widget thanh bên hiển thị bài viết phổ biến không hoạt động? Đây là mã để hiển thị bài viết phổ biến trên giao diện phía trước, tuy nhiên vấn đề là dữ liệu không được lưu từ phía sau. Giống như tôi muốn hiển thị chỉ 3 bài viết phổ biến trên giao diện phía trước, vì vậy tôi chọn tùy chọn 3 nhưng nó không lưu lại. Tuy nhiên, khi tôi truyền giá trị tĩnh cho `$popularpostcount` thì mã này hoạt động `echo $this->popularPosts($popularpostcount);` vì vậy tôi tin rằng vấn đề chỉ là lưu lại tùy chọn được chọn. Tôi mới bắt đầu phát triển plugin, vì vậy vui lòng cho tôi biết tôi mắc lỗi gì trong quá trình phát triển.

<?php
/*
Plugin Name: Popular Post Widget
Plugin URI: http://demo.test.com
Author: Swapnesh Kumar Sinha
Description: This is a plugin to show popular posts in sidebar as a widget.
Version: 1.0
Author URI: http://swapneshsinha.wordpress.com
*/
class PopularPostWidget extends WP_Widget {
public function __construct() {
//Quy trình xử lý widget thực tế
$widget_options = array(
'Description' => 'Show Popular Posts'
);
parent::__construct( 'PopularPostWidget', 'Popular Post Widget', $widget_options);
}

public function form( $instance ) {
//Đầu ra biểu mẫu tùy chọn trên quản trị viên
$instance = wp_parse_args( (array) $instance, array( 'popularpostcount' => '' ) );
$popularpostcount = $instance['popularpostcount'];

echo $popularpostcount;
echo "Số bài viết để hiển thị ";

echo "<select name='popularpostcount' id='popularpostcount'>";
for( $i =1; $i<=5; $i++ )
{
if ( $i == $instance['popularpostcount'] )
echo "<option value='".$i."' selected>".$i."</option>";
else
echo "<option value='".$i."'>".$i."</option>";
}

echo "</select>";
}

public function update( $new_instance, $old_instance ) {
//Xử lý các tùy chọn widget để lưu lại
$instance = $old_instance;
$instance['popularpostcount'] = $new_instance['popularpostcount'];
return $instance;
}

public function widget( $args , $instance ) {
//Đầu ra nội dung của widget
extract($args);
$popularpostcount = apply_filters('widget_title', $instance['popularpostcount']);

echo  "<h2>Most Popular Posts</h2>";
echo  "<ul>";
echo $this->popularPosts($popularpostcount);
echo  "</ul>";
}

public function popularPosts($num)
{
global $wpdb;
$posts = $wpdb->get_results("SELECT comment_count, ID, post_title FROM $wpdb->posts ORDER BY comment_count DESC LIMIT 0 , $num");
foreach ($posts as $post) {
setup_postdata($post);
$id = $post->ID;
$title = $post->post_title;
$count = $post->comment_count;

if ($count != 0) {
$popular .= '<li>';
$popular .= '<a href="' . get_permalink($id) . '" title="">' . $title.'</a> '." - ".$count;
$popular .= '</li>';
}
}
return $popular;
}
