var file_frame;

jQuery('.upload_image_button').live('click', function( event ) {
    event.preventDefault();
    var image_url = jQuery(this).parent('.bb_half').find('.bb_img_url');
    var image_href = jQuery(this).closest('.bb_room_img_form').find('.bb_img_display');

    // Nếu khung media đã tồn tại, hãy mở nó.
    if ( file_frame ) {
        file_frame.open();
        return;
    }

    // Tạo khung media.
    file_frame = wp.media.frames.file_frame = wp.media( {
        title: jQuery( this ).data( 'uploader_title' ),
        button: {
            text: jQuery( this ).data( 'uploader_button_text' ),
        },
        multiple: false  // Đặt thành true để cho phép chọn nhiều tập tin
    });

    // Khi một hình ảnh được chọn, chạy hàm callback.
    file_frame.on( 'select', function() {
        // Chúng tôi đặt multiple thành false để chỉ nhận một hình ảnh từ trình tải lên
        attachment = file_frame.state().get('selection').first().toJSON();

        // Thực hiện một số thao tác với attachment.id và/hoặc attachment.url ở đây
        image_href.css('border', '2px solid red');
        jQuery(this).css('border', '2px solid red');
        jQuery(this).closest('.bb_room_img_form').css('border', '2px solid red');

        image_url.val(attachment.url);
        image_href.attr('src', attachment.url);
    });

    // Cuối cùng, mở cửa sổ modal
    file_frame.open();
});

