Sự kiện được lên lịch xảy ra mỗi lần tải trang, nhưng dự kiến ​​xảy ra hàng ngày Tôi có một sự kiện được lên lịch xảy ra một lần mỗi ngày vào lúc 12 giờ sáng. Tuy nhiên, vì một lý do nào đó, sự kiện được lên lịch của tôi đang xảy ra trên mỗi lần tải trang và tôi không thể tìm ra lý do tại sao. Cron mặc định của WordPress bị vô hiệu hóa. Hiện tại tôi có một công việc cron chạy một phút một lần sử dụng lệnh wget thay thế cho cron mặc định của WordPress. Tôi đã tạo một plugin đơn giản dựa trên mã tại trang web này. Logic chính của tôi hoạt động nhưng tôi không thể tìm ra cách lên lịch nó hàng ngày vào lúc 12 giờ sáng hàng ngày.

<?php
register_activation_hook( __FILE__ , 'activate_daily_event' );

/**
* Khi kích hoạt, đặt thời gian, tần suất và tên của một hook hành động để lên lịch.
*/
function activate_daily_event() {
wp_schedule_event(1402460460 , 'daily', 'prefix_daily_event');
}

add_action( 'prefix_daily_event', 'prefix_do_this_daily' );

/**
* Trên hook hành động được lên lịch, chạy hàm.
*/
function prefix_do_this_daily() {
$terms=get_terms('sp_venue', array( "hide_empty" => 0 ));

if ($terms) {
foreach ($terms as $term ) {
$taxonomy_id = 'taxonomy_' . $term->term_id;
$term_ids[] = $taxonomy_id;
$option = get_option($taxonomy_id, false);

if(option){
$option['sp_venue_status'] = 'Open';
update_option($taxonomy_id, $option);
}
}
}
}

