//Set roles to meta capabilities
add_filter('map_meta_cap', 'my_map_meta_cap', 10, 4 );
function my_map_meta_cap( $caps, $cap, $user_id, $args ) {
/* Nếu chỉnh sửa, xóa hoặc đọc một tác phẩm nghệ thuật, nhận bài viết và đối tượng loại bài viết. */
if ( 'edit_artwork' == $cap || 'delete_artwork' == $cap || 'read_artwork' == $cap ) {
$post = get_post( $args[0] );
$post_type = get_post_type_object( $post->post_type );
/* Thiết lập một mảng trống cho các quyền. */
$caps = array();
}
/* Nếu chỉnh sửa một tác phẩm nghệ thuật, gán quyền cần thiết. */
if ( 'edit_artwork' == $cap ) {
if ( $user_id == $post->post_author )
$caps[] = $post_type->cap->edit_posts;
else
$caps[] = $post_type->cap->edit_others_posts;
}
/* Nếu xóa một tác phẩm nghệ thuật, gán quyền cần thiết. */
elseif ( 'delete_artwork' == $cap ) {
if ( $user_id == $post->post_author )
$caps[] = $post_type->cap->delete_posts;
else
$caps[] = $post_type->cap->delete_others_posts;
}
/* Nếu đọc một tác phẩm nghệ thuật riêng tư, gán quyền cần thiết. */
elseif ( 'read_artwork' == $cap ) {
if ( 'private' != $post->post_status )
$caps[] = 'read';
elseif ( $user_id == $post->post_author )
$caps[] = 'read';
else
$caps[] = $post_type->cap->read_private_posts;
}
/* Trả về các quyền cần thiết cho người dùng. */
return $caps;
}
