Đang cố gắng truy cập bài viết tùy chỉnh chuyển hướng đến trang chủ Tôi mới bắt đầu sử dụng WordPress và có vẻ như tôi cần nhiều thực hành và lời khuyên để nó hoạt động theo cách mà tôi muốn. Tôi thừa hưởng một trang web đang hoạt động từ một người khác. Bây giờ tôi phải thực sự thêm chức năng mới vào nó, nhưng tôi bị kẹt. Tôi đang cố gắng thêm một loại bài viết tùy chỉnh và thực sự hiển thị các bài viết của loại đó. Để làm điều này, tôi chủ yếu là sao chép mã từ những nơi khác trên trang web. Mã tôi sử dụng để tạo một danh mục bài viết mới là sau:

function theme_setup() {
//Mã khác tạo các danh mục bài viết khác
//Chuyện mới của tôi
register_post_type(
'contest',
array(
'label' => 'Concursuri',
'public' => true,
'menu_position' => 5 /*dưới Bài viết*/ ,
'capability_type' => 'post',
'supports' => array('title', 'editor', 'thumbnail', 'custom-fields'),
'taxonomies' => array('contests'),
'hierarchical' => true,
'query_var' => 'contest',
'rewrite' => array('slug' => 'contest/%categorie%', 'with_front' => false),
'feeds' => true, 'pages' => true,
)
);
register_taxonomy(
'contests',
'contest',
array(
'label' => 'Categorii Concursuri',
'public' => true,
'hierarchical' => true,
'rewrite' => array('slug' => 'contest', 'with_front' => false),
)
);
//Sau đó một số thứ khác, và ở cuối:
//flush_rewrite_rules(false); //Bỏ đi và sử dụng truy cập đến permalink thay thế
}
add_action('init', 'theme_setup');
add_filter('post_type_link', 'events_permalink_structure', 10, 3);

function events_permalink_structure($post_link, $post, $leavename) {
$arr = array(
//Một số phần tử ở đây, sau đó là của tôi
'contest' => 'contests',
//Một số phần tử khác ở đây
);
foreach ($arr as $post_type => $tax) {
if ($post->post_type == $post_type) {
$terms = wp_get_object_terms($post->ID, $tax);
if (!empty($terms)) // liên kết theo dạng http://www.site.com/<taxonomie>/%categorie%/<nume>
$post_link = str_replace('%categorie%', $terms[0]->slug, $post_link);
else // liên kết theo dạng http://www.site.com/<taxonomie>/%material%
$post_link = str_replace('/%categorie%', "", $post_link);
}
}
return $post_link;
}

function add_rewrite_rules($rules) {
$newrules = array();
//Một số quy tắc tương tự khác, sau đó là quy tắc mới của tôi
$newrules['^contest/(\d+)/([^/]+)/?'] = 'index.php?post_type=contest&contest=$matches[2]';
return $newrules + $rules;
}
add_filter('rewrite_rules_array', 'add_rewrite_rules');

