function square_slider_template() {
    // Query Arguments
    $args = array(
        'post_type' => 'slides',
        'posts_per_page' => 5
    );

    // The Query
    $the_query = new WP_Query( $args );

    // Kiểm tra xem Query có trả về bài viết nào không
    if ( $the_query->have_posts() ) {
        // Bắt đầu Slider ?>
        <div class="flexslider">
