                <?php
                    // Vòng lặp
                    while ( $the_query->have_posts() ) : $the_query->the_post(); ?>
                    <li>
                        <?php // Kiểm tra xem có URL Slide được cung cấp và nếu có, hãy tạo liên kết đến nó
                        if ( get_post_meta( get_the_id(), 'square_slideurl', true) != '' ) { ?>
                            <a href="<?php echo esc_url( get_post_meta( get_the_id(), 'square_slideurl', true ) ); ?>">
                        <?php }

                        // Hình ảnh Slide
                        echo the_post_thumbnail();

                        // Đóng liên kết Slide nếu có
                        if ( get_post_meta( get_the_id(), 'square_slideurl', true) != '' ) { ?>
                            </a>
                        <?php } ?>
                    </li>
                <?php endwhile; ?>
            </ul><!-- .slides -->
        </div><!-- .flexslider -->
        <?php
    }

    // Đặt lại dữ liệu bài viết
    wp_reset_postdata();
