Permalink Problems Tôi đang gặp vấn đề. Tôi đang chạy WP 3.05 với một danh mục tùy chỉnh. Đây là mã để tạo ra danh mục:

function create_property_taxonomies() {
    // Thêm danh mục mới, làm cho nó phân cấp (như thể loại)
    $labels = array(
        'name' => _x( 'Property Types', 'taxonomy general name' ),
        'singular_name' => _x( 'Property Type', 'taxonomy singular name' ),
        'search_items' => __("Tìm kiếm Property Types"),
        'all_items' => __("Tất cả các Property Types"),
        'parent_item' => __("Parent Property Type"),
        'parent_item_colon' => __("Parent Property Type:");
        'edit_item' => __("Edit Property Type"),
        'update_item' => __("Update Property Type"),
        'add_new_item' => __("Add New Property Type"),
        'new_item_name' => __("New Property Type"),
        'menu_name' => __("Property Type")
    );

    register_taxonomy('property_type',array('sbproperty'), array(
        'hierarchical' => true,
        'labels' => $labels,
        'show_ui' => true,
        'query_var' => true,
        'rewrite' => true,
    ));

    global $wp_rewrite;
    $wp_rewrite->extra_permastructs['property_type'] = array('%property_type%', EP_NONE);
}

Tôi đã sử dụng extra permastruct để cho phép hiển thị danh mục trên URL cơ bản như site.com/taxonomy-slug thay vì site.com/taxonomy/taxonomy-slug. Tôi cũng sử dụng plugin top-level-cats để thực hiện điều tương tự cho các danh mục gốc. Tuy nhiên điều này gây xung đột với trang của tôi. Khi tôi xóa permastruct thì trang được tải trên permalink đẹp, nhưng khi tôi thêm permastruct vào thì nó không tải được, nó trả về lỗi 404 cho tất cả các trang cấp cao nhất.

