      );
      $wp_query = new WP_Query($args);
      while ($wp_query->have_posts()) : $wp_query->the_post();
        $do_not_duplicate = $post->ID;
        $date = get_the_date('Y-m-d');
      endwhile;
      $args = array(
        'post_type'         =>  'videos',
        'posts_per_page'    =>  5
      );
      add_filter( 'posts_where', 'sw_filter_videos_before' ); //không biết cách truyền $date
      $wp_query = new WP_Query($args);
      remove_filter( 'posts_where', 'sw_filter_videos_before' );
      //lặp vòng
      $response = json_encode( array( 'result' => $result ) );
      header( "Content-Type: application/json" );
      echo $response;
      exit;
    }

Sử dụng đúng cách wp_get_object_terms **Tóm tắt:** Làm thế nào để tôi có thể lấy được tên và permalink của đối tượng trả về từ hàm wp_get_object_terms() **Chi tiết:** Tôi đã tạo một loại bài viết tùy chỉnh có tên "ge_zielgruppe" và một danh mục có tên "ge_zielgruppe_taxonomy". Danh mục sau có thể được gắn vào các bài viết và loại bài viết "ge_zielgruppe". Trên trang đơn của "ge_zielgruppe", tôi muốn hiển thị 10 bài viết gần đây nhất được gắn thẻ với cùng một "ge_zielgruppe_taxonomy". Tôi đã thực hiện điều này bằng cách sử dụng mã sau:

<?php
$theZielgruppe = wp_get_object_terms($post->ID, 'ge_zielgruppe_taxonomy');
$zielgruppe = new WP_Query(array('ge_zielgruppe_taxonomy' => $theZielgruppe->slug));
$zielgruppe->query('showposts=10');
if ($zielgruppe->have_posts()) :
    while ($zielgruppe->have_posts()) :
        $zielgruppe->the_post();
    ?>
    <<--archive-stuff-->>
    <?php
    endwhile;
endif;
?>

