Tạo một nút thả xuống và bộ lọc cho hai phân loại tùy chỉnh được gán cho một loại bài viết tùy chỉnh Tôi đang sử dụng mã sau để tạo menu thả xuống và nút lọc cho hai phân loại tùy chỉnh được gán cho một kiểu bài viết tùy chỉnh được gọi là Page Content (mã trước đây ở đây):

function parse_query($query) {
    global $pagenow;
    $qv = &$query->query_vars;
    if ($pagenow=='edit.php' &&
        isset($qv['taxonomy']) && $qv['taxonomy']=='locations' &&
        isset($qv['term']) && is_numeric($qv['term'])) {
        $term = get_term_by('id',$qv['term'],'locations');
        $qv['term'] = $term->slug;
    }
    if ($pagenow=='edit.php' &&
        isset($qv['taxonomy']) && $qv['taxonomy']=='page_sections' &&
        isset($qv['term']) && is_numeric($qv['term'])) {
        $term = get_term_by('id',$qv['term'],'page_sections');
        $qv['term'] = $term->slug;
    }
}

