Hiện tại, tôi đang sử dụng hàm Walker sau đây để điền vào menu thả xuống hiện tại với một **danh sách mục đơn**:

// Mã trong header.php

<?php wp_nav_menu(array(
    'theme_location' => 'menu_main', // vị trí chủ đề của bạn ở đây
    'walker'         => new Walker_Nav_Menu_Dropdown(),
    'items_wrap'     => '<select id="nav_iphone" name="nav_iphone" onchange="if (this.value) window.location.href = this.value;"><option value="">Chọn một tùy chọn để điều hướng</option>%3$s</select>',
)); ?>

// Mã trong function.php

class Walker_Nav_Menu_Dropdown extends Walker_Nav_Menu{
    var $to_depth = -1;

    function start_lvl(&$output, $depth) {
        $output .= '</option>';
    }

    function end_lvl(&$output, $depth) {
        $indent = str_repeat("\t", $depth); // không hiển thị thẻ đóng của con
    }

    function start_el(&$output, $item, $depth, $args) {
        $indent = ( $depth ) ? str_repeat( "&nbsp;", $depth * 4 ) : '';
        $class_names = $value = '';
        $classes = empty( $item->classes ) ? array() : (array) $item->classes;
        $classes[] = 'menu-item-' . $item->ID;
        $class_names = join( ' ', apply_filters( 'nav_menu_css_class', array_filter( $classes ), $item, $args ) );
        $class_names = ' class="' . esc_attr( $class_names ) . '"';
        $id = apply_filters( 'nav_menu_item_id', 'menu-item-'. $item->ID, $item, $args );
        $id = strlen( $id ) ? ' id="' . esc_attr( $id ) . '"' : '';
        $value = ' value="'. $item->url .'"';
        $output .= '<option'.$id.$value.$class_names.'>';
        $item_output = $args->before;
        $item_output .= $args->link_before . apply_filters( 'the_title', $item->title, $item->ID ) . $args->link_after;
        $output .= $indent.$item_output;
    }

    function end_el(&$output, $item, $depth) {
        if(substr($output, -9) != '</option>')
            $output .= "</option>"; // thay thế thẻ đóng </li> bằng thẻ option
    }
}

**Làm thế nào tôi có thể mở rộng giải pháp trên để đáp ứng yêu cầu của tôi như tôi đã chỉ định? Hoặc có giải pháp hoàn toàn khác?** Nếu có, tôi cũng rất sẵn lòng lắng nghe.

Chuyển hướng sau khi đăng ký thành công với mẫu đăng ký ở phía trước Tôi đang cố gắng chuyển hướng người dùng sau khi đăng ký và đăng nhập thành công hoặc không thành công. Mọi thứ hoạt động tốt, ngoại trừ việc chuyển hướng sau khi đăng ký thành công. Hiện tại, tôi được chuyển hướng đến "http://mysite.com/register/?login=failed." Tôi không thể tìm ra lý do tại sao tôi lại không được chuyển hướng đến "http://mysite/com/login/?redirect_to=mysite.com/change-password" mà tôi đã chỉ định ở dưới bằng cách sử dụng "add_action('registration_redirect','redirect_after_success_registration');". Đây là mã của tôi:

// Hook cho việc đăng nhập không thành công
add_action('wp_login_failed', 'my_frontend_login_fail');
function my_frontend_login_fail($username){
// Lấy trang giới thiệu, nơi bài đăng đến từ?
$referrer = add_query_arg('login', false, $_SERVER['HTTP_REFERER']);
// nếu có một trang giới thiệu hợp lệ, và nó không phải là màn hình đăng nhập mặc định
if(!empty($referrer) && !strstr($referrer,'wp-login') && !strstr($referrer,'wp-admin')){
// hãy thêm một số thông tin (login=failed) vào URL để chủ đề sử dụng
wp_redirect( add_query_arg('login', 'failed', $referrer) );
//wp_redirect($referrer . '?login=failed');
exit;
}
}

//Hook cho việc gửi đăng nhập trống
add_action( 'login_head', 'my_frontend_login_no_pass_no_username' );
function my_frontend_login_no_pass_no_username(){
$referrer = add_query_arg('login', false, $_SERVER['HTTP_REFERER']);
if ( (!isset($_REQUEST['user_login']) || ( isset( $_REQUEST['user_login'] ) && trim( $_REQUEST['user_login'] ) == '' ) ) || (!isset($_REQUEST['user_pass']) || ( isset( $_REQUEST['user_pass'] ) && trim( $_REQUEST['user_pass'] ) == '' ) ) ){
wp_redirect( add_query_arg('login', 'failed', $referrer) );
exit;
}
}

// Đăng ký không thành công
add_action('register_post', 'binda_register_fail_redirect', 99, 3);
function binda_register_fail_redirect( $sanitized_user_login, $user_email, $errors ){
// dòng này được sao chép từ hàm register_new_user trong wp-login.php
$errors = apply_filters( 'registration_errors', $errors, $sanitized_user_login, $user_email );
// kiểm tra if này được sao chép từ hàm register_new_user trong wp-login.php
if ( $errors->get_error_code() ){
// thiết lập URL tùy chỉnh của bạn cho việc chuyển hướng
$redirect_url = get_bloginfo('url') . '/register';
// thêm mã lỗi vào URL tùy chỉnh từng phần
foreach ( $errors->errors as $e => $m ){
$redirect_url = add_query_arg( $e, '1', $redirect_url );
}
// cuối cùng, chuyển hướng đến trang tùy chỉnh của bạn với tất cả các lỗi trong các thuộc tính
wp_redirect( $redirect_url );
exit;
}
}

function redirect_after_success_registration () {
$redirect_url=get_bloginfo('url').'/login/?redirect_to='.get_bloginfo('url').'/change-password';
return $redirect_url;
}
add_filter('registration_redirect','redirect_after_success_registration');

