<?php
/*
* Lớp trang chủ đề ảo
*
* Lớp này thực hiện các trang ảo cho một plugin.
*
* Nó được thiết kế để được bao gồm sau đó được gọi cho mỗi phần của plugin
* muốn các trang ảo.
*
* Nó hỗ trợ nhiều trang ảo và các hàm tạo nội dung.
* Các hàm nội dung chỉ được gọi nếu một trang khớp.
*
* Lớp sử dụng các mẫu chủ đề và theo kiến thức của tôi là duy nhất trong việc đó.
* Nó cũng sử dụng các mẫu chủ đề con trước các mẫu chủ đề chính.
*
* Mã ví dụ theo sau lớp.
*
* Tháng 8 năm 2013 Brian Coogan
*/
// Có nhiều lớp trang ảo, chúng ta muốn tránh xung đột!
//
class Virtual_Themed_Pages_BC
{
    public $title = '';
    public $body = '';
    private $vpages = array(); // mảng trang ảo chính
    private $mypath = '';
    public $blankcomments = "blank-comments.php";

    function __construct($plugin_path = null, $blankcomments = null)
    {
        if (empty($plugin_path))
            $plugin_path = dirname(__FILE__);
        $this->mypath = $plugin_path;

        if (! empty($blankcomments))
            $this->blankcomments = $blankcomments;

        // Các trang ảo được kiểm tra trong bộ lọc 'parse_request'.
        // Hành động này bắt đầu mọi thứ nếu chúng ta là một trang ảo
        add_action('parse_request', array(&$this, 'vtp_parse_request'));
    }

    function add($virtual_regexp, $contentfunction)
    {
        $this->vpages[$virtual_regexp] = $contentfunction;
    }

    // Kiểm tra các yêu cầu trang cho các trang ảo
    // Nếu chúng ta có một, gọi hàm tạo nội dung phù hợp
    //
    function vtp_parse_request(&$wp)
    {
        //global $wp;
        if (empty($wp->query_vars['pagename']))
            return; // trang không phải là liên kết vĩnh viễn

        //$p = $wp->query_vars['pagename'];
        $p = $_SERVER['REQUEST_URI'];

        $matched = 0;
        foreach ($this->vpages as $regexp => $func)
        {
            if (preg_match($regexp, $p))
            {
                $matched = 1;
                break;
            }
        }

        // Không làm gì nếu không khớp
        if (! $matched)
            return;

        // thiết lập móc và bộ lọc để tạo trang ảo
        add_action('template_redirect', array(&$this, 'template_redir'));
        add_filter('the_posts', array(&$this, 'vtp_createdummypost'));

        // chúng tôi cũng buộc phải loại bỏ các bình luận; một hộp bình luận ở chân trang của
        // một trang khá vô nghĩa.
