Cách viết lại CPT-Permalinks đúng cách (gắn liền với meta-box-data) Sử dụng các hàm hook bên dưới, tôi đã cố gắng chỉnh sửa lại permalink của tùy chỉnh post type "magazine_issue" để sử dụng giá trị từ các meta-field bổ sung mà tôi đã thêm vào màn hình chỉnh sửa. Vấn đề với mã thực tế của tôi là có vẻ như nó ghi đè URL của tất cả các bài viết tùy chỉnh theo cách mong muốn, nhưng đáng tiếc là khi yêu cầu các trang đó, nó chỉ trả về bài viết chung chung mới nhất ("Hello World") thay vì nội dung thực sự. Làm thế nào để tôi khắc phục vấn đề này?

function magazine_issues_rewrite() {
    global $wp_rewrite;
    $queryarg = 'post_type=magazine_issue&p=';
    $wp_rewrite->add_rewrite_tag('%issuenumber%', '([^/]+)', $queryarg);
    $wp_rewrite->add_rewrite_tag('%issueyear%', '([^/]+)', $queryarg);
    $wp_rewrite->add_permastruct('issue_url_by_meta', '/'.__('issues', 'doev').'/%issueyear%/%issuenumber%/', false);
}

add_action('init', 'magazine_issues_rewrite');

function magazine_issues_permalink($post_link, $id = 0, $leavename) {
    global $wp_rewrite;
    $post = &get_post($id);
    if (is_wp_error($post)) return $post;

    if ('magazine_issue'==get_post_type($post)) {
        $newlink = $wp_rewrite->get_extra_permastruct('issue_url_by_meta');
        $newlink = str_replace("%issuenumber%", get_post_meta($post->ID,'issuenumber',true), $newlink);
        $newlink = str_replace("%issueyear%", get_the_date('Y'), $newlink);
        $newlink = home_url(user_trailingslashit($newlink));
        return $newlink;
    }
}

add_filter('post_type_link', 'magazine_issues_permalink', 1, 3);

pre_get_posts Query không hoạt động cho trang tác giả tùy chỉnh Tôi đang sử dụng chủ đề TwentyTwelve và đã chỉnh sửa truy vấn bài viết tiêu chuẩn trong file author.php bằng mã sau:

function wpd_author_query( $query ) {
    // Mã để thiết lập $current_user_name ở đây
    // Lấy tác giả từ URL
    $author = get_user_by('slug',get_query_var('author_name'));
    $current_user_name = $author->user_nicename;

    if ( $query->is_author() && $query->is_main_query()) {
        // Mã của bạn để thiết lập $current_user_name ở đây
        $query->set( 'meta_key', '_writer_relation_added_date_'.$current_user_name );
        $query->set( 'orderby', 'meta_value_num' );
        $query->set( 'post_status', $post_status );

        $tax_query = array(
            array(
                'taxonomy' => 'writer',
                'field' => 'name',
                'terms' => $current_user_name
            )
        );

        $query->set( 'tax_query', $tax_query );
    }
}

add_action( 'pre_get_posts', 'wpd_author_query' );

Tuy nhiên, tax_query không hoạt động cho trang tác giả. Nó vẫn không lấy các bài viết trong danh mục writer. Tôi đã thử áp dụng mã đó cho các trang khác như is_home() và is_archive() và nó hoạt động tốt. Vậy nên phải có xung đột với wordpress và trang mẫu tác giả không cho phép tôi sử dụng tax_query để lấy các bài viết trong danh mục writer.

