add_action bên ngoài một plugin Tôi đang cố gắng tạo lớp của riêng mình để thực hiện một số thay đổi phổ biến nhất mà tôi cần trong tất cả các trang web WP của tôi. Những điều như loại bỏ thẻ canonical khi không cần thiết hoặc thay đổi mô tả meta. Tôi không tạo một plugin, vì tôi không quen thuộc với nó. Tôi đã viết lớp sau đây, nhưng tôi đã không thể khiến nó hoạt động hoàn toàn. Ngay khi _setup function được gọi, bất cứ điều gì khác cũng được hiển thị trên mã nguồn. Tương tự, tất cả các add_action('wp_head') đều bị bỏ qua. Tôi nghi ngờ rằng điều này là do tôi gọi lại lớp quá muộn, nhưng tôi không biết liệu có phải vậy hay không và làm thế nào tôi có thể kiểm tra nó.

class Stuff_Frontend {
    private static $_instance = null;

    public static function init()
    {
        add_action( 'wp_head', array(self::instance(), '_setup'));
    }

    public static function instance()
    {
        // tạo đối tượng mới nếu nó không tồn tại.
        is_null(self::$_instance) && self::$_instance = new self;

        return self::$_instance;
    }

    /**
     * Thiết lập lớp
     * Thêm và xóa nhiều bộ lọc.
     */
    function _setup() {
        echo "Tôi ở đây;";
        add_action( 'wp_head', array(self::instance(), 'head' ), 1 );

        // Xóa các hành động mà chúng tôi sẽ xử lý thông qua cuộc gọi wpseo_head của chúng tôi, và có lẽ thay đổi đầu ra của
        remove_action( 'wp_head', 'rel_canonical' );
        remove_action( 'wp_head', 'index_rel_link' );
        remove_action( 'wp_head', 'start_post_rel_link' );
        remove_action( 'wp_head', 'adjacent_posts_rel_link_wp_head' );
        remove_action( 'wp_head', 'rsd_link' );
        remove_action( 'wp_head', 'wlwmanifest_link' );

        add_action( 'mystuff', array(self::instance(), 'change_metadesc' ), 10 );
    }

    /**
     * Hàm wrapper chính được gắn vào wp_head. Nó kết hợp tất cả đầu ra trên phía trước.
     */
    public function head() {
        echo "đây là một bài kiểm tra cho lớp đầu của tôi";

        /**
         * Hành động: 'mystuff'
         */
        do_action( 'mystuff' );

        return;
    }

    /**
     * Thay đổi phần tử mô tả meta.
     *
     * @param bool $echo Cho dù có lặp lại mô tả hay không.
     *
     * @return string
     */
    public function change_metadesc() {
        echo "đây là một nỗ lực để thay đổi mô tả";
    }
}

