Thêm số tăng một vào DIV ID Tôi đang sử dụng mã ngắn để hiển thị một loại bài viết tùy chỉnh. Mã ngắn này có thuộc tính để hiển thị chỉ các bài viết trong một danh mục cụ thể trong loại bài viết tùy chỉnh, ví dụ như [faq category="du lịch"]. Đối với mỗi mã ngắn, WordPress sẽ tạo ra một tập hợp HTML cụ thể, bao gồm một thẻ div với id là "faq-accordion". Đối với mỗi mã ngắn, tôi cần tạo ra thẻ div với ID "faq-accordion+1" ví dụ như "faq-accordion1", "faq-accordion2", "faq-accordion3", v.v. Tôi đã thêm được số vào mỗi thẻ div nhưng vì lý do nào đó nó chỉ chạy đến 6 và sau đó lặp lại các số. Đây là mã của tôi

add_shortcode( 'faq', 'wpse105856_shortcode_callback' );

function wpse105856_shortcode_callback( $atts ) {
    extract( shortcode_atts( array(
        'category' => ''
    ), $atts ) );

    $args = array(
        'numberposts' => -1,
        'orderby' => 'menu_order',
        'order' => 'ASC',
        'post_type' => 'faq'
    );

    if ( ! empty( $category ) ) {
        $args['category_name'] = $category;
    };

    $posts = get_posts( $args );

    // Ở đây là nơi tôi đang cố gắng thêm số mới vào thẻ div faq-accordion một cách động

    $num = 0;

    foreach ( $posts as $post ) {
        $faq .= '<div id="faq-accordion'.++$num.'">'; // Mở container
    };

    foreach ( $posts as $post ) { // Tạo mã đánh dấu cho từng câu hỏi
        $faq .= sprintf(('<h3><a href="">%1$s</a></h3><div>%2$s</div>'),
            $post->post_title,
            wpautop($post->post_content)
        );
    };

    $faq .= '</div>'; // Đóng container

    return $faq; // Trả về HTML.
};

