* @since 3.0.0
*
* @uses $super_admins Siêu quản trị viên biến toàn cục, nếu được thiết lập.
*
* @return mảng Danh sách đăng nhập siêu quản trị viên
*/
function get_super_admins() {
    global $super_admins;
    if ( isset($super_admins) )
        return $super_admins;
    else
        return get_site_option( 'site_admins', array('admin') );
}

/**
* Xác định xem người dùng có phải là quản trị viên trang web hay không.
*
* @since 3.0.0
*
* @param int $user_id (không bắt buộc) ID của người dùng. Mặc định là người dùng hiện tại.
* @return bool Đúng nếu người dùng là quản trị viên trang web.
*/
function is_super_admin( $user_id = false ) {
    if ( $user_id )
        $user = new WP_User( $user_id );
    else
        $user = wp_get_current_user();

    if ( empty( $user->id ) )
        return false;

    if ( is_multisite() ) {
        $super_admins = get_super_admins();
        if ( is_array( $super_admins ) && in_array( $user->user_login, $super_admins ) )
            return true;
    } else {
        if ( $user->has_cap('delete_users') )
            return true;
    }

    return false;
}

/**
* Người dùng có khả năng hoặc tên vai trò hay không.
*
* Điều này hữu ích để tìm hiểu xem người dùng có vai trò cụ thể nào
* được chỉ định cho người dùng hay không. Tham số tùy chọn thứ hai cũng có thể được sử dụng để
* kiểm tra các khả năng đối với bài đăng cụ thể.
*
* @since 2.0.0
* @access công khai
*
* @param chuỗi|int $cap Khả năng hoặc tên vai trò để tìm kiếm.
* @param int $post_id Tùy chọn. ID bài đăng để kiểm tra khả năng chống lại bài đăng cụ thể.
* @return bool Đúng, nếu người dùng có khả năng; sai, nếu người dùng không có khả năng.
*/
hàm has_cap( $cap ) {
#       fb($cap);
nếu ( is_numeric( $cap ) ) {
_deprecated_argument( __FUNCTION__, '2.0', __('Sử dụng các cấp độ người dùng của plugin và chủ đề bị lỗi thời. Sử dụng vai trò và khả năng thay thế.') );
$cap = $this->translate_level_to_cap( $cap );
}
$args = array_slice( func_get_args(), 1 );
$args = array_merge( array( $cap, $this->ID ), $args );
$caps = call_user_func_array( 'map_meta_cap', $args );
// Siêu quản trị viên đa trang web có tất cả các cap theo định nghĩa, trừ khi từ chối cụ thể.
nếu ( is_multisite() && is_super_admin( $this->ID ) ) {
nếu ( in_array('do_not_allow', $caps) )
trả về sai;
trả về đúng;
}

// Phải có TẢI CẢ các cap yêu cầu
$capabilities = apply_filters( 'user_has_cap', $this->allcaps, $caps, $args );
$capabilities['exist'] = true; // Mọi người đều được phép tồn tại
foreach ( (mảng) $caps as $cap ) {
//echo "Kiểm tra cap $cap
nếu ( trống( $capabilities[$cap] ) || !$capabilities[$cap] )
trả về sai;
}

trả về đúng;
}

