/**
* Làm sạch và xác thực đầu vào. Chấp nhận một mảng, trả về một mảng đã được làm sạch.
*/
function theme_options_validate( $input ) {
global $select_options, $radio_options;

// Giá trị của hộp kiểm của chúng tôi có thể là 0 hoặc 1
if ( ! isset( $input['option1'] ) )
$input['option1'] = null;
$input['option1'] = ( $input['option1'] == 1 ? 1 : 0 );

// Cho rằng tùy chọn văn bản của chúng tôi phải là văn bản an toàn không có thẻ HTML
$input['sometext'] = wp_filter_nohtml_kses( $input['sometext'] );

// Tùy chọn chọn của chúng tôi phải thực sự tồn tại trong mảng các tùy chọn chọn
if ( ! array_key_exists( $input['selectinput'], $select_options ) )
$input['selectinput'] = null;

// Tùy chọn radio của chúng tôi phải thực sự tồn tại trong mảng các tùy chọn radio
if ( ! isset( $input['radioinput'] ) )
$input['radioinput'] = null;
if ( ! array_key_exists( $input['radioinput'], $radio_options ) )
$input['radioinput'] = null;

// Cho rằng tùy chọn vùng văn bản của chúng tôi phải là văn bản an toàn với các thẻ được phép cho bài viết
$input['sometextarea'] = wp_filter_post_kses( $input['sometextarea'] );

return $input;
}

