Loại bỏ hỗ trợ Gravatar.com cho WordPress và Local Avatars Đơn giản Tôi hiện đang sử dụng Simple Local Avatars trên một số blog của tôi cho phép mọi người tải lên hình đại diện tùy chỉnh của họ. Theo như tôi biết thì Simple Local Avatars sử dụng hàm 'get_avatar' để kiểm tra xem có chọn hình đại diện tùy chỉnh hay không, nếu không sẽ mặc định là Gravatar.com. Có thể vô hiệu hóa phần Gravatar.com hay không, vô hiệu hóa hoàn toàn Gravatar.com và hiển thị hình ảnh lưu trữ cục bộ nếu không chọn hình đại diện tùy chỉnh? Tôi hy vọng là được đăng câu hỏi này ở đây, nhưng đây sẽ là tập tin của Simple Local Avatars

<?php
/*
Plugin Name: Simple Local Avatars
Plugin URI: http://www.get10up.com/plugins/simple-local-avatars-wordpress/
Description: Adds an avatar upload field to user profiles if the current user has media permissions. Generates requested sizes on demand just like Gravatar! Simple and lightweight.
Version: 1.2.3
Author: Jake Goldman (10up), Oomph Inc
Author URI: http://www.get10up.com/
*/
// thêm trường vào hồ sơ người dùng
class simple_local_avatars {
function simple_local_avatars() {
add_filter('get_avatar', array($this, 'get_avatar'), 10, 5);
add_action('admin_init', array($this, 'admin_init'));
add_action('show_user_profile', array($this, 'edit_user_profile'));
add_action('edit_user_profile', array($this, 'edit_user_profile'));
add_action('personal_options_update', array($this, 'edit_user_profile_update'));
add_action('edit_user_profile_update', array($this, 'edit_user_profile_update'));
add_filter('avatar_defaults', array($this, 'avatar_defaults'));
}
function get_avatar($avatar = '', $id_or_email, $size = '96', $default = '', $alt = false) {
if (is_numeric($id_or_email))
$user_id = (int) $id_or_email;
elseif (is_string($id_or_email)) {
if ($user = get_user_by_email($id_or_email))
$user_id = $user->ID;
} elseif (is_object($id_or_email) && !empty($id_or_email->user_id))
$user_id = (int) $id_or_email->user_id;
if (!empty($user_id))
$local_avatars = get_user_meta($user_id, 'simple_local_avatar', true);
if (!isset($local_avatars) || empty($local_avatars) || !isset($local_avatars['full'])) {
if (!empty($avatar)) // nếu được gọi bởi bộ lọc
return $avatar;
remove_filter('get_avatar', 'get_simple_local_avatar');
$avatar = get_avatar($id_or_email, $size, $default);
add_filter('get_avatar', 'get_simple_local_avatar', 10, 5);
return $avatar;
}
if (!is_numeric($size)) // đảm bảo kích thước hợp lệ
$size = '96';
if (empty($alt))
$alt = get_the_author_meta('display_name', $user_id);
// tạo ra kích thước mới
if (empty($local_avatars[$size])) {
$upload_path = wp_upload_dir();
$avatar_full_path = str_replace($upload_path['baseurl'], $upload_path['basedir'], $local_avatars['full']);
$image_sized = image_resize($avatar_full_path, $size, $size, true);
if (is_wp_error($image_sized)) // xử lý trường hợp kích thước gốc lớn hơn hoặc thiếu khả năng thay đổi kích thước
$local_avatars[$size] = $local_avatars['full'];
else
$local_avatars[$size] = str_replace($upload_path['basedir'], $upload_path['baseurl'], $image_sized);
update_user_meta($user_id, 'simple_local_avatar', $local_avatars);
} elseif (substr($local_avatars[$size], 0, 4) != 'http')
$local_avatars[$size] = site_url($local_avatars[$size]);
$author_class = is_author($user_id) ? ' current-author' : '';
$avatar = "<img alt='" . esc_attr($alt) . "' src='" . $local_avatars[$size] . "' class='avatar avatar-{$size}{$author_class} photo' height='{$size}' width='{$size}' />";
return $avatar;
}
