<?php
add_filter('posts_groupby', 'author_groupby');
function author_groupby($groupby) {
global $wpdb;
$author_groupby = "{$wpdb->posts}.post_author";
nếu (preg_match("/$author_groupby/", $groupby)) {
// nhóm chúng tôi cần đã có
trả về $groupby;
}
nếu (strlen(trim($groupby) == 0)) {
// groupby trống, dùng của chúng tôi
trả về $author_groupby;
}
trả về "$groupby, $author_groupby";
}
Tôi đã thử với mã sau nhưng không hoạt động:
