Thiết lập tiêu đề bài viết thông qua Meta Data trả về Auto-draft Tôi đã đọc ở đây và những nơi khác về việc thiết lập tiêu đề bài viết dựa trên metadata của nó. Thật không may, tôi không thể thực hiện được và hy vọng rằng ai đó có thể hướng dẫn tôi đến hướng đúng đắn hoặc giải thích cho tôi biết tôi đã sai ở đâu. Đây là mã của tôi:

add_filter( 'wp_insert_post_data', 'setup_match_title', 99, 2 );

function setup_match_title( $data, $postarr ) {
    if ( $data['post_type'] == 'matches' && $data['post_title'] == '' ) :
        $a = get_the_title( get_post_meta( $postarr['ID'], 'away_name', true ) );
        $h = get_the_title( get_post_meta( $postarr['ID'], 'home_name', true ) );
        $data['post_title'] = $a . ' vs ' . $h;
    endif;
    return $data;
}

