Hình X hoặc Hình Y dựa trên giá trị đầu vào Meta-Box Tôi đang xây dựng một trang web đánh giá phim và có một hộp meta cho mục đích này. Hộp meta của tôi có 3 trường: $director, $starring và $rating. Tôi muốn hiển thị hình ảnh dựa trên giá trị số trong trường $rating. Ví dụ, nếu $rating = 5 thì hiển thị hình ảnh 5 sao, nếu là 4 thì hiển thị hình ảnh 4 sao, v.v... Tôi đoán rằng tôi cần sử dụng câu lệnh if của PHP cho việc này, nhưng không chắc chắn cách thực hiện. Nếu ai có thể giúp tôi về mã nguồn thì rất cảm ơn. Mã nguồn của tôi cho hộp meta như sau:

function save_moviereview_meta($post_id, $post) {
    // Kiểm tra xem mã nonce có hợp lệ và được tạo ra bởi màn hình của chúng tôi hay không
    if ( !wp_verify_nonce( $_POST['moviereview_noncename'], plugin_basename(__FILE__) )) {
        return $post->ID;
    }

    // Kiểm tra xem người dùng có được phép chỉnh sửa bài viết hay không
    if ( !current_user_can( 'edit_post', $post->ID ))
        return $post->ID;

    // Lưu dữ liệu vào mảng để dễ dàng lặp qua các giá trị
    $moviereview_meta['_director'] = $_POST['_director'];
    $moviereview_meta['_starring'] = $_POST['_starring'];
    $moviereview_meta['_rating'] = $_POST['_rating'];

    // Thêm giá trị của $moviereview_meta vào trường tùy chỉnh
    foreach ($moviereview_meta as $key => $value) {
        if( $post->post_type == 'revision' )
            return; // Không lưu dữ liệu tùy chỉnh hai lần
        $value = implode(',', (array)$value); // Chuyển đổi giá trị thành dạng CSV nếu nó là một mảng
        if(get_post_meta($post->ID, $key, FALSE)) { // Nếu trường tùy chỉnh đã có giá trị
            update_post_meta($post->ID, $key, $value);
        } else { // Nếu trường tùy chỉnh chưa có giá trị
            add_post_meta($post->ID, $key, $value);
        }
        if(!$value)
            delete_post_meta($post->ID, $key); // Xóa trường nếu trống
    }
}

add_action('save_post', 'save_moviereview_meta', 1, 2); // Lưu các trường tùy chỉnh

gform_after_submission không hoạt động như mong đợi Tôi đang cố gắng tăng một giá trị cho bảng `wp_user_meta`, sử dụng Gravity Forms. Và tôi không may mắn chút nào cả. Tôi đã có một phiên bản của điều này hoạt động trên `gform_pre_submission` (mặc dù không có lớp-ngửi) nhưng tôi muốn làm điều này sau khi gửi vì sẽ có PayPal liên quan và không muốn đăng cho đến khi thanh toán được xác minh. Tôi đang cố gắng sử dụng cssClass làm bộ lọc để các nhà phát triển khác có thể tạo ra nhiều biểu mẫu Gravity như họ muốn, miễn là họ sử dụng các lớp `product_name` và `product_price`. Thật không may, cơ sở dữ liệu của tôi hiện đang bị tràn ngập với những sai sót.

// Gắn vào các biểu mẫu trọng lực và cập nhật trường lịch sử thanh toán

add_action('gform_after_submission', 'payment_history_handler', 10, 2);

function payment_history_handler($entry, $form){
    $current_user = wp_get_current_user();
    $payment_history = get_user_meta($current_user->ID, 'payment_history', true);

    foreach($form['fields'] as &$field){
        if(strpos($field['cssClass'], 'payment_name') === true){
            $payment_name = $entry[$field['id']];
        } else {
            $payment_name = 'fail';
        }

        if(strpos($field['cssClass'], 'payment_price') === true){
            $payment_price = $entry[$field['id']];
        } else {
            $payment_price = 1;
        }
    }

    if(!empty($payment_name) && !empty($payment_price)){
        $payment_history[] = array('date' => date('U'), 'name' => $payment_name, 'price' => $payment_price);
        update_user_meta($current_user->ID, 'payment_history', $payment_history);
    }
}

