jQuery.noConflict();

jQuery(function() {

// Lấy biểu mẫu.

var form = jQuery('#register-form');

// Lấy phần tử div tin nhắn

var formMessages = jQuery('#form-messages');

// Thiết lập trình nghe sự kiện cho biểu mẫu liên hệ

jQuery(form).submit(function(event) {

// Ngăn chặn trình duyệt gửi biểu mẫu

event.preventDefault();

// Xử lý dữ liệu biểu mẫu

var formData = jQuery(form).serialize();

jQuery.ajax({

type: 'POST',

url: jQuery(form).attr('action'),

data: formData

}).done(function(response) {

// Đảm bảo rằng phần tử div tin nhắn có lớp 'thành công'

jQuery(formMessages).removeClass('register-error');

jQuery(formMessages).addClass('register-success');

// Thiết lập văn bản tin nhắn

jQuery(formMessages).text(response);

// Xóa biểu mẫu

jQuery('#user_name').val('');

jQuery('#user_email').val('');

}).fail(function(data) {

// Đảm bảo rằng phần tử div tin nhắn có lớp 'lỗi'

jQuery(formMessages).removeClass('register-success');

jQuery(formMessages).addClass('register-error');

// Thiết lập văn bản tin nhắn

if(data.responseText !== '') {

jQuery(formMessages).text(data.responseText);

}else{

jQuery(formMessages).text('Ôi trời! Một lỗi đã xảy ra và yêu cầu của bạn không được gửi.');

}

});

});

