Cách ghi đè chức năng validate_plugin Tôi có thể ghi đè hàm validate_plugin của WordPress như thế nào? Tôi cần vô hiệu hóa riêng chức năng đó cho plugin của mình, và nó không nên ảnh hưởng đến bất kỳ plugin nào khác. Tôi không muốn sử dụng hàm validate_plugin cho plugin của mình vào lúc này, tôi không tìm thấy một hook được khai báo, do_action hoặc apply_filter, trong hàm trong file wp-admin/includes/plugin.php.

<?php
function run_activate_plugin( $plugin ) {
    $current = get_option( 'active_plugins' );
    $plugin = plugin_basename( trim( $plugin ) );

    if ( !in_array( $plugin, $current ) ) {
        $current[] = $plugin;
        sort( $current );
        do_action( 'activate_plugin', trim( $plugin ) );
        update_option( 'active_plugins', $current );
        do_action( 'activate_' . trim( $plugin ) );
        do_action( 'activated_plugin', trim( $plugin) );
    }

    return null;
}

run_activate_plugin( 'plugin/subfolder/plugin.php');

