function change_uploaded_image_html( $html ) {
    // Xóa thuộc tính chiều cao và chiều rộng từ hình ảnh khi chúng được tải lên.
    $classes = 'img-responsive';
    if ( preg_match( '/<img.*? class=".*?" \/>/', $html ) ) {
        $html = preg_replace( '/(<img.*? class=".*?)(".*?\/>)/', '$1 ' . $classes . '$2', $html );
    } else {
        $html = preg_replace( '/(<img.*?)\/>/', '$1 class="' . $classes . '" \/>', $html );
    }
    $html = preg_replace( '/(height|width)="\d*"\s/', "", $html );
    return $html;
}

Sau đó, tôi đã thử một phương pháp khác từ một bài đăng trên diễn đàn này thiết lập thuộc tính chiều rộng thành không có gì nhưng tôi không thành công vì thuộc tính chiều rộng và chiều cao trên hình ảnh vẫn còn:

function my_img_caption_shortcode_filter( $val, $attr, $content=null ){
    extract( shortcode_atts( array(
        'id'    => '',
        'align' => '',
        'width' => '',
        'caption' => ''
    ), $attr ) );

    if ( 1 > ( int ) $width || empty( $caption ) )
        return $val;

    $capid = '';
    if ( $id ) {
        $id = esc_attr( $id );
        $capid = 'id="figcaption_'. $id . '" ';
        $id = 'id="' . $id . '" aria-labelledby="figcaption_' . $id . '" ';
    }

    return '<figure ' . $id . 'class="wp-caption ' . esc_attr($align) . '" >'
    . do_shortcode( $content ) . '<figcaption ' . $capid
    . 'class="wp-caption-text">' . $caption . '</figcaption></figure>';
}

add_filter( 'img_caption_shortcode', 'my_img_caption_shortcode_filter',10 ,3 );

