add_filter( "manage_acme_products_posts_columns", "change_columns" );

// Cung cấp nội dung cho các cột mới
// Bên dưới tôi đã thay đổi 'get_post_meta' thành 'get_the_terms'
// Điều này được lấy từ một hướng dẫn khác để nhắm mục tiêu các Taxonomy thay vì post_meta
function custom_columns( $column, $post_id ) {
