Lặp lại vòng lặp vào hàm trả về? Tôi đang viết một hàm mã ngắn trả về một hình ảnh danh mục, liên kết đến danh mục, ba bài viết gần đây nhất trong danh mục đó, và một liên kết khác đến danh mục. Xem mã của tôi bên dưới:

add_shortcode('caticons_listing','bm_caticons_listing');

function bm_caticons_listing($atts) {
    extract( shortcode_atts( array(
        'include' => '',
        'exclude' => '',
        'small' => 'true'
    ), $atts ) );

    if ($atts['include']) $include = "&include=".$atts['include'];
    if ($atts['exclude']) $exclude = "&exclude=".$atts['exclude'];
    if ($atts['small'] == 'false') $small = "&small=false";

    $listing_code .= '<table class="cat-nav">';

    foreach(get_categories("orderby=name&order=ASC&hide_empty=0".$include.$exclude) as $category) {
        if (category_description($category->cat_ID)) { $desc = category_description($category->cat_ID); } else { $desc = "Coming soon!";}
        if ($category->count > 0) {
            $seemore = '<br /><a href="'.get_category_link( $category->term_id ).'">Xem thêm.</a>';
        } else { $seemore = '';}

        query_posts('cat='.$category->term_id.'&showposts=3');

        $listing_code .= '<tr><td>'.get_cat_icon("echo=false".$small."&class=caticon&cat=".$category->cat_ID).'</td><td valign="top" style="padding: 5px;"><a href="'.get_category_link( $category->term_id ).'"><h2 style="font-size: 130%;">'.$category->cat_name.'</h2></a>'.category_description($category->cat_ID).'<br />';

        // $listing_code .= "Tôi nghĩ tôi cần một vòng lặp ở đây.";

        $listing_code .= $seemore.'</td></tr>';
    }

    $listing_code .= '</table>';

    return $listing_code;
}

Vấn đề của tôi là, với cách các ví dụ vòng lặp WP được viết, tôi không thể tìm ra một cách tốt để đưa ra ba bài viết mới nhất như các liên kết theo một cách có thể được lưu trữ như một biến (để được trả về như đầu ra mã ngắn). Tôi rất mong nhận được sự giúp đỡ. Cảm ơn!

Cách bật hình thu nhỏ trong widget bảng điều khiển RSS Tôi đang sử dụng thành công fetch_feed() để hiển thị một nguồn cấp dữ liệu RSS bên trong một widget bảng điều khiển. Tuy nhiên, tôi không thể tải hình ảnh thu nhỏ từ các mục trong nguồn cấp dữ liệu. Tôi đang cố gắng thực hiện điều đó với phương thức get_image_url(), tuy nhiên WordPress đã báo lỗi về phương thức này là chưa được định nghĩa. Mã dưới đây...

function example_dashboard_widget_function() {
    // Hiển thị bất cứ thứ gì bạn muốn hiển thị
    $rss = fetch_feed( "http://localhost/testsite/wp-content/test.rss" );

    if ( is_wp_error($rss) ) {
        if ( is_admin() || current_user_can('manage_options') ) {
            echo '<p>';
            printf(__('<strong>RSS Error</strong>: %s'), $rss->get_error_message());
            echo '</p>';
        }
        return;
    }

    if ( !$rss->get_item_quantity() ) {
        echo '<p>Không có mục nào trong nguồn cấp dữ liệu để hiển thị!</p>';
        $rss->__destruct();
        unset($rss);
        return;
    }

    echo "<ul>\n";
    if ( !isset($items) )
        $items = 10;

    foreach ( $rss->get_items(0, $items) as $item ) {
        $publisher = '';
        $site_link = '';
        $link = '';
        $content = '';
        $date = '';
        $image = '';

        $image = $item->get_image_url(); //
        //$image = esc_url( strip_tags( $item->get_thumbnail() ) );
        $link = esc_url( strip_tags( $item->get_link() ) );
        $content = $item->get_content();

        $content = wp_html_excerpt($content, 250) . ' ...';

        echo "<li><img src='$image' /><a href='$link'>$link</a> - $content</li>\n";
    }

    echo "</ul>\n";

    $rss->__destruct();
    unset($rss);
}

