Vấn đề là tôi đã chỉnh sửa 'wp_set_auth_cookie()' và 'wp_clear_auth_cookie()', tham khảo từ codex: http://codex.wordpress.org/Function_Reference/wp_set_auth_cookie

Hàm này nằm trong một tệp lõi: wp-includes/pluggable.php

Tôi nghĩ rằng wp_set_auth_cookie() phải là vấn đề chính, vui lòng kiểm tra mã:

Phiên bản gốc

hàm wp_set_auth_cookie($user_id, $remember = false, $secure = '') {
nếu ($remember) {
$expiration = thời gian() + áp dụng bộ lọc ('auth_cookie_expiration', 14 * DAY_IN_SECONDS, $user_id, $remember);
// Đảm bảo trình duyệt sẽ tiếp tục gửi cookie sau khi thời gian hết hạn được đạt đến.
// Cần thiết cho thời gian ân hạn đăng nhập trong wp_validate_auth_cookie().
$hết hạn = $expiration + (12 * HOUR_IN_SECONDS);
} khác {
$expiration = thời gian() + áp dụng bộ lọc ('auth_cookie_expiration', 2 * DAY_IN_SECONDS, $user_id, $remember);
$hết hạn = 0;
}
nếu (' ' === $secure)
$secure = is_ssl();
$secure = áp dụng bộ lọc ('secure_auth_cookie', $secure, $user_id);
$secure_logged_in_cookie = áp dụng bộ lọc ('secure_logged_in_cookie', false, $user_id, $secure);
nếu ($secure) {
$auth_cookie_name = SECURE_AUTH_COOKIE;
$scheme = 'secure_auth';
} khác {
$auth_cookie_name = AUTH_COOKIE;
$scheme = 'auth';
}
$auth_cookie = wp_generate_auth_cookie($user_id, $expiration, $scheme);
$logged_in_cookie = wp_generate_auth_cookie($user_id, $expiration, 'logged_in');
làm hành động ('set_auth_cookie', $auth_cookie, $expire, $expiration, $user_id, $scheme);
làm hành động ('set_logged_in_cookie', $logged_in_cookie, $expire, $expiration, $user_id, 'logged_in');
setcookie ($auth_cookie_name, $auth_cookie, $expire, PLUGINS_COOKIE_PATH, COOKIE_DOMAIN, $secure, true);
setcookie ($auth_cookie_name, $auth_cookie, $expire, ADMIN_COOKIE_PATH, COOKIE_DOMAIN, $secure, true);
setcookie (LOGGED_IN_COOKIE, $logged_in_cookie, $expire, COOKIEPATH, COOKIE_DOMAIN, $secure_logged_in_cookie, true);
nếu (COOKIEPATH! = SITECOOKIEPATH)
setcookie (LOGGED_IN_COOKIE, $logged_in_cookie, $expire, SITECOOKIEPATH, COOKIE_DOMAIN, $secure_logged_in_cookie, true);
}
