function lishortcode($liatts) {
extract(shortcode_atts(array(
"li" => get_option('li'),
), $liatts));
foreach ($liatts as $key => $option) {
$li[$key] = $option;
}
$lib=$li[URL];
return $lib;
}
add_filter('widget_text', 'do_shortcode');
