Làm thế nào để một php script chạy chỉ với wp-cron Tôi có một script PHP thực thi một hàm và tạo ra một tập tin XML với kết quả. Tôi muốn chạy script này chỉ một lần mỗi ngày và tôi đang sử dụng wordpress cron để làm điều này. Vấn đề là script này luôn chạy trên tất cả các trang tải và điều này không tốt vì nó mất hơn 30 giây để hoàn tất. Tôi có thể ngăn nó chạy liên tục và làm cho nó chỉ hoạt động với wp-cron? Tôi đã đọc về cronjob nhưng nhà cung cấp hosting của tôi không hỗ trợ tính năng này. Đây là mã tôi sử dụng ở đầu tệp PHP của tôi:

add_action('my_cron_hook', 'myfunction');
if (!wp_next_scheduled('my_cron_hook')) {
wp_schedule_event(time(), 'daily', 'my_cron_hook');
}
register_deactivation_hook(__FILE__, 'my_deactivate');
function my_deactivate() {
$timestamp = wp_next_scheduled('my_cron_hook');
wp_unschedule_event($timestamp, 'my_cron_hook');
}
Tôi muốn script chạy hàng ngày và luôn ở chế độ nền, nó không nên ảnh hưởng đến việc điều hướng của người dùng. Cảm ơn. Sửa đổi. Đây là toàn bộ mã script:

add_action('cO_cron_hook', 'remoteHeader');
if (!wp_next_scheduled('cO_cron_hook')) {
wp_schedule_event(time() + 24 * 60 * 60, 'daily', 'cO_cron_hook');
}
register_deactivation_hook(__FILE__, 'bl_deactivate');
function bl_deactivate() {
$timestamp = wp_next_scheduled('cO_cron_hook');
wp_unschedule_event($timestamp, 'cO_cron_hook');
}
set_time_limit(300);
function remoteHeader($url) {
$online = 'online';
$offline = 'offline';
$agent = "Mozilla/5.0 (compatible; MSIE 9.0; Windows NT 6.1; Win64; x64; Trident/5.0)";
$ch = curl_init();
curl_setopt($ch, CURLOPT_URL, $url);
curl_setopt($ch, CURLOPT_USERAGENT, $agent);
curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
curl_setopt($ch, CURLOPT_VERBOSE, false);
curl_setopt($ch, CURLOPT_TIMEOUT, 10);
curl_setopt($ch, CURLOPT_NOBODY, 1);
curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, FALSE);
curl_setopt($ch, CURLOPT_SSLVERSION, 3);
curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, FALSE);
curl_exec($ch);
$httpcode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
curl_close($ch);
if ($httpcode >= 200 && $httpcode < 400) return $online;
else return $httpcode;
}
