Hiện tại tôi đang sử dụng `search.php`; `$_POST["type"]` để xác định xem đã có loại tìm kiếm nào được sử dụng và `$_POST["s"]` cho thuật ngữ truy vấn:

<?php
if (isset($_POST["s"])) {
  $search_term = $_POST["s"];
}
if (isset($_POST["type"])) {
  switch ($_POST["type"]) {
    case "profile":
      $post_type = "species";
      break;
    case "glossary":
      $post_type = "glossary";
      break;
    default:
      $post_type = array( 'post', 'species' );
      break;
  }
} else {
  $post_type = array( 'post', 'species' );
}
$args = array(
  's' => $search_term,
  'post_type' => $post_type
);
