// Hàm gọi lại

function show_custom_meta_box() {
    global $custom_meta_fields, $post;

    // Sử dụng nonce để xác minh
    echo '<input type="hidden" name="custom_meta_box_nonce" value="' . wp_create_nonce(basename(__FILE__)) . '" />';

    // Bắt đầu bảng trường và lặp qua từng trường
    echo '<table class="form-table">';
    foreach ($custom_meta_fields as $field) {
        // Lấy giá trị của trường này nếu nó tồn tại trong bài viết hiện tại
        $meta = get_post_meta($post->ID, $field['id'], true);

        // Bắt đầu một dòng bảng với
        echo '<tr>
            <th><label for="' . $field['id'] . '">' . $field['label'] . '</label></th>
            <td>';

        // Sử dụng chuyển đổi để hiển thị trường theo kiểu của nó
        switch ($field['type']) {

            // Các trường khác sẽ được thêm vào đây

            // Chọn
            case 'select':
                echo '<select name="' . $field['id'] . '" id="' . $field['id'] . '">';
                foreach ($field['options'] as $option) {
                    echo '<option', $meta == $option['value'] ? ' selected="selected"' : '', ' value="' . $option['value'] . '">' . $option['label'] . '</option>';
                }
                echo '</select><br /><span class="description">' . $field['desc'] . '</span>';
                break;
        }

        echo '</td></tr>';
    }

    echo '</table>'; // Kết thúc bảng
}

// Lưu dữ liệu

function save_custom_meta($post_id) {
    global $custom_meta_fields;

    // Xác minh nonce
    if (!wp_verify_nonce($_POST['custom_meta_box_nonce'], basename(__FILE__)))
        return $post_id;

    // Kiểm tra lưu tự động
    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE)
        return $post_id;

    // Kiểm tra quyền truy cập
    if ('page' == $_POST['post_type']) {
        if (!current_user_can('edit_page', $post_id))
            return $post_id;
    } elseif (!current_user_can('edit_post', $post_id)) {
        return $post_id;
    }

    // Lặp qua các trường và lưu dữ liệu
    foreach ($custom_meta_fields as $field) {
        $old = get_post_meta($post_id, $field['id'], true);
        $new = $_POST[$field['id']];

        if ($new && $new != $old) {
            update_post_meta($post_id, $field['id'], $new);
        } elseif ('' == $new && $old) {
            delete_post_meta($post_id, $field['id'], $old);
        }
    }
}

add_action('save_post', 'save_custom_meta');

