Cách tự động thay đổi trạng thái bài viết thành bản nháp dựa trên trường tùy chỉnh Tôi muốn tự động lưu bài viết dưới dạng nháp dựa trên một trường tùy chỉnh. Lưu ý: **tôi đang sử dụng plugin Magic Fields.** Dựa trên đoạn mã sau, tôi muốn sử dụng trường tùy chỉnh "hết hạn" để đặt ngày hết hạn cho bài viết.

function sfn_show_expire() {
    global $wpdb;
    $server_time = date('mdy');
    $result = $wpdb->get_results("SELECT * FROM wp_posts WHERE post_type = 'show' AND post_status = 'publish'");
    if( !empty($result)) {
        foreach ($result as $a) {
            $show_time = get_the_time('mdy', $a->ID );
            if ( $server_time > $show_time) {
                $my_post = array();
                $my_post['ID'] = $a->ID;
                $my_post['post_status'] = 'draft';
                wp_update_post( $my_post );
            }
        } // end foreach
    }
}

add_action( 'init', 'sfn_show_expire' );

