Sử dụng trường tùy chỉnh trong URL của Custom Post Type Tôi đang phát triển một trang web về xe hơi có phòng trưng bày. Mỗi phòng trưng bày cần có URL riêng tùy chỉnh dựa trên địa điểm của nó. Địa điểm (thành phố và quận/tỉnh) đã được chèn như hai trường tùy chỉnh. Vì vậy, ví dụ, nếu đó là "Phòng trưng bày A", nằm ở Liverpool, Merseyside, URL của nó sẽ là: http://www.domain.com/location/merseyside/liverpool/showroom-a/ Tôi có một loại bài viết tùy chỉnh là "Showroom", có quy tắc ghi lại được đặt thành false (mặc dù trước đây nó đã được đặt thành true trong quá trình thử nghiệm). Tuy nhiên khi tôi tạo bài viết đó, có một vấn đề xảy ra. Mã liên kết vĩnh viễn được cung cấp là mọi thứ TRỪ tên của phòng trưng bày (ví dụ: http://www.domain.com/location/merseyside/liverpool/). Truy cập vào URL này sẽ gây ra lỗi 404, và ngay cả khi thêm "showroom-a" (ví dụ) vào cuối mã (http://www.domain.com/location/merseyside/liverpool/showroom-a/), cũng gây ra lỗi 404. Đây là mã của tôi:

function add_rewrite_rules()
{
// Đăng ký các quy tắc ghi lại tùy chỉnh
global $wp_rewrite;
$wp_rewrite->add_rewrite_tag('%showroom%', '([^/]+)', 'showroom=');
$wp_rewrite->add_rewrite_tag('%post_custom_data%', '([^/]+)', 'post_custom_data=');
$wp_rewrite->add_permastruct('showroom', 'location/%post_custom_data%', false);
}

function permalinks($permalink, $post, $leavename)
{
$no_data = 'no-data';
$post_id = $post->ID;

if ($post->post_type != 'showroom' || empty($permalink) || in_array($post->post_status, array('draft', 'pending', 'auto-draft')))
return $permalink;

$state = sanitize_title_with_dashes(get_post_meta($post_id, 'state', true));
$city = sanitize_title_with_dashes(get_post_meta($post_id, 'city', true));
$data = $state . "/" . $city;

if (!$data)
$data = $no_data;

$permalink = str_replace('%post_custom_data%', $data, $permalink);

return $permalink;
}

add_action('init', 'add_rewrite_rules');
add_filter('post_type_link', 'permalinks', 10, 3);

Tôi rất mong nhận được ý tưởng hoặc sự giúp đỡ từ các bạn :)

Dùng cùng một cấu trúc permalink dựa trên ngày cho mọi loại bài viết Có cách nào để sử dụng cùng một cấu trúc permalink dựa trên ngày cho tất cả các loại bài viết (không theo thứ tự phân cấp) trên một trang web, bao gồm bài viết và các loại bài viết tùy chỉnh không? Tôi muốn tất cả các loại bài viết có định dạng `/%year%/%monthnum%/%day%/%postname%/`, để loại bài viết không xuất hiện trong URL. Với cấu trúc permalink mặc định của loại bài viết tùy chỉnh, đoạn mã sau đây đã thành công trong việc xóa loại bài viết khỏi permalink (với rủi ro gây ra xung đột tên bài viết, nhưng tôi có thể chấp nhận điều đó), nhưng tôi không biết phải làm gì để thiết lập permalink sử dụng cấu trúc ngày.

class simons_permalinks {
function __construct() {
add_action( 'pre_get_posts',  array( $this, 'pre_remove_slug' ) );
add_filter( 'post_type_link', array( $this, 'remove_slug' ), 10, 3 );
}
function pre_remove_slug( $query ) {
if ( ! $query->is_main_query() )
return;
if ( 2 != count( $query->query ) or !isset( $query->query[ 'page' ] ) )
return;
$types = array( 'page', 'post', 'feature', 'opinion' );
if ( ! empty( $query->query[ 'name' ] ) ) {
$query->set( 'post_type', $types );
}
}
function remove_slug( $link, $post, $name ) {
$types = array( 'post', 'feature', 'opinion' );
if ( 'post' != $post->post_type and in_array( $post->post_type, $types ) and 'publish' == $post->post_status ) {
$pto = get_post_type_object( $post->post_type );
$link = str_replace( '/' . $pto->rewrite[ 'slug' ] . '/', '/', $link );
}
return $link;
}
}
