add_action('save_post', 'save_front_page_slideshow_option');

endif;

/**
* Lưu các giá trị từ metabox 'Bao gồm trong Front Page Sideshow' khi người dùng Cập Nhật media
*/
function save_front_page_slideshow_option($post_id){
echo '<pre>'; print_r($_POST); echo '</pre>';
die();

/** Kiểm tra nonce bảo mật để đảm bảo chúng ta có quyền ủy quyền thích hợp */
