Tạo một Mega Menu Hiện tại tôi đang tạo một chủ đề dựa trên BootStrap 3.0. Và thiết kế mà tôi đã lên ý tưởng sử dụng một thanh điều hướng Mega Menu. Hiện tại tôi đang cố gắng thêm YAMM3 - Yet Another Mega Menu for Bootstrap 3, tuy nhiên tôi chưa quen với việc thực hiện bất cứ điều gì ngoài một menu thả xuống đơn giản trong WordPress. Ai có thể hướng dẫn hoặc chỉ cho tôi thấy hướng đi đúng đắn để bắt đầu không? Tôi đã tạo một chủ đề BootStrap 3, tôi chỉ bị lạc lối về cách thêm Mega Menu một cách chính xác. Cảm ơn Chỉnh sửa: Đây là những gì tôi hiện có, chỉ hiển thị một menu điều hướng BootStrap 3 đáp ứng thông thường.

class Cwd_wp_bootstrapwp_Walker_Nav_Menu extends Walker_Nav_Menu {

function display_element ($element, &$children_elements, $max_depth, $depth = 0, $args, &$output) {
// kiểm tra xem có con nào cho ID được cho và thêm nó vào phần tử với một (mới) ID
$element->hasChildren = isset($children_elements[$element->ID]) && !empty($children_elements[$element->ID]);

return parent::display_element($element, $children_elements, $max_depth, $depth, $args, $output);
}

// ĐỔI .sub-menu thành .dropdown-menu

function start_lvl(&$output, $depth) {
$indent = str_repeat("\t", $depth);
$output .= "\n$indent<ul class=\"dropdown-menu\">";
}

function start_el(&$output, $item, $depth = 0, $args = array(), $id = 0) {
$item_html = '';
parent::start_el($item_html, $item, $depth, $args);
$output .= sprintf('<small>%s</small>', esc_html($item->description));

if (($item->hasChildren) && ($depth === 0)) {
$item_html = str_replace('<a', '<a class="dropdown-toggle" data-toggle="dropdown" data-target="#"', $item_html);
$item_html = str_replace('</a>', ' <b class="caret"></b></a>', $item_html);
}

$output .= $item_html;
}

}

function cwd_wp_bootstrapwp_nav_menu_css_class($classes, $item) {
// ĐỔI .current-menu-item .current-menu-parent .current-menu-ancestor thành .active
$classes = preg_replace('/(current(-menu-|[-_]page[-_])(item|parent|ancestor))/', 'active', $classes);

// Thêm lớp .dropdown vào các mục danh sách có con
if ($item->hasChildren) {
$classes[] = 'dropdown';
//$classes[] = 'yamm-fw';
}

return $classes;
}

add_filter('nav_menu_css_class', 'cwd_wp_bootstrapwp_nav_menu_css_class', 10, 2);

