Chuyển đổi một plugin đơn giản để đặt bên trong của functions.php Trước tiên, tôi biết rằng việc sử dụng các plugin riêng biệt tốt hơn là tích hợp chúng vào functions.php nhưng đây là một theme framework sẽ được triển khai trên nhiều trang web và việc đóng gói nó như một phần của theme sẽ dễ dàng hơn. Tôi đang gặp khó khăn khi sử dụng mã sau từ plugin tại địa chỉ này. Kiến thức PHP của tôi còn hạn chế, tôi đã thử sao chép và dán mã trực tiếp nhưng không hoạt động, nhưng lại hoạt động tốt khi sử dụng như một plugin.

class Filosofo_Custom_Image_Sizes {
public function __construct()
{
add_filter('image_downsize', array(&$this, 'filter_image_downsize'), 99, 3);
}
/**
* Hàm gọi lại cho bộ lọc "image_downsize".
*
* @param bool $ignore Một giá trị nhằm loại bỏ thông tin chưa được lọc trả về từ bộ lọc này.
* @param int $attachment_id ID của file đính kèm mà chúng ta muốn một kích thước nhất định.
* @param string $size_name Tên của kích thước mong muốn.
*/
public function filter_image_downsize($ignore = false, $attachment_id = 0, $size_name = 'thumbnail')
{
global $_wp_additional_image_sizes;
$attachment_id = (int) $attachment_id;
$size_name = trim($size_name);
$meta = wp_get_attachment_metadata($attachment_id);
/* kích thước yêu cầu chưa tồn tại cho file đính kèm này */
if (
empty( $meta['sizes'] ) ||
empty( $meta['sizes'][$size_name] )
) {
// trước tiên, hãy xem liệu đây có phải là một kích thước đã đăng ký hay không
if ( isset( $_wp_additional_image_sizes[$size_name] ) ) {
$height = (int) $_wp_additional_image_sizes[$size_name]['height'];
$width = (int) $_wp_additional_image_sizes[$size_name]['width'];
$crop = (bool) $_wp_additional_image_sizes[$size_name]['crop'];
// nếu không, hãy kiểm tra xem tên có dạng [chiều rộng]x[chiều cao] hay không và sử dụng nó để cắt xén
} else if ( preg_match('#^(\d+)x(\d+)$#', $size_name, $matches) ) {
$height = (int) $matches[2];
$width = (int) $matches[1];
$crop = true;
}
if ( ! empty( $height ) && ! empty( $width ) ) {
$resized_path = $this->_generate_attachment($attachment_id, $width, $height, $crop);
$fullsize_url = wp_get_attachment_url($attachment_id);
$file_name = basename($resized_path);
$new_url = str_replace(basename($fullsize_url), $file_name, $fullsize_url);
if ( ! empty( $resized_path ) ) {
$meta['sizes'][$size_name] = array(
'file' => $file_name,
'width' => $width,
'height' => $height,
);
wp_update_attachment_metadata($attachment_id, $meta);
return array(
$new_url,
$width,
$height,
true
);
}
}
}
return false;
}
/**
* Tạo ra một phiên bản cắt xén của hình ảnh cho một ID file đính kèm nhất định.
*
* @param int $attachment_id File đính kèm để tạo ra hình ảnh cắt xén.
* @param int $width Chiều rộng của hình ảnh cắt xén tính bằng pixel.
* @param int $height Chiều cao của hình ảnh cắt xén tính bằng pixel.
* @param bool $crop Cho biết có nên cắt xén hình ảnh được tạo ra hay không.
* @return string Đường dẫn đầy đủ đến hình ảnh cắt xén. Trống nếu thất bại.
*/
private function _generate_attachment($attachment_id = 0, $width = 0, $height = 0, $crop = true)
{
$attachment_id = (int) $attachment_id;
$width = (int) $width;
$height = (int) $height;
$crop = (bool) $crop;
$original_path = get_attached_file($attachment_id);
// sửa lỗi của WP lên đến 2.9.2
if ( ! function_exists('wp_load_image') ) {
require_once ABSPATH . 'wp-admin/includes/image.php';
}
$resized_path = @image_resize($original_path, $width, $height, $crop);
if (
! is_wp_error($resized_path) &&
! is_array($resized_path)
) {
return $resized_path;
// có thể hình ảnh này đã tồn tại. Nếu đúng, hãy trả về nó.
} else {
$orig_info = pathinfo($original_path);
$suffix = "{$width}x{$height}";
$dir = $orig_info['dirname'];
$ext = $orig_info['extension'];
$name = basename($original_path, ".{$ext}");
$destfilename = "{$dir}/{$name}-{$suffix}.{$ext}";
if ( file_exists( $destfilename ) ) {
return $destfilename;
}
}
return '';
}
}
function initialize_custom_image_sizes()
{
new Filosofo_Custom_Image_Sizes;
}
add_action('plugins_loaded', 'initialize_custom_image_sizes');
