    function dynamic_save_postdata( $post_id ) {
        // Kiểm tra xem đây có phải là quy trình tự động lưu hay không.

        // Nếu nó là, biểu mẫu của chúng tôi chưa được gửi, vì vậy chúng tôi không muốn làm gì cả
        if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE )
            return $post_id;

        // Kiểm tra xem nó có đến từ màn hình của chúng tôi và với quyền ủy quyền thích hợp hay không,

        // vì save_post có thể được kích hoạt vào những thời điểm khác
        if ( !isset( $_POST['dynamicMeta_noncename'] ) )
            return;

        if ( !wp_verify_nonce( $_POST['dynamicMeta_noncename'], plugin_basename( __FILE__ ) ) )
            return;

        // OK, chúng tôi đã được xác thực: chúng tôi cần tìm và lưu dữ liệu

        $ourwork = $_POST['ourwork'];

        update_post_meta($post_id,'ourwork',$ourwork);
    }

Không thể cập nhật một tùy chọn khi hành động publish_post được kích hoạt. Tôi đang sử dụng plugin của Tom McFarlin và đang gặp phải một vấn đề lớn là không thể cập nhật một tùy chọn khi hành động `publish_post` được kích hoạt. Tôi có một hàm kết nối với hành động xuất bản bài viết và tất cả những gì nó làm là cập nhật một tùy chọn. Đây không phải là nhiệm vụ ban đầu của tôi. Điều tôi muốn làm là gọi một hàm riêng từ bên trong hàm trên, sẽ cập nhật tùy chọn. Điều đó không thành công nên tôi bắt đầu cập nhật tùy chọn từ bên trong hàm công khai chính nó. Đây là mã, và nếu ai đó có thể giúp tôi không chỉ về vấn đề này mà còn cách sử dụng hàm riêng thì thật tuyệt vời.

PS: Lọc `the_content` hoạt động, nhưng hành động `publish_post` không hoạt động. Tôi đã để lại dòng gọi hàm riêng bị bình luận, để bạn có thể kiểm tra hai vấn đề của tôi riêng biệt.

