$wpdb class cập nhật meta_value sử dụng Ajax Tôi đang cố gắng tạo ra một cách để thay đổi thứ tự bài viết sử dụng meta_key / meta_value được cập nhật bằng jQuery ui-sortable. Tôi đã sử dụng menu_order theo cùng một cách nhưng cần tạo ra một cách để xem trước thứ tự mới trước khi lưu các giá trị menu_order mới. Đây là hàm Ajax mà tôi đang sử dụng nhưng không hoạt động:

function wnd_preview_item_order() {
    global $wpdb;
    $order = explode(',', $_POST['order']);
    $counter = 0;
    foreach ($order as $item_id) {
        $wpdb->update($wpdb->postmeta, array(
            'meta_key' => '_wnd_pre_order',
            'meta_value' => $counter
        ), array(
            'ID' => $item_id
        ) );
        $counter++;
    }
    die(1);
}
add_action('wp_ajax_item_sort', 'wnd_preview_item_order');
add_action('wp_ajax_nopriv_item_sort', 'wnd_preview_item_order');

