function wnd_save_item_order() {
    global $wpdb;
    $order = explode(',', $_POST['order']);
    $counter = 0;
    foreach ($order as $item_id) {
        $wpdb->update($wpdb->posts, array(
            'menu_order' => $counter
        ), array(
            'ID' => $item_id
        ) );
        $counter++;
    }
    die(1);
}

