Làm thế nào để tạo một liên kết cố định cho plugin tùy chỉnh Tôi viết một plugin đơn giản sẽ chuyển hướng người dùng đến một trang vào một ngày nhất định. (trong trường hợp này là cho Blackout chống lại SOPA ở Mỹ) Hiện tại tôi đang sử dụng dòng `wp_redirect(plugins_url('simple-sopa-blackout/blackout.php'),302);` để chuyển hướng người dùng vào ngày đã cho. Vấn đề là nó tạo ra một URL xấu như `http://example.net/wp-content/plugins/simple-blackout/blackout.php` Sẽ thật tuyệt nếu chỉ làm cho nó thành `http://example.net/blackout` Tôi đã thử cái mà tôi nghĩ là Codex đúng với đoạn mã sau:

add_filter('rewrite_rules_array','my_insert_rewrite_rules');
add_action('wp_loaded','my_flush_rules');
// flush_rules() nếu các quy tắc của chúng tôi chưa được bao gồm
function my_flush_rules(){
$rules = get_option('rewrite_rules');
if (!isset($rules['blackout/?$'])) {
global $wp_rewrite;
$wp_rewrite->flush_rules();
}
}

// Thêm một quy tắc mới
function my_insert_rewrite_rules($rules){
$newrules = array();
$newrules['blackout/?$'] = plugins_url('simple-sopa-blackout/blackout.php');
return $newrules + $rules;
}

