function cd_meta_box_save( $post_id ) {
// Ngừng nếu đây là một bản tự động lưu
if( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) return;

// Nếu mã bảo mật của chúng tôi không tồn tại hoặc không hợp lệ, hãy dừng lại
if( !isset( $_POST['meta_box_nonce'] ) || !wp_verify_nonce( $_POST['meta_box_nonce'], 'my_meta_box_nonce' ) ) return;

// Nếu người dùng hiện tại không có quyền chỉnh sửa bài viết này, hãy dừng lại
if( !current_user_can( 'edit_post' ) ) return;

// Bây giờ chúng ta có thể thực sự lưu dữ liệu
$allowed = array(
'a' => array( // Chỉ cho phép thẻ a
'href' => array() // và những neo này chỉ có thể có thuộc tính href
)
);

// Có lẽ là một ý tưởng tốt để đảm bảo dữ liệu của bạn được thiết lập
if( isset( $_POST['meta_box_title'] ) )
update_post_meta( $post_id, 'meta_box_title', wp_kses( $_POST['meta_box_title'], $allowed ) );

if( isset( $_POST['meta_box_director'] ) )
update_post_meta( $post_id, 'meta_box_director', wp_kses( $_POST['meta_box_director'], $allowed ) );

if( isset( $_POST['meta_box_desc'] ) )
update_post_meta( $post_id, 'meta_box_desc', wp_kses( $_POST['meta_box_desc'], $allowed ) );
}
?>

