3. Cuối cùng, đây là hàm thực hiện việc đăng ký và được đặt tên theo tên của nút đăng nhập (checkFB.php)

// Đừng lo lắng, tôi không muốn hiển thị mã này trên http://wordpress.stackexchange.com/!
require_once('/this_is_the_path_to_my_server_/wp-load.php');
require_once('/this_is_the_path_to_my_server_/wp-config.php');

/*
$_REQUEST được gửi kèm với 2 mảng. Chúng ta sẽ lấy ID và bắt đầu kiểm tra.
*/
$login = $_REQUEST['userResp']['id'];

// Kiểm tra xem tên người dùng đã tồn tại hay chưa
$id = username_exists($login);
$errors = array();

// Trường hợp 1: Khi ID không tồn tại
if(!$id) {
    $email = $_REQUEST['userResp']['email'];
    $existingID = email_exists($email);

    // Trường hợp 1 được xác nhận: Nếu email cũng không tồn tại, chúng ta có thể tiến hành đăng ký
    if(!$existingID) {
        $pass = wp_generate_password( $length=12, $include_standard_special_chars=false );
        $userData = array();
        $userData['user_login'] = $login;
        $userData['user_email'] = $email;
        $userData['user_password'] = $pass;
        $userData['user_nicename'] = $_REQUEST['userResp']['first_name'] .' '. $_REQUEST['userResp']['last_name'];
        $userData['first_name'] = $_REQUEST['userResp']['first_name'];
        $userData['last_name'] = $_REQUEST['userResp']['last_name'];
        $insertStatus = wp_insert_user($userData);

        if(is_wp_error($insertStatus)) {
            $errors = array_merge($errors, $insertStatus->getErrorMessages());
        }
        else {
            wp_set_auth_cookie($insertStatus, true);
        }
    }

    // Trường hợp 2: Khi ID email mà người dùng đã gắn với tài khoản Facebook của họ cũng đã được đăng ký ở đây
    else {
        $userFB = get_user_meta($existingID, 'fbid', true);

        // Nếu một người dùng đã được gắn với email đó
        if(!empty($userFB)) {

            // Trường hợp 2a: Ở đây, chúng ta so khớp ID Facebook của người dùng với ID Facebook của ID email
            if($userFB == $login)
                wp_set_auth_cookie($existingID, true);
            else {
                array_push($errors, __("Có vẻ như đã có một ID Facebook khác được gắn với tài khoản của bạn. Vui lòng kiểm tra lại."));
            }
        }

        // Tạo liên kết giữa ID email của người dùng và ID Facebook lần đầu tiên và đăng nhập cho họ
        else {
            if(!add_user_meta($existingID, 'fbid', $login, true)) {
                array_push($errors, __("Xin lỗi! Chúng tôi không thể liên kết tài khoản Facebook của bạn."));
            }
            else {
                wp_set_auth_cookie($existingID, true);
            }
        }
    }
}

// Trường hợp 3: Khi người dùng đã được đăng ký
else {
    wp_set_auth_cookie($id, true);
}

$resp = array();
if(!count($errors)) {
    $resp['status'] = "Success";
    $resp['loggedIn'] = true;
    $resp['errors'] = $errors;
}
else {
    $resp['status'] = "Failure";
    $resp['loggedIn'] = false;
    $resp['errors'] = $errors;
}
echo "reply(".json_encode($resp).")";

