Get_terms có trường tùy chỉnh được kiểm tra Tôi đã thêm một trường tùy chỉnh, được gọi là `sticky`, vào một danh mục tùy chỉnh sử dụng plugin wp taxonomy meta, như sau:

function YOUR_PREFIX_register_taxonomy_meta_boxes() {
    // Đảm bảo không có lỗi khi plugin bị vô hiệu hóa hoặc trong quá trình nâng cấp
    if ( ! class_exists( 'RW_Taxonomy_Meta' ) )
        return;

    $meta_sections = array();

    // Phần meta đầu tiên
    $meta_sections[] = array(
        'title' => 'Sticky', // tiêu đề phần
        'taxonomies' => array('tvr_amenity'), // danh sách các danh mục. Mặc định là mảng ('category', 'post_tag'). Tùy chọn
        'id' => 'sticky', // ID của mỗi phần, sẽ là tên tùy chọn
        'fields' => array(
            // Danh sách các trường meta
            array(
                'name' => 'Hiển thị trong bộ lọc trang chủ',
                'id' => 'sticky',
                'type' => 'checkbox',
            ),
        ),
    );

    foreach ( $meta_sections as $meta_section ) {
        new RW_Taxonomy_Meta( $meta_section );
    }
}

Bây giờ tôi đang cố gắng lấy tất cả các danh mục có giá trị này được đánh dấu, như sau:

