Tìm kiếm mặc định của tôi không hoạt động Tôi đang sử dụng một hàm để tìm kiếm `post_meta` mà tôi lưu trữ với mỗi bài đăng, nhưng vấn đề là khi tôi tìm kiếm `title`, `tags`, nội dung thì tìm kiếm không hoạt động. Tôi nghĩ hàm mới của tôi chỉ ghi đè lên tính năng tìm kiếm mặc định của WordPress. Đây là mã của tôi:

function custom_search_query( $query ) {
    $custom_fields = array(
        // put all the meta fields you want to search for here
        "post_state",
        "post_region",
        "post_country"
    );
    $searchterm = $query->query_vars['s'];
    // we have to remove the "s" parameter from the query, because it will prevent the posts from being found
    $query->query_vars['s'] = "";
    if ($searchterm != "") {
        $meta_query = array('relation' => 'OR');
        foreach($custom_fields as $cf) {
            array_push($meta_query, array(
                'key' => $cf,
                'value' => $searchterm,
                'compare' => 'LIKE'
            ));
        }
        $query->set("meta_query", $meta_query);
    }
}
add_filter( "pre_get_posts", "custom_search_query");

