Chức năng HTML tùy chỉnh chỉ hoạt động khi hình ảnh đính kèm vào bài viết/trang Tôi đã thay đổi html của gallery bằng cách sử dụng posts_gallery hook theo cách được trình bày ở đây: Làm thế nào để tùy chỉnh đầu ra của WP hình ảnh gallery shortcode từ một plugin? Tôi đã sao chép mã mới nhất từ wordpress và thay đổi biến $output để sửa đổi HTML của tôi. Vấn đề là nó chỉ hoạt động cho các hình ảnh được đính kèm vào trang đang xem. Tôi muốn sử dụng hình ảnh từ các trang khác hoặc đã được tải lên trong các gallery. Các gallery được tạo với mã ngắn sử dụng cửa sổ đa phương tiện và trông giống như: [gallery ids="1,2,3,4,5"]. Tôi đã thử thay thế ids với bao gồm nhưng điều đó không hoạt động và tôi nhận được một số mã mặc định khác ngoài đầu ra HTML tùy chỉnh của tôi. Đây là đầu ra gallery tùy chỉnh của tôi:

function my_gallery_shortcode( $output = '', $atts, $content = false, $tag = false ) {
    $return = $output; // fallback
    // lấy nội dung của chức năng gallery của riêng bạn
    $my_result = get_my_gallery_content( $atts );
    // boolean false = trống, xem http://php.net/empty
    if( !empty( $my_result ) ) {
        $return = $my_result;
    }
    return $return;
}
add_filter( 'post_gallery', 'my_gallery_shortcode', 10, 4 );

function get_my_gallery_content ( $atts ) {
    global $post;
    // Chúng tôi tin tưởng đầu vào của tác giả, vì vậy hãy chắc chắn rằng nó trông giống như một câu lệnh orderby hợp lệ
    if ( isset( $attr['orderby'] ) ) {
        $attr['orderby'] = sanitize_sql_orderby( $attr['orderby'] );
        if ( !$attr['orderby'] )
            unset( $attr['orderby'] );
    }
    $html5 = current_theme_supports( 'html5', 'gallery' );
    extract(shortcode_atts(array(
        'order'      => 'ASC',
        'orderby'    => 'menu_order ID',
        'id'         => $post ? $post->ID : 0,
        'itemtag'    => $html5 ? 'figure'
        : 'dl',
        'icontag'    => $html5 ? 'div'
        : 'dt',
        'captiontag' => $html5 ? 'figcaption' : 'dd',
        'columns'    => 3,
        'size'       => 'thumbnail',
        'include'    => '',
        'exclude'    => '',
        'link'       => '',
    ), $attr, 'gallery'));
    $id = intval($id);
    if ( 'RAND' == $order )
        $orderby = 'none';
    if ( !empty($include) ) {
        $_attachments = get_posts( array('include' => $include, 'post_status' => 'inherit', 'post_type' => 'attachment', 'post_mime_type' => 'image', 'order' => $order, 'orderby' => $orderby) );
        $attachments = array();
        foreach ( $_attachments as $key => $val ) {
            $attachments[$val->ID] = $_attachments[$key];
        }
    } elseif ( !empty($exclude) ) {
        $attachments = get_children( array('post_parent' => $id, 'exclude' => $exclude, 'post_status' => 'inherit', 'post_type' => 'attachment', 'post_mime_type' => 'image', 'order' => $order, 'orderby' => $orderby) );
    } else {
        $attachments = get_children( array('post_parent' => $id, 'post_status' => 'inherit', 'post_type' => 'attachment', 'post_mime_type' => 'image', 'order' => $order, 'orderby' => $orderby) );
    }
    if ( empty($attachments) )
        return '';
    if ( is_feed() ) {
        $output = "\n";
        foreach ( $attachments as $att_id => $attachment )
            $output .= wp_get_attachment_link($att_id, $size, true) . "\n";
        return $output;
    }
    $itemtag = tag_escape($itemtag);
    $captiontag = tag_escape($captiontag);
    $icontag = tag_escape($icontag);
    $valid_tags = wp_kses_allowed_html( 'post' );
    if ( ! isset( $valid_tags[ $itemtag ] ) )
        $itemtag = 'dl';
    if ( ! isset( $valid_tags[ $captiontag ] ) )
        $captiontag = 'dd';
    if ( ! isset( $valid_tags[ $icontag ] ) )
        $icontag = 'dt';
    $columns = intval($columns);
    $itemwidth = $columns > 0 ? floor(100/$columns) : 100;
    $float = is_rtl() ? 'right' : 'left';
    $selector = "gallery-{$instance}";
    $gallery_style = $gallery_div = '';
    /**
     * Lọc xem có in các kiểu gallery mặc định hay không.
     *
     * @since 3.1.0
     *
     * @param bool $print Xác định xem có in các kiểu gallery mặc định hay không.
     *                   Nếu chủ đề hỗ trợ gallery HTML5, giá trị mặc định là false.
     *                   Nếu không, giá trị mặc định là true.
     */
    if ( apply_filters( 'use_default_gallery_style', ! $html5 ) ) {
        $gallery_style = "
        <style type='text/css'>
            #{$selector} {
                margin: auto;
            }
            #{$selector} .gallery-item {
                float: {$float};
                margin-top: 10px;
                text-align: center;
                width: {$itemwidth}%;
            }
            #{$selector} img {
                border: 2px solid #cfcfcf;
            }
            #{$selector} .gallery-caption {
                margin-left: 0;
            }
            /* xem gallery_shortcode() trong wp-includes/media.php */
        </style>\n\t\t";
    }
    $size_class = sanitize_html_class( $size );
    $gallery_div = "<div id='$selector-sausage' class='gallery galleryid-{$id} gallery-columns-{$columns} gallery-size-{$size_class} images'>";
    /**
     * Lọc các kiểu CSS mặc định của mã ngắn gallery.
     *
     * @since 2.5.0
     *
     * @param string $gallery_style Kiểu CSS mặc định của mã ngắn gallery.
     * @param string $gallery_div   HTML div mở cho đầu ra của mã ngắn gallery.
     */
    $output = apply_filters( 'gallery_style', $gallery_style . $gallery_div );
    $i = 0;
    $first_image = reset($attachments);
    $output .= '<a href="" itemprop="image" class="woocommerce-main-image zoom">';
    $output .= wp_get_attachment_image( $first_image->ID, array(470,365), true, false );
    $output .= '</a>';
    $output .= '<div class="thumbnails">';
    foreach ( $attachments as $id => $attachment ) {
        if ( ! empty( $link ) && 'file' === $link )
            $image_output = wp_get_attachment_link( $id, $size, false, false );
        elseif ( ! empty( $link ) && 'none' === $link )
            $image_output = wp_get_attachment_image( $id, $size, false );
        else
            $image_output = wp_get_attachment_link( $id, $size, true, false );
        $image_meta  = wp_get_attachment_metadata( $id );
        $orientation = '';
        if ( isset( $image_meta['height'], $image_meta['width'] ) )
            $orientation = ( $image_meta['height'] > $image_meta['width'] ) ? 'portrait' : 'landscape';
        $output .= $image_output;
    }
    if ( ! $html5 && $columns > 0 && $i % $columns !== 0 ) {
        $output .= "
            <br style='clear: both' />";
    }
    $output .= "
        </div>\n</div>\n";
    return $output;
}

