Cách tự động kích hoạt một plugin khi cài đặt Tôi có một plugin là trình cài đặt cho chủ đề và nhiều plugin khác hoạt động cùng với nó. Để thuận tiện cho cuộc thảo luận, chúng ta hãy gọi các plugin bổ sung là "payload". Điều duy nhất mà tôi đang thiếu là cách để kích hoạt các plugin payload thông qua script (thay vì yêu cầu chủ trang web phải nhấp vào nút "Activate" một cách thủ công. Tôi cũng muốn vô hiệu hóa (và xóa bỏ) plugin trình cài đặt sau khi hoàn thành các quy trình kích hoạt (nhưng đây là mối quan tâm thứ yếu). Cảm ơn bạn trước! Dưới đây là đoạn mã tôi đã viết nhưng nó không kích hoạt bất kỳ plugin payload nào:

function payload_activate() {
    activate_plugin('my-first-plugin.php');
    activate_plugin('my-second-plugin.php');
}

register_activation_hook(__FILE__, 'payload_activate');

Thiết lập biến $wp_rewrite->non_wp_rules bên trong một plugin Tôi đang cố gắng thiết lập lại các quy tắc không phải của WordPress bên trong một plugin. Các biến $wp_rewrite->rules được thiết lập đúng, nhưng không thiết lập gì cả khi tôi vô hiệu hóa/kích hoạt plugin của tôi. Tuy nhiên, nếu tôi thiết lập 'flush_rewrite_rules()' để xóa trong hành động "init" thay vì kích hoạt plugin thì chúng hoạt động tốt. Đây là phiên bản đơn giản của mã của tôi...

class My_Plugin {

public function __construct() {
register_activation_hook(__FILE__, array(&$this, 'activate'));
register_deactivation_hook( __FILE__, array(&$this, 'deactivate'))
add_action('generate_rewrite_rules', array(&$this, 'rewrite'));
}

public function rewrite() {
global $wp_rewrite;
$new_rules = array(
'something/?$' => 'index.php?custom_page=something',
);
$new_non_wp_rules = array(
'theme/(.*)' => 'wp-content/themes/$1',
);
$wp_rewrite->rules = $new_rules + $wp_rewrite->rules;
$wp_rewrite->non_wp_rules = $new_non_wp_rules + $wp_rewrite->non_wp_rules;
}

public function activate() {
flush_rewrite_rules();
}

public function deactivate() {
flush_rewrite_rules();
}

}

