});
```

Tuy nhiên, vấn đề là biến `$username` trả về giá trị `null` thay vì `test`. Tôi đã thử nhiều cách kết hợp khác nhau trong vài tiếng đồng hồ nhưng tất cả đều trả về giá trị `null`. Việc gán giá trị `$username = 'test'` khiến hàm PHP hoạt động đúng như mong đợi, vì vậy tôi nghĩ rằng vấn đề không liên quan đến mã PHP. Vậy làm thế nào để biến `$username` lắng nghe và lấy được giá trị tham số chính xác thay vì `null`?

Bạn có ý tưởng nào về cách để thực hiện kiểm tra đơn vị đọc các chức năng trong file functions.php không? Tôi đã thực hiện một bài kiểm tra đơn vị cho một plugin hoạt động hoàn hảo cho đến phần mà tôi cần kích hoạt chủ đề và kiểm tra xem chủ đề có cung cấp dữ liệu móc đúng cho plugin. Bên trong plugin mà tôi đang thử nghiệm, tôi có apply_filters sẽ thực hiện các móc add_filter được định nghĩa bên trong theme functions.php. Đây là mã kiểm tra đơn vị của tôi:

function test_theme_hooks() {
    // Định nghĩa các plugin cần thiết cho việc thử nghiệm
    $requiredplugins = array(
        '0' => 'myplugin1/plugin1.php',
        '1' => 'myplugin2/plugin2.php'
    );

    // Kích hoạt các plugin
    update_option('active_plugins', $requiredplugins);

    // Kích hoạt chủ đề
    switch_theme('my_theme_to_test', 'my_theme_to_test');

    // Lấy các nhóm được định nghĩa bởi chủ đề
    $Class_My_Plugin = new Class_My_Plugin;
    $groups_definedfrom_theme = $Class_My_Plugin->get_groups();

    $correct_groups = array('0' => 'Some array');

    $this->assertEqual($correct_groups, $groups_definedfrom_theme);
}

Vấn đề là, dường như theme functions.php không được đọc hoặc thực thi trong quá trình thử nghiệm. Tôi đã kiểm tra thủ công rằng chủ đề đã được chuyển đổi/bật cũng như các plugin cần thiết. Nhưng kết quả của $groups_definedfrom_theme là NULL mà không chính xác. Có bất kỳ mẹo nào để thực hiện bài kiểm tra này chính xác hoặc làm thế nào để khiến bài kiểm tra đơn vị đọc các chủ đề functions.php đang hoạt động cũng như các bộ lọc của nó? Cảm ơn bất kỳ sự giúp đỡ nào.

