});

Gọi JavaScript points.set() **cập nhật** giá trị vị trí (Tôi nhận được thông tin chính xác trong console) nhưng **không thể** cập nhật phần tử đầu vào nằm trong tùy chỉnh chủ đề chính nó. Tôi đã xem qua lớp api.Value (lớp của biến points của tôi) trong wp-includes/js/customize-base.js. Điều tôi cần là lấy được trường hợp của api.Element tương ứng và gọi phương thức cập nhật của nó. Nhưng tôi không thể tìm ra từ đâu tôi có thể lấy điều này.

Chỉ trả về các sub-term tùy chỉnh cho kiểu bài viết tùy chỉnh, không hiển thị term-parent Tôi đã tạo một hàm tùy chỉnh để lấy thuật ngữ phân loại tùy chỉnh cho danh sách bài viết trong truy vấn và hiển thị cả tên và liên kết. Ngoài ra, nó cũng loại trừ việc liệt kê thuật ngữ nếu tôi chỉ định ID thuật ngữ (tôi có một thuật ngữ đặc biệt mà tôi không muốn hiển thị, mà tôi sử dụng làm móc lặp). Điều này đạt được bằng cách sử dụng hàm sau:

function my_get_the_term_list( $id = 0, $taxonomy, $before = '', $sep = '', $after = '', $exclude = array() ) {     $terms = get_the_terms( $id, $taxonomy );          if ( is_wp_error( $terms ) )         return $terms;          if ( empty( $terms ) )         return false;          foreach ( $terms as $term ) {              if(!in_array($term->term_id,$exclude)) {             $link = get_term_link( $term, $taxonomy );             if ( is_wp_error( $link ) )                 return $link;             $term_links[] = '<a href="' . $link . '" rel="tag" class="category-link" title="Xem tất cả câu chuyện từ '.$terms_as_text.'">' . $term->name . '</a>';         }     }          $term_links = apply_filters( "term_links-$taxonomy", $term_links );          return $before . join( $sep, $term_links ) . $after;     }

Sau đó, tôi hiển thị nó với dòng sau:

<?php echo my_get_the_term_list( $post->ID, 'sports_category',  '', ' ', '', array(3623) ); ?>

Tất cả đều tốt đẹp. Bây giờ tôi đang đi sâu vào cây trang web và tôi muốn lấy thuật ngữ của bài viết hiện tại một lần nữa, nhưng bây giờ (vì tôi đang ở trang lưu trữ cho thuật ngữ trong giải thích ở trên) tôi chỉ muốn lấy các thuật ngữ con và không hiển thị thuật ngữ cha. Tôi đã thử sửa đổi mã trên nhưng dường như không thể tách rời mọi thứ. Các ví dụ tôi đã thấy ở nơi khác không đề cập đến các thuật ngữ tùy chỉnh, ngoài ra tôi cũng muốn tạo nó thành hàm để có thể đặt một số tham số như ở trên. Đây là nỗ lực mới nhất của tôi:

function my_get_the_children( $id, $taxonomy, $before = '', $sep = '', $after = '', $exclude = array() ) {     $terms = get_term_children( $id, $taxonomy );          if ( is_wp_error( $terms ) )         return $terms;          if ( empty( $terms ) )         return false;          foreach ( $terms as $term ) {              if(!in_array($term->term_id,$exclude)) {             $link = get_term_link( $term->name, $taxonomy );             if ( is_wp_error( $link ) )                 return $link;             $term_links[] = '<a href="' . $link . '" rel="tag" class="category-link" title="Xem tất cả câu chuyện từ '.$terms_as_text.'">' . $term->name . '</a>';         }     }          $term_links = apply_filters( "term_links-$taxonomy", $term_links );          return $before . join( $sep, $term_links ) . $after;     }

