Làm thế nào để thêm một lớp vào hình ảnh đính kèm Khi tôi đang chỉnh sửa nội dung trên WordPress và thêm một hình ảnh bên ngoài bằng nút 'img', mã HTML của tôi sẽ như thế này:

<img src="http://example.com/image.jpg" alt="image" />

Làm thế nào để tự động thêm một lớp vào thẻ img? Ví dụ như thế này:

<img class="my-img-class" src="http://example.com/image.jpg" alt="image" />

Tôi muốn áp dụng nguyên tắc tương tự cho tùy chọn "Add Media". Mã đầu ra hiện tại trông như thế này:

<a href="mywordpressdomain/image.jpg"><img src="mywordpressdomain/image.jpg" alt="image" width="872" height="867" class="alignnone size-full wp-image-59" /></a>

Và tôi muốn mã đầu ra trông như thế này:

<a href="mywordpressdomain/image.jpg"><img src="mywordpressdomain/image.jpg" alt="image" width="872" height="867" class="alignnone size-full my-img-class" /></a>

Tôi mới bắt đầu học PHP, vì vậy tôi không chắc làm thế nào để thực hiện điều này thông qua một bộ lọc. Tôi đã bắt đầu như thế này, nhưng không biết phải làm gì tiếp theo:

function image_tag_class($class, $id, $align, $size) {
    return $align;
}

add_filter('get_image_tag_class', 'image_tag_class', 0, 4);

pre_get_posts trên một trang Liệu có thể chỉnh sửa truy vấn chính trên trang bằng bộ lọc `pre_get_posts` không? Tôi đã thử nhưng dường như nó không hoạt động.

function pre_wp_queries( $query ) {
    // chỉ kích hoạt trên truy vấn chính
    if ( !$query->is_main_query() )
        return;

    if ( is_page_template('TEMPLATE_NAME.php') ) {
        $query->query_vars['pagename'] = null;
        $query->query_vars['post_type'] = 'post';
        $query->query_vars['posts_per_page'] = 3;
        $query->query_vars['cat'] = 13;
    }
}

add_action('pre_get_posts', 'pre_wp_queries', 9001);

Trên header.php tôi sử dụng dòng này để kiểm tra xem nó có hoạt động không:

var_dump($GLOBALS['wp_query']->request);

Nó hiển thị:

SELECT wp_posts.*
FROM wp_posts
WHERE 1=1
AND wp_posts.post_type = 'post'
ORDER BY wp_posts.post_date DESC

Vậy là nó đã thay đổi kiểu bài viết nhưng không thay đổi những phần còn lại. Hơn nữa nó dẫn đến trang lỗi 404. Thực ra việc xả ra `$GLOBALS['wp_query']->queried_object` cho kết quả trả về trang ban đầu. Tôi đã thử trên hai cài đặt WP và nhận được cùng một kết quả. Đây có phải là hành vi đúng đắn hay tôi đã bỏ lỡ điều gì đó?

Thay đổi get_post_thumb theo cách có thể thay đổi kích thước? Làm thế nào để tôi có thể thay đổi phản hồi get_post_thumb khi đạt đến một điểm dừng nhất định với mã PHP? Tôi sử dụng mã sau để in bài đăng của tôi ở thời điểm hiện tại:

<?php
echo '<div class="featured-thumbnail">';
the_post_thumbnail('featured-cat',array('title' => ''));
echo '</div>';
?>

Điều này được chỉ định trong tệp "functions.php" của tôi:

add_image_size( 'featured-cat', 248, 110, true ); //featured-cat

Điều tôi muốn làm tiếp theo là thay vào đó sử dụng mã sau khi đạt đến kích thước màn hình 320px. Tôi muốn sử dụng

add_image_size( '**featured-cat-mobile**', 200, 80, true ); //featured-cat mobile

draft_to_pending action không có vẻ như là kích hoạt Tôi có hành động ‘draft_to_pending‘ được thiết lập để bắn trên một loại bài viết tùy chỉnh. Tôi giả định rằng khi người dùng nhấp vào “Tình trạng » Chỉnh sửa” thay đổi nó thành “Đang chờ” và sau đó nhấp vào “Lưu Đang chờ”, hành động này được giả định sẽ bắn, nhưng dường như không làm như vậy. Đây là mã của tôi:
add_action('draft_to_pending','notify_email_rejected',99);

hàm notify_email_rejected($post) {
$post_id = $post->ID;
$is_rejected = get_post_meta($post_id,'rejected_listing',true);
$owner_id = get_post_meta($post_id,'owner',true);
$owner = get_userdata($owner_id);
$to = $owner->user_email;
$headers = "Từ: HayForSale <admin@hayforsale.com>\r\n";
$headers .= "Phiên bản MIME: 1.0\r\n";
$headers .= "Kiểu nội dung: text/html; charset=ISO-8859-1\r\n";
$subject = 'Danh sách của bạn đã bị từ chối tại HayForSale.com';
$rejection = get_post_meta( $post_id, 'rejection_message', true );
$message = 'một số html';
wp_mail($to, $subject, $message, $headers);
}

Mô tả meta dấu ba chấm Tôi có một hàm để đặt một meta description trong phần <head> của theme. Nó hoạt động tốt nhưng tôi có một vấn đề nhỏ. Nó cắt những từ ngữ trong mô tả khi nó đến giới hạn 160 ký tự. Tôi hy vọng có cách "sạch sẽ" hơn để làm điều đó. Đây là hàm:

function add_meta_description() {
    global $post;
    if ( is_single() ) {
        $post_object = get_post(get_the_ID());
        $content= $post_object->post_content;
        $desc = substr( strip_tags( $content ), 0, 160 );
        echo '<meta name="description" content="' . esc_attr( $desc ) . '" />';
    }
}

Có cách nào để không cắt từ ngữ và thay vào đó là dấu chấm lửng không?

Bảng không được tạo ra khi kích hoạt WP Theme Đây là mã tôi đang sử dụng để tạo một bảng tùy chỉnh có tên là "prefix" + zillow --> trong đó prefix là tiền tố bảng wp cho trang web.

register_activation_hook(__FILE__,'CreateTable');

Hàm thực tế được cung cấp bên dưới - nó kiểm tra xem bảng như vậy đã tồn tại cùng với số phiên bản được gán cho bảng đó (để tôi có thể cập nhật / thay đổi bảng đó trong phiên bản sau của chủ đề) -

function CreateTable() {
//Phiên bản bảng cơ sở dữ liệu
$zillow_db_table_version = "1.0";
$table_name = $wpdb->prefix . "zillow";
$installed_ver = get_option( "zillow_db_table_version" );

//Kiểm tra xem bảng có tồn tại và nếu bảng được cập nhật, nếu không tạo nó
if($wpdb->get_var("SHOW TABLES LIKE '$table_name'") != $table_name || $installed_ver != $zillow_db_table_version ) {
$sql = "CREATE TABLE " . $table_name .
" (propertyid varchar(20) NOT NULL ,
inserted_on date,
UNIQUE KEY id (id) );";
require_once(ABSPATH . 'wp-admin/includes/upgrade.php');
dbDelta($sql);
update_option( "zillow_db_table_version", $zillow_db_table_version );
}

//Thêm phiên bản bảng cơ sở dữ liệu vào các tùy chọn
add_option("zillow_db_table_version", $zillow_db_table_version);
}

Tuy nhiên, bảng không được tạo ra chút nào. Có vấn đề gì với mã trên? Tôi đã thử kích hoạt chủ đề bằng mã trên nhiều lần (sau khi kích hoạt trước một chủ đề khác và sau đó kích hoạt chủ đề này) nhưng không có bảng nào được tạo ra (tôi kiểm tra trực tiếp trong danh sách bảng WP).

Truyền kết quả của truy vấn tùy chỉnh đến vòng lặp - khi viết một plugin Tôi muốn viết một plugin, không phải một theme. Tôi cần có thể chạy một câu lệnh SQL tùy chỉnh và thiết lập kết quả làm bài viết cho vòng lặp. Tôi đang viết một plugin, vì vậy tôi không thể sử dụng các thẻ mẫu hay vòng lặp foreach. Tôi chỉ muốn chạy câu lệnh SQL của mình, chọn đúng hàng và nói với WordPress rằng đây là bài viết cho vòng lặp. Cho đến nay tôi đã thử như sau:

add_filter('pre_get_posts', 'customQuery');

function customQuery() {
    global $wpdb;

    $sql = "câu lệnh SQL ở đây";
    $safequery = $wpdb->prepare($sql);
    $queryResults = $wpdb->get_results($safequery);
}

Điều này hoạt động tốt để lấy kết quả mong muốn. Biến $queryResults chứa dữ liệu chính xác. Sau dòng đó, tôi đã thử một vài điều khác nhau mà không thành công.

...

global $post;
$post = $queryResults[0]; //vì nó là một mảng và tôi chỉ cần kết quả đầu tiên

Điều này không hoạt động. Hoặc nói cách khác, nếu tôi kiểm tra biến $post ngay sau dòng đó, nó sẽ hiển thị kết quả mong muốn, nhưng dường như nó bị đặt lại ở đâu đó phía dưới bởi vì trang hiển thị 404 khi thực sự hiển thị. Tôi cũng đã thử:

...

global $post;
$post = $queryResults[0];
setup_postdata($post);

Kết quả tương tự. Nếu tôi kiểm tra giá trị biến ngay lập tức, tôi sẽ thấy giá trị mong muốn. Với ví dụ thứ hai, tôi thậm chí còn thử chạy một số hàm như the_title(); (mà hoạt động nhưng không giúp ích gì bởi vì tôi đang viết một plugin chứ không phải một theme). Nhưng khi trang được hiển thị, tôi nhận được lỗi 404. Tôi chắc rằng tôi chỉ bỏ lỡ điều đơn giản nào đó mà sẽ cho phép tôi chuyển kết quả của mình vào vòng lặp từ plugin. Các bạn có ý tưởng nào không? Cảm ơn.

Cách thêm các mục menu điều hướng vào một vị trí cụ thể trong một menu Tôi đang thêm các liên kết đăng nhập/đăng xuất vào menu điều hướng bằng mã sau:

function rp_add_login_logout_links( $items, $args ) {
  $link = wp_loginout( get_permalink( get_option( 'woocommerce_myaccount_page_id' ) ), false );

  if ( 'Shop Menu' == $args->menu ) {
    $items .= '<li id="menu-item-login" class="menu-item menu-item-login">' . $link . '</li>';
  }

  return $items;
}

add_filter( 'wp_nav_menu_items', 'rp_add_login_logout_links', 10, 2 );

Vì $items là một chuỗi, tôi chỉ có thể dễ dàng chèn hoặc thêm các liên kết vào danh sách. Tôi cần liên kết này xuất hiện trước một mục menu cụ thể trong danh sách, nó sẽ trở thành mục thứ ba từ cuối cùng. Có bộ lọc hoặc phương pháp nào khác mà tôi có thể sử dụng để thực hiện điều này? Tôi đã thử sử dụng strpos để tìm mục điều hướng tôi đang tìm kiếm và thao tác với chuỗi $items nhưng không thể khớp với mục menu HTML.

Cách hiển thị bài viết từ một danh mục duy nhất trong một phân loại tùy chỉnh Tôi đang cố gắng liệt kê các bài viết từ một danh mục duy nhất trong hệ thống phân loại tùy chỉnh của tôi. Tôi đã tạo một loại bài viết tùy chỉnh được gọi là "Inventory" và một hệ thống phân loại tùy chỉnh được gọi là "Inventory Category". Sau đó, tôi tạo một số danh mục sử dụng hệ thống phân loại "Inventory Category". Tôi muốn hiển thị các bài viết chỉ từ một danh mục duy nhất. Để làm điều này, tôi sử dụng hàm query_posts() với các tham số sau:

query_posts( array( 'post_type' => 'inventory', 'inventory-category' => 'bulk-racks' ) );

Tuy nhiên, mã này trả về tất cả các bài viết trong hệ thống phân loại "Inventory Category" thay vì chỉ những bài viết trong danh mục "bulk racks". Ai có thể giúp tôi sửa lỗi này không? Đây là cách tôi tạo loại bài viết và hệ thống phân loại tùy chỉnh:

/* --- Tạo loại bài viết Inventory --- */
add_action('init', 'inventory_register');
function inventory_register() {
    $args = array(
        'label' => __('Inventory'),
        'singular_label' => __('Inventory'),
        'public' => true,
        'show_ui' => true,
        'capability_type' => 'post',
        'hierarchical' => true,
        'rewrite' => true,
        'supports' => array('title', 'thumbnail', 'revisions','custom-fields')
    );
    register_post_type( 'inventory' , $args );
}

/* --- Đăng ký hệ thống phân loại tùy chỉnh cho danh sách Inventory --- */
add_action( 'init', 'register_my_taxonomies', 0 );
function register_my_taxonomies() {
    register_taxonomy(
        'division',
        array( 'inventory' ),
        array(
            'hierarchical' => true,
            'public' => true,
            'labels' => array(
                'name' => __( 'Inventory Category' ),
                'singular_name' => __( 'Inventory Categories' ),
                'show_ui' => true,
                'show_in_nav_menus' => true,
            ),
        )
    );
}

Filter của $object dùng để làm gì? Tôi cứ nhìn thấy mẫu này, và thắc mắc nó dùng để làm gì, và WP sử dụng nó như thế nào bên trong:
if ( empty($post) ) {
    if ( isset($GLOBALS['post']) )
        $_post = & $GLOBALS['post'];
    else
        return $null;
} elseif ( is_object($post) && empty($post->filter) ) {
    _get_post_ancestors($post);
    $_post = sanitize_post($post, 'raw');
    wp_cache_add($post->ID, $_post, 'posts');
} else {
    if ( is_object($post) )
        $post_id = $post->ID;
    else
        $post_id = $post;
Dòng cụ thể cần quan tâm là `is_object($post) && empty($post->filter)`. Tôi đã thấy thuộc tính `filter` này được liên kết với các đối tượng khác. Thắc mắc nó làm gì và làm thế nào có thể sử dụng?
