while ( $dirloop->have_posts() ) : $dirloop->the_post();

$custom = get_post_custom($post->ID);

$file_id = $custom["upload_file"][0];

$file_begin = $custom["begin_date"][0];

$file_end = $custom["end_date"][0];

if ('' != $file_end) {$file_end = "to".$file_end;}

$file_url = wp_get_attachment_url($file_id);

if ('' != $file_url) { //Kiểm tra sự tồn tại của URL tệp

$content .= "<li class='ia_nl'><a href='".$file_url."'>".$cat." ".$file_begin.$file_end."</a></li>\n";

}

endwhile;

$content .= "</ul>\n";

} else { $content = "nothing"; }

return $content;

}

Làm thế nào để lọc get_avatar? Tôi muốn sử dụng hệ thống avatar địa phương cho trang web wp của tôi, tôi muốn lọc hàm 'get_avatar()' để nó sẽ trả về avatar từ máy chủ của tôi thay vì gavatar mặc định. Tôi có đoạn mã sau đây:

class local_avatar {
function __construct() {
add_filter('get_avatar', array($this, 'get_avatar'));
}

public function get_avatar($avatar, $id_or_email, $size = '96', $default, $alt = false) {
global $wpdb;
$upload = wp_upload_dir();
if (is_numeric($id_or_email)) {
// ID người dùng
$image = get_user_meta($id_or_email, '_ahaali_avatar', true);
if ($image) {
$image_path = $upload['baseurl'] . '/avatar/' . $image;
$ahaali_avatar = '<img src="' . $image_path . '" width="' . $size . '" height="' . $size . '" />';
