function validate_setting($plugin_options) {
   $keys = array_keys($_FILES);
   $i = 0;
   foreach ($_FILES as $image) {
      // nếu một tập tin đã được tải lên
      if ($image['size']) {
         // nếu nó là một hình ảnh
         if (preg_match('/(jpg|jpeg|png|gif)$/', $image['type'])) {
            $override = array('test_form' => false);
            // lưu tập tin, và lưu một mảng, chứa vị trí của nó trong $file
            $file = wp_handle_upload($image, $override);
            $plugin_options[$keys[$i]] = $file['url'];
         } else {
            // Không phải là hình ảnh.
            $options = get_option('plugin_options');
            $plugin_options[$keys[$i]] = $options['logo'];
            // chết và để người dùng biết rằng họ đã mắc lỗi.
            wp_die('Không có hình ảnh nào được tải lên.');
         }
      }
      // Nếu không, người dùng không tải lên một tập tin.
      // Giữ hình ảnh đã có sẵn trên tệp.
      else {
         $options = get_option('plugin_options');
         $plugin_options[$keys[$i]] = $options[$keys[$i]];
      }
      $i++;
   }
   return $plugin_options;
}

