wp_mail function hết thời gian chờ đợi Tôi có chức năng sau đây. Đây là một phần của trang web dựa trên thành viên. Khi một bài viết với loại "message" được chuyển sang trạng thái Publish, nó nên gửi email cho tất cả người dùng thuộc (custom user meta) các quận (taxonomy) được chọn khi bài viết được soạn thảo. Nếu tôi gửi cho một nhóm nhỏ, dường như nó hoạt động. Nếu tôi gửi cho tất cả các quận, nó bị treo và không có tin nhắn nào được gửi đi. Tôi đã thử giới hạn nó thành từng phần (25) để giảm bớt khó khăn, nhưng không giúp ích gì. Bạn có ý tưởng nào ngoài việc nói với khách hàng chỉ gửi cho một nhóm tại một thời điểm?

add_action('publish_messages', 'messages_notify', 10, 3);

function messages_notify() {
    global $post;

    // nếu bài viết đã được xuất bản, hủy bỏ
    if($post->post_status == 'publish') {
        return;
    }

    // lấy các quận được đánh dấu, nếu không hủy bỏ
    $districts = get_the_terms($post->ID, 'message_district');
    if(empty($districts)) return;

    // truy vấn các thành viên thuộc một trong các quận được đánh dấu
    $the_districts = array();
    $district_args = array('relation' => 'OR' );
    foreach($districts as $district){
        $the_districts[] = $district->name;
        if ($district->name == 'Northeast') {
            $district_args[] = array('key' => 'whprms_district_ne', 'value' => 1);
        }

        if ($district->name == 'North Central') {
            $district_args[] = array('key' => 'whprms_district_nc', 'value' => 1);
        }

        if ($district->name == 'Southeast') {
            $district_args[] = array('key' => 'whprms_district_se', 'value' => 1);
        }

        if ($district->name == 'Southwest') {
            $district_args[] = array('key' => 'whprms_district_sw', 'value' => 1);
        }

        if ($district->name == 'West') {
            $district_args[] = array('key' => 'whprms_district_w', 'value' => 1);
        }
    }

    $district_members = get_users(
        array(
            'meta_query' => $district_args,
        )
    );

    $attachment_args = array('post_type' => 'attachment', 'orderby' => 'date', 'order' => 'ASC', 'numberposts' => -1, 'post_status' => NULL, 'post_parent' =>$post->ID);
    $attachments = get_posts($attachment_args);

    if ($attachments) {
        $att_array = array();
        foreach ($attachments as $attachment) {
            $att_array[] = get_the_title($attachment->ID);
        }
    }

    // chỉ gửi tin nhắn cho người dùng với vai trò mong muốn
    $bcc = array();
    foreach($district_members as $district_member) {
        if(user_can($district_member->ID, 'board_members') || user_can($district_member->ID, 'members')) {
            $bcc[] = $district_member->user_email;
        }
    }

    $subject = 'WHPRMS Message: '.$post->post_title;
    $message = 'New message posted by ';
    if(user_can($post->post_author, 'administrator')) {
        $message .= get_the_author_meta('user_nicename', $post->post_author)."\n\r";
    } else {
        $message .= get_the_author_meta('first_name', $post->post_author).' '.get_the_author_meta('last_name', $post->post_author)."\n\r";
    }

    $message .= 'Excerpt: '.stripslashes(substr($post->post_content, 0, 240)).'...'."\n\r";
    $message .= 'Link: '.get_permalink($post->ID)."\n\r";

    $message .= 'District(s): '.implode(', ', $the_districts)."\n\r";
    if (!empty($att_array)) {
        $message .= 'Attachment(s): '.implode(', ', $att_array)."\n\r";
    }

    $message .= 'You are receiving this message because you belong to one of the districts mentioned above.';

    $chunked_bcc = array_chunk($bcc, 25);
    foreach($chunked_bcc as $bcc_chunk){
        $headers = array();
        $headers['Bcc'] = 'BCC: '.implode(', ', $bcc_chunk);
        wp_mail('no-reply@whprms.org', $subject, $message, $headers);
    }
}

Metabox nonce không cho phép cập nhật Tôi đang gặp vấn đề khi lưu dữ liệu metabox cho type bài viết tùy chỉnh. Tôi nghĩ rằng tôi đã sửa được bằng cách áp dụng lời khuyên trong bài viết này: Metabox nonce PHP notice mà không loại bỏ cảnh báo nhưng khiến tôi không thể cập nhật metaboxes. Đây là mã liên quan:

function save_goal_info_meta( $post_id ) {
    global $goal_info_meta_fields;

    // kiểm tra nonce
    if ( ! isset( $_POST['product_noncename'] ) || ! wp_verify_nonce( $_POST['goal_info_meta_box_nonce'], basename( __file__ ) ) ) {
        return $post_id;
    }

    // kiểm tra autosave
    if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) {
        return $post_id;
    }

    // kiểm tra quyền truy cập
    if ( 'page' == $_POST['post_type'] ) {
        if ( ! current_user_can( 'edit_page', $post_id ) )
            return $post_id;
    } elseif ( ! current_user_can( 'edit_post', $post_id ) ) {
        return $post_id;
    }

    // lặp qua các trường và lưu dữ liệu
    foreach ( $goal_info_meta_fields as $field ) {
        if ( $field['type'] == 'tax_select' )
            continue;

        $old = get_post_meta( $post_id, $field['id'], true );
        $new = $_POST[$field['id']];

        if ( isset( $new ) && ! empty( $new ) && ( $new != $old ) ) {
            update_post_meta( $post_id, $field['id'], $new );
        } elseif ( '' == $new && $old ) {
            delete_post_meta( $post_id, $field['id'], $old );
        }
    }
}

add_action( 'save_post', 'save_goal_info_meta' );

