Lấy cấu trúc permalink của /%posttype%/%category%/%postname% Tôi có một loại bài viết tùy chỉnh tên là Reportage, được thêm vào trong functions.php:
add_action( 'init', 'create_post_type' );
function create_post_type() {
    register_post_type( 'reportage',
        array(
            'labels' => array(
                'name' => __( 'Reportage' ),
                'singular_name' => __( 'Reportage' )
            ),
            'public' => true,
            'taxonomies' => array('category'),
            'query_var' => true
        )
    );
