function related_posts(){
    global $post;
    $categories = get_the_category($post->ID);
    if ($categories) {
        $category_ids = array();
        foreach($categories as $individual_category) $category_ids[] = $individual_category->term_id;
        $args=array(
            'category__in' => $category_ids,
            'post__not_in' => array($post->ID),
            'posts_per_page'=> 5, // Số lượng bài viết liên quan sẽ được hiển thị.
            'ignore_sticky_posts' => 1
        );
        $my_query = new wp_query( $args );
        if( $my_query->have_posts() ) {
            $categories = get_the_category();
            echo '<div class="related_posts"><div class="related_title"> <a href="'. get_category_link($categories[0]->cat_ID). '"> '. $categories[0]->cat_name .' </a> </div><div class="related_main">';
            while( $my_query->have_posts() ) {
                $my_query->the_post();?>
                    <div class="related_posts">
                        <div class="related_thumbnail">
                          <a href="<?php the_permalink()?>"><?php the_post_thumbnail(); ?><br />
                          </a>
                        </div>
                        <div class="related_title">
                          <a href="<?php the_permalink()?>" title="<?php the_title(); ?>"><?php the_title(); ?></a>
                        </div>
                    <?php
                }
                echo '</div></div>';
            }
        }
    }
    wp_reset_query();
}

Thay đổi giá trị của số bài viết trong gallery Tôi đã cài đặt plugin này (http://wordpress.org/plugins/media-categories-2/) để phân loại hình ảnh của tôi. Trong file functions.php, tôi đã thêm đoạn mã sau đây để giới hạn số lượng hình ảnh hiển thị trong gallery:

function get_random_gallery_images(){
    global $wpdb,$post;
    $ids = "";
    $counter = 0;
    $number_of_posts = 1;
    $args = array(
        'post_type' => 'attachment',
        'numberposts' => 1,
        'post_status' => null,
        'orderby' => 'rand',
        'post_parent' => $post->ID
    );
    $attachments = get_posts($args);
    if ($attachments) {
        foreach ($attachments as $attachment) {
            if ($counter != 0) {
                $ids .= ','.$attachment->ID;
            } else {
                $ids .= $attachment->ID;
            }
            $counter++;
        }
    }
    return $ids;
}

