Điều tôi cần làm bây giờ là thêm thuộc tính rel="lightbox" vào hình thu nhỏ được hiển thị. Dưới đây là cách tôi thực hiện đối với tất cả các hình ảnh khác:

function pietergoosen_voeg_lightbox_rel_attribute_by_the_content($content) {
global $post;
$pattern = "/<a(.*?)href=('|\')(.*?).(bmp|gif|jpeg|jpg|png)('|\')(.*?)>/i";
$replacement = '<a$1href=$2$3.$4$5 rel="lightbox" title="'.$post->post_title.'"$6>';
$content = preg_replace($pattern, $replacement, $content);
return $content;
}

add_filter('the_content', 'pietergoosen_voeg_lightbox_rel_attribute_by_the_content');

