add_filter('post_type_link', 'portfolio_permalink_filter_function', 1, 3);

function portfolio_permalink_filter_function( $post_link, $id = 0, $leavename = FALSE ) {

if ( strpos('%portfolios%', $post_link) === 'FALSE' ) {

return $post_link;

}

$post = get_post($id);

if ( !is_object($post) || $post->post_type != 'portfolio' ) {

return $post_link;

}

$terms = wp_get_object_terms($post->ID, 'portfolios');

if ( !$terms ) {

return str_replace('portfolios/%portfolios%/', '', $post_link);

}

return str_replace('%portfolios%', $terms[0]->slug, $post_link);

}

Các URL sau đây hoạt động như mong đợi:

"http://example.com/portfolios" <-- kho lưu trữ danh mục đầu tư (archive-portfolio.php)

"http://example.com/portfolios/animals/" <-- kho lưu trữ thuật ngữ (taxonomy- portfolios.php)

"http://example.com/portfolios/pets/" <-- kho lưu trữ thuật ngữ (taxonomy- portfolios.php)

"http://example.com/portfolios/animals/beagle" <-- bài viết (single-portfolio.php)

Tuy nhiên, việc thực hiện "http://example.com/portfolios/animals/beagle" = "http://example.com/portfolios/pets/beagle" vẫn còn khó khăn đối với tôi.

**Liên kết Prev/Next của bài viết**

Nếu bạn đang điều hướng qua các bài viết trong kho lưu trữ "Vật nuôi" bằng cách sử dụng các liên kết prev/next ở cuối các bài viết, khi bạn đến bài viết "Beagle", các liên kết prev/next hiện tại hiển thị các liên kết trước và tiếp theo đến các bài viết trong kho lưu trữ "Động vật" (vì cách tôi tạo các liên kết prev/next và vì thuật ngữ permalink của Beagle là "động vật"). Đây là mã cho các liên kết prev/next:

/* Liên kết trước/sau trong thuật ngữ phân loại danh mục đầu tư chính */

$post_ids = get_posts(array(

'numberposts'   => -1, // nhận tất cả các bài viết.

'post_type'     => 'portfolio',

'fields'        => 'ids', // Chỉ nhận ID bài viết

'tax_query'     => array(array('taxonomy' => 'portfolios', 'field' => 'name', 'terms' => $portfolio_terms[0])),

'orderby'       => 'title',

'order'         => 'ASC'

));

$thisindex = array_search($post->ID, $post_ids);

$previd = $post_ids[$thisindex-1];

$nextid = $post_ids[$thisindex+1];

echo '<div class="post-prev-next"><!-- .post-prev-next -->';

if ( !empty($previd) ) {

echo '<div class="post-prev"><a rel="prev" href="' . get_permalink($previd) . '" title="'. get_the_title($previd) .'">&laquo; '. get_the_title($previd) .'</a></div>';

}

if ( !empty($nextid) ) {

echo '<div class="post-next"><a rel="next" href="' . get_permalink($nextid) . '" title="'. get_the_title($nextid) .'">'. get_the_title($nextid) .' &raquo;</a></div>';

}

echo '</div><!-- end .post-prev-next -->';

Logic trên có thể phải thay đổi khi vấn đề đầu tiên được giải quyết, nhưng tôi không chắc nó nên thay đổi thành gì. Nó trông giống như @TheDeadMedic đã gợi ý một giải pháp trong câu trả lời này, nhưng vì người hỏi không đi theo hướng đó, nên nó chưa bao giờ được phát triển thêm.

Nếu bạn đang gán nhiều danh mục cho một sản phẩm duy nhất, tôi có thể dễ dàng thay đổi cách nó xác định danh mục nào để sử dụng trong liên kết vĩnh viễn. Cảm ơn việc đọc vô số câu hỏi/trả lời Stackexchange và một số blog hướng dẫn trong những ngày qua, tôi đã có thể lắp ráp những gì tôi có cho đến nay, nhưng tôi đã gặp phải một vấn đề khó khăn với vấn đề này. Tôi đánh giá cao sự giúp đỡ của cộng đồng.

Làm thế nào để đặt JQuery/Ajax bên trong shortcode? Mục đích của plugin này là tạo ra một danh sách mà người dùng có thể chỉnh sửa bằng cách bỏ phiếu tăng hoặc giảm. Mã ngắn được sử dụng để hiển thị danh sách trên một trang và sử dụng JQuery để mờ dần khi cập nhật cơ sở dữ liệu. Một bản demo về khái niệm này có sẵn tại http://bucketlingerwedding.com/80s-music-reception/ (Lưu ý: mã hoạt động không còn sử dụng AJAX). Tôi muốn đưa plugin này vào Kho lưu trữ Wordpress, nhưng AJAX đang khiến tôi khó chịu. Dưới đây là mã mới nhất. Nó chỉ hiển thị một trang với khu vực nội dung trống. Tôi cần phải cập nhật cơ sở dữ liệu với AJAX, và tránh làm lại trang, để tôi có thể làm việc trong các hiệu ứng chuyển tiếp/hiệu ứng động. Mã này đã được chú thích để phản ánh sự hiểu biết của tôi về những gì tôi đang cố gắng thực hiện.

