WordPress - hình ảnh thu nhỏ từ youtube (function và loop) Chào bạn, tôi cần hiển thị hình thu nhỏ từ YouTube trên trang chủ. Tôi có mã cho WordPress trong hàm và vòng lặp nhưng không hiển thị hình thu nhỏ từ YouTube. Lỗi có thể là gì?

Mã hàm:

function get_thumbnail_fromyoutube( $size = 0 ) {
    global $post, $posts;
    $youtube = '';
    $get_url = preg_match_all('/<iframe.+src=[\'"]([^\'"]+)[\'"].*>/i', $post->post_content, $matches);
    $youtube = $matches[1][0];
    if(preg_match('/^(http:\/\/www.youtube.com)/', $youtube))
    {
        $youtube = preg_replace('/(.*?).embed\//', '', $youtube);
        $youtube = preg_replace('/\?.(.*?)$/', '', $youtube);
        echo '<img src="http://img.youtube.com/vi/' . $youtube . '/' . $size . '.jpg" alt="' . $post->post_title . '" />';
    }
}

Mã vòng lặp:

<?php
$args = array(
    'tax_query' => array(
        array(
            'posts_per_page' => 1,
            'order' => 'DESC',
            'taxonomy' => 'section',
            'field' => 'slug',
            'terms' => 'video'
        )
    )
);
$query = new WP_Query( $args );
if ( $query->have_posts() ) {
    while ( $query->have_posts() ) {
        $query->the_post();
        ?>
        <img src="<?php echo has_post_thumbnail() ? the_post_thumbnail('thumbnail') : get_thumbnail_fromyoutube(); ?>" alt="<?php the_title(); ?>"/>
        <?php
    }
}
wp_reset_query();
// Khôi phục dữ liệu bài viết toàn cầu bị thay đổi bởi hàm the_post().
?>

