Hàm WordPress để HTML an toàn khi được gửi qua yêu cầu AJAX Cách chính xác để gửi HTML trở lại một yêu cầu AJAX trong WordPress là gì? Tôi hiện đang có đoạn mã sau:
add_action( 'wp_ajax_nopriv_get-location-info', 'sc_locations_get_location_info' );
add_action( 'wp_ajax_get-location-info', 'sc_locations_get_location_info' );

function sc_locations_get_location_info() {
    $nonce = $_POST['nonce'];

    if ( ! wp_verify_nonce( $nonce, 'get-location-info-nonce' ) ) {
        $response = json_encode( array( 'success' => false, 'error' => "Failed nonce check" ) );
    } else {
        $response = json_encode( array( 'success' => true, 'HTML' => '...LOTS OF WONDERFUL HTML...' ) );
    }

    header( "Content-Type: application/json" );
    echo $response;
    exit;
}

Hiện tại tôi chỉ sử dụng hàm json_encode() nhưng liệu tôi có cần phải thực hiện thêm điều gì khác với HTML không? HTML được tạo ra có thể được tin tưởng nên không cần phải loại bỏ bất cứ thứ gì.

404 Vấn đề với Custom Post Type - sử dụng Meta cho Permalink viết lại Tôi đang cố gắng viết lại permalinks sử dụng dữ liệu meta từ bài viết của tôi. Permalink viết lại hoạt động, nhưng tôi gặp vấn đề 404 khi cố gắng xem bài viết. Tôi đã làm sạch bộ nhớ cache bằng cách truy cập trang cài đặt permalink, và vẫn không được. Có ai có thể cho tôi biết lý do tại sao nó không hoạt động?

add_filter('post_type_link','calendar_link_filter',1,3);

function calendar_link_filter( $post_link, $id = 0, $leavename = FALSE ) {
    $post = get_post($id);
    if($post->post_type != 'super_duper') {
        return $post_link;
    }
    $date = get_post_meta($post->ID,'event_start_date',true);
    $date = strtotime($date);
    $str = $post_link;
    $str = str_replace('%cal_year%',date("Y",$date),$str);
    $str = str_replace('%cal_month%',date("m",$date),$str);
    $str = str_replace('%cal_day%',date("d",$date),$str);
    return $str;
}

add_action( 'init', 'create_my_post_types' );

