        array(
            'labels' => array(
                'name' => __( 'Super Dupers' ),
                'singular_name' => __( 'Super Duper' )
            ),
            'hierarchical' => false,
            'show_ui' => true, // UI in admin panel
            'publicly_queryable' => true,
            'rewrite' => true,
            'public' => true,
            'rewrite' => array('slug' => 'events8/%cal_year%/%cal_month%/%cal_day%'),
        )
    );
