    function update($new_instance, $old_instance)
    {
        $instance = $old_instance;

        // Trường
        $instance['title'] = strip_tags($new_instance['title']);

        return $instance;
    }

    function deactivate()
    {
        delete_option('HNDomainSearchWidget');
    }

    // xử lý đầu vào của tiện ích và tìm kiếm tên miền bằng cách sử dụng
    function search_for_domain($search_domain, $permalink)
    {
        $referrer = $_SERVER['HTTP_REFERER'];

        if(isset($search_domain))
        {
            // lấy chi tiết để truy cập
            $hobinom = new hobinom_db();
            $current_user_id = get_current_user_id();
            $details = $hobinom->get_details($current_user_id);
            $username = $details['username'];
            $password = $details['password'];

            // tách dữ liệu từ tên miền và TLD
            // hàm explode biến mỗi dấu chấm tiếp theo thành một mảng mới, vì vậy domain.co.uk là [0],[1],[2] trong khi domain.co là [0][1]
            $root_domain = explode(".", $search_domain);
            $domain = $root_domain[0];
            $tld = substr($search_domain, strrpos($search_domain, ".")+1);

            // truy cập API của Enom
            $url =  '/interface.asp?command=check&sld='.$domain.'&tld='.$tld.
                '&responsetype=xml&uid='.$username.'&w='.$password;

            // Tải kết quả API vào một đối tượng SimpleXML
            $xml = simplexml_load_file($url);

            if(isset($xml->errors))
            {
                // in tất cả các lỗi
                function recursive_print($item, $key)
                {
                    echo '<div id="domain-notavail">'.$item.'</div><br />';
                }
                array_walk_recursive($xml->errors, 'recursive_print');
            }
            else
            {
                // Đọc kết quả
                $rrpCode = $xml->RRPCode;
                $rrpText = $xml->RRPText;

                // Thực hiện các hành động dựa trên kết quả
                switch ($rrpCode)
                {
                    case 210:
                        echo '<div id="domain-avail">'. $xml->DomainName.' là sẵn có</div>';
                        break;
                    case 211:
                        echo '<div id="domain-notavail">'.$xml->DomainName.' không sẵn có</div>';
                        break;
                    default:
                        echo '<div id="domain-default">Mã: '. $rrpCode . ' ' . $rrpText . '</div>';
                        break;
                }
            }

            //$this->hobinom_redirect($referrer);
        }
    }

    function hobinom_redirect($permalink)
    {
        wp_redirect($permalink);
    }
}
add_action('widgets_init', array($HNDomainSearchWidget, 'hobinom_redirect'));
?>

