Google font không hiển thị trong tùy chọn chủ đề. Tôi đã thực hiện hướng dẫn sau trong bảng tùy chọn chủ đề của mình. http://wptheming.com/2012/06/loading-google-fonts-from-theme-options/ Mọi thứ hoạt động tốt. Nhưng trong bảng tùy chọn chủ đề các phông chữ mặc định của hệ thống đang hiển thị trong danh sách thả xuống.

/**
* Trả về một mảng các phông chữ hệ thống
* Cảm thấy tự do để chỉnh sửa điều này, cập nhật các phông chữ dự phòng, v.v.
*/

function options_typography_get_os_fonts() {
// Phông chữ mặc định của hệ điều hành
$os_faces = array(
'Arial, sans-serif' => 'Arial',
'"Avant Garde", sans-serif' => 'Avant Garde',
'Cambria, Georgia, serif' => 'Cambria',
'Copse, sans-serif' => 'Copse',
'Garamond, "Hoefler Text", Times New Roman, Times, serif' => 'Garamond',
'Georgia, serif' => 'Georgia',
'"Helvetica Neue", Helvetica, sans-serif' => 'Helvetica Neue',
'Tahoma, Geneva, sans-serif' => 'Tahoma'
);
return $os_faces;
}

/**
* Trả về một danh sách chọn của các phông chữ Google
* Cảm thấy tự do để chỉnh sửa điều này, cập nhật các phông chữ dự phòng, v.v.
*/

function options_typography_get_google_fonts() {
// Phông chữ mặc định của Google
$google_faces = array(
'Arvo, serif' => 'Arvo',
'Copse, sans-serif' => 'Copse',
'Droid Sans, sans-serif' => 'Droid Sans',
'Droid Serif, serif' => 'Droid Serif',
'Lobster, cursive' => 'Lobster',
'Nobile, sans-serif' => 'Nobile',
'Open Sans, sans-serif' => 'Open Sans',
'Oswald, sans-serif' => 'Oswald',
'Pacifico, cursive' => 'Pacifico',
'Rokkitt, serif' => 'Rokkit',
'PT Sans, sans-serif' => 'PT Sans',
'Quattrocento, serif' => 'Quattrocento',
'Raleway, cursive' => 'Raleway',
'Ubuntu, sans-serif' => 'Ubuntu',
'Yanone Kaffeesatz, sans-serif' => 'Yanone Kaffeesatz'
);
return $google_faces;
}

/**
* Kiểm tra các tùy chọn phông chữ để xem nếu một phông chữ Google được chọn.
* Nếu vậy, options_typography_enqueue_google_font được gọi để xếp hàng phông chữ.
* Đảm bảo rằng mỗi phông chữ Google chỉ được xếp hàng một lần.
*/

function options_typography_google_fonts() {
$all_google_fonts = array_keys( options_typography_get_google_fonts() );
// Định nghĩa tất cả các tùy chọn có thể có một phông chữ Google duy nhất
$google_font = woodpecker_get_option('google_font', 'Rokkitt, serif');
$google_mixed = woodpecker_get_option('google_mixed', false);
$google_mixed_2 = woodpecker_get_option('google_mixed_2', 'Arvo, serif');
// Nhận được mặt phông chữ cho từng tùy chọn và đặt nó vào một mảng
$selected_fonts = array(
$google_font['face'],
$google_mixed['face'],
$google_mixed_2['face']
);
// Loại bỏ bất kỳ bản sao nào trong danh sách
$selected_fonts = array_unique($selected_fonts);
// Kiểm tra từng phông chữ duy nhất so với các phông chữ Google được xác định
// Nếu nó là một phông chữ Google, hãy tiến hành gọi hàm để xếp hàng nó
foreach ( $selected_fonts as $font ) {
if ( in_array( $font, $all_google_fonts ) ) {
options_typography_enqueue_google_font($font);
}
}
}

add_action( 'wp_enqueue_scripts', 'options_typography_google_fonts' );

/**
* Xếp hàng phông chữ Google được truyền qua
*/

function options_typography_enqueue_google_font($font) {
$font = explode(',', $font);
$font = $font[0];
// Một số phông chữ Google cần những thay đổi nhỏ để tải đúng cách
// Như người bạn của chúng tôi "Raleway"
if ( $font == 'Raleway' )
$font = 'Raleway:100';
$font = str_replace(" ", "+", $font);
wp_enqueue_style( "options_typography_$font", "http://fonts.googleapis.com/css?family=$font", false, null, 'all' );
}

/*
* Đầu ra các kiểu bảng điều khiển tùy chọn được chọn inline vào <head>
*/

function options_typography_styles() {
$output = '';
$input = '';
if ( woodpecker_get_option( 'google_font' ) ) {
$input = woodpecker_get_option( 'google_font' );
$output .= options_typography_font_styles( woodpecker_get_option( 'google_font' ) , '.google-font');
}
if ( $output != '' ) {
$output = "\n<style>\n" . $output . "</style>\n";
echo $output;
}
}

add_action('wp_head', 'options_typography_styles');

// Trả về một tùy chọn phông chữ ở định dạng có thể đầu ra như CSS inline

function options_typography_font_styles($option, $selectors) {
$output = $selectors . ' {';
$output .= ' color:' . $option['color'] .'; ';
$output .= 'font-family:' . $option['face'] . '; ';
$output .= 'font-weight:' . $option['style'] . '; ';
$output .= 'font-size:' . $option['size'] . '; ';
$output .= '}';
$output .= "\n";
return $output;
}

