CẬP NHẬT: Tôi đã tìm thấy rằng tôi có thể gọi WP_Filesystem() trực tiếp để tạo ra nó, vì vậy tôi đang nhận được zip trích xuất tốt, bây giờ vấn đề là tập tin zip được sao chép đến thư mục đích thay vì bị xóa như phương pháp ZipArchive của tôi làm.

require('../../../wp-blog-header.php');
require('../../../wp-admin/includes/file.php');
function openZip($file_to_open) {
global $target;
global $wp_filesystem;
if(class_exists('ZipArchive')) {
$zip = new ZipArchive();
$x = $zip->open($file_to_open);
if($x === true) {
$zip->extractTo($target);
$zip->close();
unlink($file_to_open);
} else {
die("Có một vấn đề. Vui lòng thử lại!");
}
} else {
WP_Filesystem();
