Gọi clean_term_cache() thất bại khi gọi trong cùng một plugin tạo ra các điều khoản, thành công khi gọi riêng biệt? Mã plugin của tôi ở dưới đây. Trong hàm myPlugin_cleanup(), tôi tạo một số danh mục và gán ID thuật ngữ 1 làm parent. Do lỗi **biết trước khi tạo các danh mục qua script** (hàm array category_children không được tạo ra và dẫn đến lỗi nghiêm trọng khi truy cập trang chứa danh sách danh mục), tôi đã đặt cuộc gọi clean_term_cache() trực tiếp bên dưới hàm tạo các danh mục của tôi. Tuy nhiên, nó không hoạt động. Tùy chọn category_children không được tạo ra. Thú vị là, nếu tôi tạo một plugin mà chức năng duy nhất là thực thi cuộc gọi clean_term_cache('', 'category'), nó sẽ giải quyết vấn đề này và tạo tùy chọn category_children với các giá trị chính xác. Tôi chỉ không chắc tại sao nó lại không hoạt động trong cùng một plugin mà tạo các danh mục. Tôi có thể bỏ lỡ điều gì?

function myPlugin_activate(){
    if ( get_option( 'myPlugin_activated' ) !== "1"){
        //bỏ qua bất kỳ hàm nào bạn không muốn chạy
        myPlugin_copy('themes');
        myPlugin_copy('plugins');
        myPlugin_images();
        myPlugin_options();
        myPlugin_settings();
        myPlugin_widgets();
        myPlugin_links();
        myPlugin_posts();
        myPlugin_pages();
        myPlugin_custom_menus();
        myPlugin_cleanup();
        clean_term_cache('','category'); //không hoạt động ở đây
        update_option('myPlugin_activated', "1");
    }
}

function myPlugin_cleanup(){
    //bao gồm các phụ thuộc
    require_once(ABSPATH.'/wp-admin/includes/taxonomy.php');
    if(!get_cat_ID('nofollow')){wp_create_category('nofollow',1);}
    if(!get_cat_ID('noindex')){wp_create_category('noindex',1);}
    clean_term_cache('','category'); //cũng không hoạt động ở đây
}

register_activation_hook(__FILE__, 'myPlugin_activate');

