Tuỳ chỉnh bài viết loại bài viết trích đoạn nhiều hơn và độ dài của trích đoạn Tôi đã viết một số mã để nhận được "excerpt_length" và "excerpt_more" tùy chỉnh. excerpt_length hoạt động cho cả kiểu bài viết tùy chỉnh và bài viết thông thường. Nhưng tôi không biết tại sao "excerpt_more" không hoạt động cho các loại bài viết tùy chỉnh. Mã của tôi như sau:

class Excerpt {
// Độ dài mặc định (bởi WordPress)
public static $length = 55;
// Vì vậy bạn có thể gọi: doctoplus_excerpt('short');
public static $types = array(
'ten' => 10,
'few' => 15,
'short' => 25,
'regular' => 55,
'long' => 100
);
// More mặc định
public static $more = '...';
// Vì vậy bạn có thể gọi doctoplus_excerpt('short', 'Read More');
public static $moreTypes = array(
1 => 'Read More',
2 => 'More',
3 => 'Xem thêm'
);
/**
* Thiết lập độ dài cho đoạn trích dẫn,
* sau đó nó thêm bộ lọc WP
* Và tự động gọi the_excerpt();
*
* @param string $new_length
* @return void
* @author Girija
*/
public static function length($new_length = 55) {
Excerpt::$length = $new_length;
add_filter('excerpt_length', 'Excerpt::new_length', 999);
Excerpt::output();
}
// Cho WP biết độ dài mới
public static function new_length() {
if( isset(Excerpt::$types[Excerpt::$length]) )
return Excerpt::$types[Excerpt::$length];
else
return Excerpt::$length;
}
public static function more($new_more = 'Read More') {
Excerpt::$more = $new_more;
add_filter('excerpt_more', 'Excerpt::new_more', 999);
}
// Cho WP biết More tùy chỉnh
public static function new_more() {
global $post;
if(isset(Excerpt::$moreTypes[Excerpt::$more]) ) {
return ' <a class="more-link" href="'. get_permalink($post->ID) . '">'. __(Excerpt::$moreTypes[Excerpt::$more], 'doctoplus') .'</a>';
} else {
return Excerpt::$more;
}
}
// Đưa ra đoạn trích dẫn
public static function output() {
the_excerpt();
}
}
// Một tên gọi khác cho lớp
function doctoplus_excerpt($length = 55, $more = "...") {
Excerpt::length($length);
Excerpt::more($more);
}

