Truy vấn tùy chỉnh trực tiếp can thiệp vào các truy vấn khác trên trang Trong câu hỏi trước, tôi đã gặp khó khăn trong việc cách để hiển thị các loại bài viết tùy chỉnh của tôi khi thực hiện các truy vấn tiêu đề/ thẻ tiêu chuẩn, vì mặc định Wordpress không bao gồm CPT trong các truy vấn này. Sau một thời gian tìm kiếm, tôi đã tìm được câu trả lời cho vấn đề này:

add_filter('pre_get_posts', 'query_post_type');

function query_post_type($query) {
  if($query->is_category() || $query->is_tag() || $query->is_home() && $query->is_main_query()) {
    $post_type = get_query_var('post_type');
    if($post_type)
      $post_type = $post_type;
    else
      $post_type = array('post','my_custom_post_type');
    $query->set('post_type',$post_type);
    return $query;
  }
}

Và nó hoạt động rất tốt... Tôi có thể gán các danh mục/ thẻ cho các loại bài viết tùy chỉnh của mình, và sau đó truy vấn chúng và xem kết quả. Tuy nhiên, với đoạn mã này, tôi lại gặp phải một vấn đề hoàn toàn mới chỉ xảy ra khi đoạn mã trên được thêm vào... nếu tôi truy vấn hoặc xem trực tiếp loại bài viết tùy chỉnh của mình (nghĩa là không qua danh mục/ thẻ), thì đột nhiên các mục truy vấn tiêu chuẩn trên trang (như danh sách danh mục trong chân trang) lại trống. Tôi không hiểu làm thế nào điều này có thể xảy ra, vì tôi đã kiểm tra để đảm bảo rằng $query->is_main_query(), vì vậy câu lệnh if ban đầu sẽ trả về giá trị sai... Liệu tôi có cần viết một hàm riêng biệt nữa để khi tôi truy vấn hoặc xem trực tiếp một loại bài viết tùy chỉnh, tôi có thể cho phép các loại bài viết tiêu chuẩn hoạt động trên cùng một trang hay không? Mọi sự giúp đỡ đều được đánh giá cao...

* * *

CẬP NHẬT:

Cảm ơn những bình luận của bạn, tôi đã tìm ra lý do tại sao điều này gây ra vấn đề: Khi tôi có giải pháp ban đầu (không được hiển thị trong bài đăng này), mọi thứ hoạt động tốt với các truy vấn cơ bản từ các loại bài viết tiêu chuẩn và CPT - nhưng khi tôi tiến triển đến nhiều truy vấn, tôi nhận ra rằng trong một số trường hợp, chẳng hạn như các trang có truy vấn phân tán, ở trang chính, một số ở chân trang, đột nhiên tôi gặp phải hiệu ứng chéo - ví dụ như menu của tôi đôi khi biến mất. Đó là lúc tôi thêm vào điều kiện $query->is_main_query() (xem mã đầy đủ ở trên) - và tất nhiên nó hoạt động tốt hơn sau đó, bởi vì tôi chỉ áp dụng điều này cho truy vấn chính, do đó tránh được các vấn đề liên quan đến menu/ chân trang... hoặc ít nhất là tôi nghĩ là như vậy. Từ khi thêm phiên bản mới của mã này, mọi thứ đều ổn - cho đến khi tôi truy vấn trực tiếp CPT của mình... khi tôi làm điều đó, một trong những widget chân trang tiêu chuẩn của tôi (gọi một truy vấn danh mục đơn giản) lại trống. Khi tôi bắt đầu xem xét vấn đề này, tôi thấy rằng trong câu lệnh IF ban đầu trong mã ở trên, nó thực hiện một "OR OR OR AND" - trong khi về mặt kỹ thuật, để giữ cho mã này chỉ ảnh hưởng đến truy vấn chính, tôi cần phải thực hiện một cái gì đó giống như "(( OR OR OR ) AND)" - hoặc, bao bọc toàn bộ hàm trong một câu lệnh if ($query->is_main_query()).

Vì vậy, tôi đã thực hiện điều đó (xem bên dưới)... và khi tôi làm vậy, nó đã giải quyết được vấn đề "gọi trực tiếp CPT" - cho phép tôi truy vấn trực tiếp một CPT mà không làm hỏng truy vấn chân trang.

add_filter('pre_get_posts', 'query_post_type');

function query_post_type($query) {
  if ($query->is_main_query()) {
    if($query->is_category() || $query->is_tag() || $query->is_home() ) {
      $post_type = get_query_var('post_type');
      if($post_type)
        $post_type = $post_type;
      else
        $post_type = array('post','my_custom_post_type');
      $query->set('post_type',$post_type);
      return $query;
    }
  }
}

Vậy thì, điều này nghe có vẻ tuyệt vời, phải không? Nhưng không... bởi vì phiên bản đầu tiên của mã này không được thiết lập theo ý định của tôi, nó cho phép CPT của tôi được thêm vào các truy vấn tiêu đề/ thẻ tiêu chuẩn vào những thời điểm không phải là truy vấn chính... vì vậy bây giờ khi tôi đã lọc chính thức điều này để chỉ ảnh hưởng đến truy vấn chính trong mọi trường hợp, các cuộc gọi Tab trên trang của tôi đã thất bại. (Những cuộc gọi này đang gọi CPT của tôi thông qua danh mục trong các tab jQuery trên mỗi trang). Vì vậy, câu hỏi mới của tôi là: cho phiên bản mã THỨ HAI của tôi ở trên, cho phép tôi kết hợp CPT vào các truy vấn tiêu đề/ thẻ tiêu chuẩn, và truy vấn trực tiếp CPT, mà không ảnh hưởng xấu đến các truy vấn khác trên trang - làm thế nào tôi có thể xác định các cuộc gọi Tab đang thực hiện? Bởi vì nó rõ ràng không phải là truy vấn chính - và do đó, tôi cần phải nhắm mục tiêu chúng để tôi có thể bao gồm CPT của mình, giống như tôi đã làm với truy vấn chính?

Bootstrap Nav Menu không hiển thị nhiều hơn 1 menu thả xuống Tôi có đoạn mã sau để hiển thị menu điều hướng trong tệp `functions.php`.

```php
class BootstrapNavMenuWalker extends Walker_Nav_Menu {
    function start_lvl( &$output, $depth = 0, $args = array() ) {
        $indent = str_repeat( "\t", $depth );
        $submenu = ($depth > 0) ? ' sub-menu' : '';
        $output    .= "\n$indent<ul class=\"dropdown-menu$submenu depth_$depth\">\n";
    }

    function start_el( &$output, $item, $depth = 0, $args = array(), $id = 0 ) {
        $indent = ( $depth ) ? str_repeat( "\t", $depth ) : '';
        $li_attributes = '';
        $class_names = $value = '';
        $classes = empty( $item->classes ) ? array() : (array) $item->classes;

        // quản lý ngăn cách: thêm lớp ngăn cách vào một phần tử để có được ngăn cách trước nó.
        $divider_class_position = array_search('divider', $classes);
        if($divider_class_position !== false){
            $output .= "<li class=\"divider\"></li>\n";
            unset($classes[$divider_class_position]);
        }

        $classes[] = ($args->has_children) ? 'dropdown' : '';
        $classes[] = ($item->current || $item->current_item_ancestor) ? 'active' : '';
        $classes[] = 'menu-item-' . $item->ID;
        if($depth && $args->has_children){
            $classes[] = 'dropdown-submenu';
        }

        $class_names = join( ' ', apply_filters( 'nav_menu_css_class', array_filter( $classes ), $item, $args ) );
        $class_names = ' class="' . esc_attr( $class_names ) . '"';

        $id = apply_filters( 'nav_menu_item_id', 'menu-item-'. $item->ID, $item, $args );
        $id = strlen( $id ) ? ' id="' . esc_attr( $id ) . '"' : '';

        $output .= $indent . '<li' . $id . $value . $class_names . $li_attributes . '>';

        $attributes  = ! empty( $item->attr_title ) ? ' title="'  . esc_attr( $item->attr_title ) .'"' : '';
        $attributes .= ! empty( $item->target )     ? ' target="' . esc_attr( $item->target     ) .'"' : '';
        $attributes .= ! empty( $item->xfn )        ? ' rel="'    . esc_attr( $item->xfn        ) .'"' : '';
        $attributes .= ! empty( $item->url )        ? ' href="'   . esc_attr( $item->url        ) .'"' : '';
        $attributes .= ($args->has_children)        ? ' class="dropdown-toggle" data-toggle="dropdown"' : '';

        $item_output = $args->before;
        $item_output .= '<a'. $attributes .'>';
        $item_output .= $args->link_before . apply_filters( 'the_title', $item->title, $item->ID ) . $args->link_after;
        $item_output .= ($depth == 0 && $args->has_children) ? ' <b class="caret"></b></a>' : '</a>';
        $item_output .= $args->after;

        $output .= apply_filters( 'walker_nav_menu_start_el', $item_output, $item, $depth, $args );
    }

    function display_element( $element, &$children_elements, $max_depth, $depth=0, $args, &$output ) {
        //v($element);
        if ( !$element )
            return;

        $id_field = $this->db_fields['id'];

        //hiển thị phần tử này
        if ( is_array( $args[0] ) )
            $args[0]['has_children'] = ! empty( $children_elements[$element->$id_field] );
        else if ( is_object( $args[0] ) )
            $args[0]->has_children = ! empty( $children_elements[$element->$id_field] );

        $cb_args = array_merge( array(&$output, $element, $depth), $args);
        call_user_func_array(array(&$this, 'start_el'), $cb_args);

        $id = $element->$id_field;

        //chỉ đi xuống khi độ sâu là đúng và có các phần tử con cho phần tử này
        if ( ($max_depth == 0 || $max_depth > $depth+1 ) && isset( $children_elements[$id]) ) {
            foreach( $children_elements[ $id ] as $child ){
                if ( !isset($newlevel) ) {
                    $newlevel = true;
                    //bắt đầu ngăn cách con
                    $cb_args = array_merge( array(&$output, $depth), $args);
                    call_user_func_array(array(&$this, 'start_lvl'), $cb_args);
                }

                $this->display_element( $child, $children_elements, $max_depth, $depth + 1, $args, $output );
            }

            unset( $children_elements[ $id ] );
        }

        if ( isset($newlevel) && $newlevel ){
            //kết thúc ngăn cách con
            $cb_args = array_merge( array(&$output, $depth), $args);
            call_user_func_array(array(&$this, 'end_lvl'), $cb_args);
        }

        // kết thúc phần tử này
        $cb_args = array_merge( array(&$output, $element, $depth), $args);
        call_user_func_array(array(&$this, 'end_el'), $cb_args);
    }
}

