Hiển thị tất cả bài viết từ tất cả các loại bài viết trong hậu trường quản trị viên Tôi đang cố gắng tạo một trang quản trị để hiển thị tất cả các bài viết từ các loại bài viết tùy chỉnh. Nó giống như trang edit.php, nhưng thay vì hiển thị một loại bài viết, tôi muốn hiển thị tất cả các bài viết trên một trang từ nhiều loại bài viết tùy chỉnh. Tôi đã làm theo hướng dẫn tại đây để tạo bảng. Mọi thứ đều ổn, nhưng có một số điều mà tôi không thể giải quyết được. Thực ra vấn đề chủ yếu ở PHP hơn là WordPress. Đây là những gì tôi đang làm: truy vấn các bài viết từ các loại bài viết tùy chỉnh mong muốn và lưu trữ đối tượng trả về trong mảng để sử dụng sau này. Đây là mã của tôi:

function getallposts() {
    global $current_user; // tôi cần hiển thị các bài viết dựa trên ID người dùng.
    get_currentuserinfo();
    if(!current_user_can('administrator') && current_user_can('edit_posts') ) {
        $userid = $current_user->ID;
    } elseif(current_user_can('administrator')) {$userid='1';} // người dùng quản trị viên có thể xem tất cả các bài viết, nhưng người dùng chỉ có thể xem các bài viết của riêng họ
    $args = array(
        'numberposts'     => -1,
        'offset'          => 0,
        'orderby'         => 'post_date',
        'order'           => 'DESC',
        'post_type'       => array('cpt1','cpt2'),//loại bài viết cần truy vấn
        'author'          => $userid,//tham chiếu đến thông tin đăng nhập người dùng ở trên
        'post_status'     => 'publish'
    );
    $myposts = get_posts( $args );//ở đây sử dụng get_posts để truy vấn bài viết.
    $myitems =array();//khai báo mảng.
    foreach ($myposts as $post) {
        $metavalue = get_post_meta($post->ID, 'rating', true); //lấy giá trị meta cho bài viết
        $myitems =array (
            'post_title' => $post->post_title,
            'ID'=>$post->ID,
            'post_author'=> $post->post_author,
            'post_date' => $post->post_date,
            'rating' =>$metavalue
        ); // tôi muốn lưu nó trong một mảng để sử dụng sau này. không biết tôi có làm đúng không.
    }
    return $myitems;//ở đây tôi không có ý tưởng nào để trả về mảng từ $myitems ở trên
}

