function mmp_rewrite_rules($rules)
{
    $newRules = array();
    $newRules['episodes/(.+)/(.+)/(.+)/(.+)/?$'] = 'index.php?custom_post_type_name=$matches[3]'; // cấu trúc tùy chỉnh của tôi sẽ luôn có tên bài viết ở phân đoạn thứ 5 của URI
