Đặt hàng các kịch bản dựa trên tùy chọn Phương pháp tốt nhất để thêm các script dựa trên các tùy chọn mà tôi có là gì? Giả sử tôi có 50 tùy chọn và đối với mỗi tùy chọn tôi cần thêm một script (một số trong đó có thể lặp lại). Nếu tôi thực hiện việc này trong một vòng lặp foreach và chuyển đổi sang phát hiện script nào tôi cần, tôi sẽ gặp phải vấn đề gì (hiệu năng, v.v.)? Bạn có nghĩ rằng cách này tốt hơn so với việc gọi tất cả các script bất kể các tùy chọn mà tôi có không? Ví dụ như sau (lớp hoạt động giống như tôi cần):

<?php
class MyClass {
    var $options;

    public function __construct($options) {
        $this->options = (isset($options)) ? $options : array();
        add_action('admin_enqueue_scripts', array(&$this, 'enqueue'));
    }

    // Đây là phần mà tôi thêm các script
    function enqueue() {
        foreach ($this->options as $value) {
            switch ($value['type']) {
                case 'value1':
                    wp_enqueue_script('value1_script');
                    break;
                case 'value2':
                    wp_enqueue_script('value2_script');
                    break;
            }
        }
    }

    function render_opts() {
        $output = '';
        foreach ($this->options as $value) {
            switch ($value['type']) {
                case 'value1':
                    $output .= 'value1';
                    break;
                case 'value2':
                    $output .= 'value2';
                    break;
            }
        }
        return $output;
    }
}

