Custom WordPress user permalink Tôi có một chút vấn đề với trang wordpress của tôi. Tôi cần thay đổi liên kết vĩnh viễn của người dùng. Liên kết vĩnh viễn nên chứa dữ liệu từ bảng wp_usermeta. Tôi đã tạo một số hàm và các liên kết đã được thay đổi, nhưng khi tôi truy cập chúng thì nó nói: Trang không tìm thấy. Tôi sẽ mua cho bạn một cốc bia nếu bạn có thể cho tôi biết lỗi trong mã của tôi là gì. Đây là mã:

add_filter( 'request', 'wpse5742_request' );

function wpse5742_request( $query_vars ) {
    if ( array_key_exists( 'author_name', $query_vars ) ) {
        global $wpdb;
        $author_id = $wpdb->get_var( $wpdb->prepare( "SELECT user_id FROM {$wpdb->usermeta} WHERE meta_key='nickname' AND meta_value = %s", $query_vars['author_name'] ) );
        $query_vars['author'] = $author_id;
        unset( $query_vars['author_name'] );
    }
    return $query_vars;
}

add_filter( 'author_link', 'wpse5742_author_link', 10, 3 );

function wpse5742_author_link( $link, $author_id, $author_nicename ) {
    $part1 = get_user_meta( $author_id, 'nickname', true );
    $part2 = get_user_meta( $author_id, '_themex_city', true );
    $part3 = get_user_meta( $author_id, '_themex_thesubject', true );
    $newlink = $part1.'/'.$part2.'/'.$part3;

    if ( $newlink ) {
        $link = str_replace( $author_nicename, $newlink, $link );
    }

    return $link;
}

add_action( 'user_profile_update_errors', 'wpse5742_set_user_nicename_to_nickname', 10, 3 );

function wpse5742_set_user_nicename_to_nickname( &$errors, $update, &$user ) {
    if ( ! empty( $user->nickname ) ) {
        $user->user_nicename = sanitize_title( $user->nickname, $user->display_name );
    }
}

