template_redirect được gọi hai lần Tôi đang viết một plugin chuyển hướng đơn giản mà khớp với slug đã cho và chuyển hướng đến URL được chỉ định, nó hoạt động tốt. Nhưng gần đây tôi đã thêm chức năng cập nhật số liệu thống kê cho slug được truy cập và tôi phát hiện ra rằng câu lệnh cập nhật của tôi được gọi hai lần, tôi kiểm tra và thấy rằng hook `template_redirect` được gọi hai lần. Câu lệnh cập nhật số liệu thống kê của tôi chỉ được thực thi một lần. Đây là mã nguồn của tôi:
add_action("template_redirect", array($this, "redirection_section"), 11);
function redirection_section() {
    if( is_404() )
        $this->uni_page_redirect();
}
function uni_page_redirect() {
    include_once dirname(__FILE__) . '/uni_links.php';
    $Links = new UNI_Links();
    $slug = ltrim(preg_replace('#/$#', '', urldecode($_SERVER['REQUEST_URI'])), '/');
    if( $Links->is_valid_slug($slug) ) {
        // Khởi tạo với Slug
        do_action("ulr_init_slug", $slug);
        $Links->generate_links($slug);
        exit();
    }
    return false;
}
Đây là cách tôi cập nhật câu lệnh:
function slug_init_callback($slug_name) {
    global $wpdb;
    $table_slugs = ULR_TABLE_SLUGS;
    // Debug để kiểm tra các cuộc gọi
    file_put_contents(PLUGIN_BASE . '/debug.txt', "call \r\n", FILE_APPEND);
    $sql = $wpdb->prepare("update {$table_slugs} set stat= stat+1 where slug_name=%s", $slug_name);
    $wpdb->query($sql);
}
