    nếu (!current_user_can('edit_post', $post_id)) {
        trả về $post_id;
    }

    $team_meta = mảng (
        '_department' => $_POST['_department'],
        '_languages' => $_POST['_languages'] // Ngôn ngữ là đầu vào văn bản được lưu trữ mà không có vấn đề.
    );

    foreach ($team_meta as $key => $value) {
        nếu (get_post_meta($post_id, $key, FALSE)) {
            update_post_meta($post_id, $key, $value);
        } khác {
            add_post_meta($post_id, $key, $value);
        }

        nếu (!$value) {
            xóa_post_meta($post_id, $key);
        }
    }
}

