function mp_faq_shortcode() {
    /* Truy vấn các câu hỏi từ cơ sở dữ liệu */
    $loop = new WP_Query( array(
        'post_type' => 'faq_type_mp',
        'orderby' => 'title',
        'order' => 'ASC',
        'post_per_page' => -1,
    ) );

    /* Kiểm tra xem có trả về câu hỏi nào không */
    if ($loop->have_posts() ) {
        /* Mở một danh sách không sắp xếp */
        $output = '';

        /* Duyệt qua các câu hỏi (Vòng lặp) */
        while ($loop->have_posts() ) {
            $loop->the_post();

            /* Hiển thị câu hỏi */
            $output .= post_title() ,
        }

        /* Đóng danh sách không sắp xếp */
        $output .= '';
    }

    /* Nếu không tìm thấy câu hỏi nào */
    else {
        $output = 'Chưa có câu hỏi nào được xuất bản.';
    }

    /* Trả về danh sách câu hỏi */
    return $output;
}

