Đừng gửi thông báo nếu tác giả bình luận bài đăng của chính mình plugin giúp? Có cách nào để thiết lập một câu lệnh IF, nếu tác giả của bài viết bình luận hoặc trả lời trên bài viết của mình mà không nhận được thông báo từ WordPress, chỉ khi một người dùng khác bình luận thì mới nhận được thông báo. Tôi đang sử dụng plugin Notify on Comment.

<?php
/*
Plugin Name: Notify on comment
Plugin URI: http://www.artbits.it
Description: Send a notification on comment to the author of the post
Version: 1.03
Author: Fabio Trezzi
Author URI: http://www.artbits.it
*/
function notifyOnComment_send($commentID){
global $wpdb;
// Get the email of the post's author
$comment = get_comment($commentID);
$post = get_post($comment->comment_post_ID);
$user = get_userdata($post->post_author);
$to = $user->user_email;
// Set the send from
$admin_email = get_option('admin_email');
$headers= "From:noreply@bonetoz.com\r\n";
$headers .= "Reply-To:$noreply@bonetoz.com\r\n";
$headers .= "X-Mailer: PHP/".phpversion();
$comment_author_domain = @gethostbyaddr($comment->comment_author_IP);
$comments_waiting = $wpdb->get_var("SELECT count(comment_ID) FROM $wpdb->comments WHERE comment_approved = '0'");
$moderationOpt = get_option('notifyOnComments_moderationRequired');
if($moderationOpt == 'true'){
// Only send the notification if the comments requires to be moderated
$approved = $comment->comment_approved;
if($approved != 0) return; // No need to send the mail the comment is already approved
}
$template = get_option('notifyOnComments_emailTemplate');
// If not setted load the default from file
if($template || $template == "") $template = file_get_contents(dirname(__FILE__) . '/defaultTemplate.php');
// Replace all the constant with the rights values
$template = str_replace("{postID}", $post->ID, $template);
$template = str_replace("{postTitle}", $post->post_title, $template);
$template = str_replace("{author}", $comment->comment_author, $template);
$template = str_replace("{authorIp}", $comment->comment_author_IP, $template);
$template = str_replace("{authorDomain}", $comment_author_domain, $template);
$template = str_replace("{authorEmail}", $comment->comment_author_email, $template);
$template = str_replace("{authorUrl}", $comment->comment_author_url, $template);
$template = str_replace("{commentContent}", $comment->comment_content, $template);
$template = str_replace("{commentLink}", get_permalink($comment->comment_post_ID), $template);
$template = str_replace("{commentID}", $commentID, $template);
$template = str_replace("{commentsWaiting}", $comments_waiting, $template);
$template = str_replace("{siteUrl}", get_option('siteurl'), $template);
$subject = sprintf( __('[%1$s] Please moderate: "%2$s"'), get_option('blogname'), $post->post_title );
@wp_mail($to, $subject, $template, $headers);
return true;
}
function notifyOnComment_menu() {
$path = dirname(__FILE__);
$pathElements = explode('/', $path);
add_options_page('NotifyOnComments options', 'NotifyOnComments', 'manage_options', $pathElements[count($pathElements) - 1] . '/options.php');
}
add_action('comment_post', 'notifyOnComment_send');
add_action('admin_menu', 'notifyOnComment_menu');
?>

Làm thế nào để tôi có được một hình ảnh từ thư mục uploads và vào thư viện media? Tôi muốn viết một đoạn mã:

1. Lấy hình ảnh từ nội dung bài viết và xóa nó (nó được lưu trữ trên một trang web khác)
2. Tải lên thư mục tải lên
3. Thêm nó vào thư viện phương tiện truyền thông và
4. Cuối cùng trả về nội dung với hình ảnh được lưu trên máy chủ. Tôi không thể thực hiện bước thứ ba.

Vấn đề là với 'wp_insert_attachment', mỗi khi nó được chạy bên trong một hàm được gọi bởi 'add_filter', hoặc Apache trả về "Lỗi PHP nghiêm trọng: Kích thước bộ nhớ được phép" (giới hạn bộ nhớ PHP của tôi là 124MB) hoặc trang tiếp tục tải mãi mãi. Vấn đề tương tự không xảy ra khi 'wp_insert_attachment' chạy bên ngoài một hàm được gọi bởi 'add_filter'. Tôi không thể đặt nó bên ngoài vì tôi muốn cho nó dữ liệu $image_path nhận được từ hàm download_image. Tôi cũng đã thử gọi một hàm riêng biệt thực hiện bước 3, chạy từ bên trong hàm download_image, với $image_path được truyền như một biến nhưng vấn đề tương tự vẫn xảy ra. Tại sao điều đó xảy ra, bạn có ý tưởng nào để giải quyết nó không?

add_filter('content_save_pre', 'download_image');

function download_image($content_save_pre)
{
preg_match('/<img[^<]+>/i', $content_save_pre, $result); // Tìm hình ảnh đầu tiên với thẻ
$image_tags = $result[0]; // Lưu hình ảnh với thẻ
$content_save_pre = str_replace($image_tags, '', $content_save_pre); // Xóa hình ảnh với thẻ
preg_match('/http[^"]+/i', $result[0], $result); // Tìm URL
$url_only = $result[0];
preg_match('/[^\/]+$/i', $result[0], $result); // Tìm tên tệp
$filename = $result[0];
$uploads = wp_upload_dir(); // Tìm đường dẫn thư mục tải lên
$uploads_path = $uploads['path'];
$uploads_url = $uploads['url'];
$image = file_get_contents($url_only); // Lưu hình ảnh trong thư mục tải lên
file_put_contents($uploads_path . '/' . $filename, $image);
$image_url = $uploads_url . '/' . $filename; // URL của hình ảnh trên đĩa
$image_path = $uploads_path . '/' . $filename; // Đường dẫn của hình ảnh trên đĩa
// Thêm hình ảnh vào thư viện phương tiện - Bước 3
$wp_filetype = wp_check_filetype(basename($image_path), null);
$attachment = array(
'post_mime_type' => $wp_filetype['type'],
'post_title' => preg_replace('/\.[^.]+$/', '', basename($image_path)),
'post_content' => '',
'post_status' => 'inherit'
);
$attach_id = wp_insert_attachment($attachment, $image_path);
require_once(ABSPATH . 'wp-admin/includes/image.php');
$attach_data = wp_generate_attachment_metadata($attach_id, $image_path);
wp_update_attachment_metadata($attach_id, $attach_data);
return '<img src="' . $image_url . '"/>' . $content_save_pre; // Trả về nội dung với hình ảnh được lưu trên máy chủ
}

