VỚI #2: Trích Xuất Hình Ảnh Đầu Tiên Trực Tiếp Từ Nội Dung Bài Viết

// MÃ NÀY TRÍCH EXTRACT HÌNH ẢNH ĐẦU TIÊN TRỰC TIẾP TỪ NỘI DUNG BÀI VIẾT

function bm_extract_string($start, $end, $original) {

$original = stristr($original, $start);

$trimmed = stristr($original, $end);

return substr($original, strlen($start), -strlen($trimmed));

}

function getFirstImage() {

$content = get_the_content();

$pic_string = bm_extract_string('src="','" ',$content);

$imagesize = getimagesize($pic_string);

list($width, $height, $type, $attr) = getimagesize($pic_string);

$link = get_permalink();

$title = get_the_title($post->post_title);

echo '<a href="'.$link.'" style="background:url('.$pic_string.'); display:block; width:'.$width.'px; height:'.$height.'px;" title="'.$title.'"></a>';

}

Breadcrumbs: Kết quả tìm kiếm không hiển thị khi trang tĩnh được hiển thị trên cùng À, đây là một vấn đề khá kỳ lạ và tôi đang cố gắng đảm bảo rằng tôi giải thích nó đủ tốt để bạn hiểu được vấn đề mà tôi đang nói đến. Vì vậy, tôi đang sử dụng các phần tử đường dẫn trong khu vực tiêu đề. Tất cả đều hoạt động tốt. Tuy nhiên, khi bạn nhập vào một tìm kiếm, nó chỉ đôi khi hiển thị kết quả tìm kiếm thực sự trong các phần tử đường dẫn. Nó phải trông giống như thế này: Trang chủ » Blog » Kết quả tìm kiếm cho "lorem" Xem trực tiếp. Tuy nhiên, nếu kết quả tìm kiếm đầu tiên (một cái đang được hiển thị ở trên tất cả những cái khác) là một trang tĩnh thay vì một bài viết trên blog, các phần tử đường dẫn hiển thị nó theo cách này: Trang chủ » Blog » Trang Xem trực tiếp. Nó vẫn hiển thị đúng trong tab của trình duyệt của tôi. Chỉ có các phần tử đường dẫn dường như bị nhầm lẫn. Đây là đoạn mã tôi dùng cho các phần tử đường dẫn:

function dimox_breadcrumbs() {
$delimiter = '<span class="delimiter">&raquo;</span>';
$home = 'Trang chủ'; // văn bản cho liên kết 'Trang chủ'
$before = '<span class="current">'; // thẻ trước phần tử đường dẫn hiện tại
$after = '</span>'; // thẻ sau phần tử đường dẫn hiện tại
if ( !is_front_page() || is_paged() ) {
echo '<div id="crumbs">';
global $post;
$delimiter = $delimiter;
if (is_home()) $delimiter = '';
$homeLink = get_bloginfo('url');
echo '<a href="' . $homeLink . '" rel="nofollow">' . $home . '</a> ' . $delimiter . ' <a href="http://www.zoomingjapan.com/blog/" rel="nofollow">Blog</a> ' . $delimiter . ' ';
if ( is_category() ) {
global $wp_query;
$cat_obj = $wp_query->get_queried_object();
$thisCat = $cat_obj->term_id;
$thisCat = get_category($thisCat);
$parentCat = get_category($thisCat->parent);
if ($thisCat->parent != 0) echo(get_category_parents($parentCat, TRUE, ' ' . $delimiter . ' '));
echo $before . 'Lưu trữ theo danh mục "' . single_cat_title('', false) . '"' . $after;
} elseif ( is_day() ) {
echo '<a href="' . get_year_link(get_the_time('Y')) . '">' . get_the_time('Y') . '</a> ' . $delimiter . ' ';
echo '<a href="' . get_month_link(get_the_time('Y'),get_the_time('m')) . '">' . get_the_time('F') . '</a> ' . $delimiter . ' ';
echo $before . get_the_time('d') . $after;
} elseif ( is_month() ) {
echo '<a href="' . get_year_link(get_the_time('Y')) . '">' . get_the_time('Y') . '</a> ' . $delimiter . ' ';
echo $before . get_the_time('F') . $after;
} elseif ( is_year() ) {
echo $before . get_the_time('Y') . $after;
} elseif ( is_single() && !is_attachment() ) {
if ( get_post_type() != 'post' ) {
$post_type = get_post_type_object(get_post_type());
$slug = $post_type->rewrite;
echo '<a href="' . $homeLink . '/' . $slug['slug'] . '/">' . $post_type->labels->singular_name . '</a> ' . $delimiter . ' ';
echo $before . get_the_title() . $after;
} else {
$cat = get_the_category(); $cat = $cat[0];
echo get_category_parents($cat, TRUE, ' ' . $delimiter . ' ');
echo $before . get_the_title() . $after;
}
} elseif ( !is_single() && !is_page() && get_post_type() != 'post' && !is_404() ) {
$post_type = get_post_type_object(get_post_type());
echo $before . $post_type->labels->singular_name . $after;
} elseif ( is_attachment() ) {
$parent = get_post($post->post_parent);
$cat = get_the_category($parent->ID); $cat = $cat[0];
echo get_category_parents($cat, TRUE, ' ' . $delimiter . ' ');
echo '<a href="' . get_permalink($parent) . '">' . $parent->post_title . '</a> ' . $delimiter . ' ';
echo $before . get_the_title() . $after;
} elseif ( is_page() && !$post->post_parent ) {
echo $before . get_the_title() . $after;
} elseif ( is_page() && $post->post_parent ) {
$parent_id  = $post->post_parent;
$breadcrumbs = array();
while ($parent_id) {
$page = get_page($parent_id);
$breadcrumbs[] = '<a href="' . get_permalink($page->ID) . '">' . get_the_title($page->ID) . '</a>';
$parent_id  = $page->post_parent;
}
$breadcrumbs = array_reverse($breadcrumbs);
foreach ($breadcrumbs as $crumb) echo $crumb . ' ' . $delimiter . ' ';
echo $before . get_the_title() . $after;
} elseif ( is_search() ) {
echo $before . 'Kết quả tìm kiếm cho "' . get_search_query() . '"' . $after;
} elseif ( is_tag() ) {
echo $before . 'Bài viết được gắn thẻ "' . single_tag_title('', false) . '"' . $after;
} elseif ( is_author() ) {
global $author;
$userdata = get_userdata($author);
echo $before . 'Bài viết được đăng bởi ' . $userdata->display_name . $after;
} elseif ( is_404() ) {
echo $before . 'Lỗi 404' . $after;
}
if ( get_query_var('paged') ) {
if (is_home()) echo ' ' . $delimiter . ' ';
if ( is_category() || is_day() || is_month() || is_year() || is_search() || is_tag() || is_author() ) echo ' (';
echo __('Trang') . ' ' . get_query_var('paged');
if ( is_category() || is_day() || is_month() || is_year() || is_search() || is_tag() || is_author() ) echo ')';
}
echo '</div>';
}
} // end dimox_breadcrumbs()

Tôi đã nói chuyện với người tạo ra mã này, nhưng anh ta cũng không biết tại sao điều này xảy ra. Tôi hy vọng ai đó có ít nhất một ý tưởng để tôi có thể làm việc trên nó? Cảm ơn rất nhiều! :)

Lưu giá trị selectlist (taxonomy) trong wp:wp_set_object_terms Trong phần quản trị của tôi, tôi có các trường bổ sung (như giá hoặc thương hiệu - đó là phân loại). Khi tôi chỉnh sửa hoặc tạo một phần mới, tôi thiết lập dữ liệu bổ sung. Và việc lưu trữ giá không có vấn đề gì, nhưng việc lưu trữ giá trị từ danh sách chọn là điều kỳ lạ - nó không lưu:

wp_set_object_terms($post_id, $_POST['part_brand'], 'brands', true);

Theo tài liệu WP: hàm này cập nhật giá trị từ danh sách chọn phân loại. Nhưng với tôi nó không hoạt động. Toàn bộ mã bạn có thể xem ở đây:

