// Custom excerpt for comments
function unspoken_excerpt($string, $limit) {
    $more = '';
    $words = explode(" ",$string);
    if ( count($words) >= $limit) $more = '...';
    $output = strip_tags( implode(" ",array_splice($words, 0, $limit)).$more );
    echo $output;
}

