Hooks không thực thi Dựa trên sự hiểu biết của tôi về móc, bạn tạo một chiếc móc bằng cách làm do_action('hook_name'); sau đó thêm một cái gì đó vào móc và gọi phương thức nơi bạn muốn nó thực hiện móc, vì vậy:

public function hook_name() {
    do_action('hook_name');
}

ở đâu đó bạn làm điều gì đó như:

add_action('hook_name', 'some_hook');

và sau đó ở đâu đó trong chủ đề bạn gọi:

hook_name();

và đó là nó, nơi bạn gọi hàm đó sẽ thực hiện móc. Vâng, tôi đã cố gắng tạo một lớp để đơn giản hóa điều này, bởi vì nếu bạn có một chủ đề với nói 50.000 móc (không hỏi tại sao, tôi đang đi cùng cực đoan), đó là 50.000 chức năng giống như người tôi đã làm ở trên. Vì vậy, dựa trên: Bài đăng trước đây Tôi đã cố gắng tạo một lớp như:

<?php
class AisisCore_Hooks {
    protected $_hooks;

    public function __construct($hooks) {
        $this->_hooks = $hooks;
        $this->_setup_hooks($this->_hooks);
        $this->init();
    }

    public function init() {}

    protected function _setup_hooks($hooks) {
        foreach ($hooks as $hook => $param) {
            if (is_array($param)) {
                do_action($hook, implode(',', $param));
            } else {
                do_action($hook);
            }
        }
    }
}

Tôi sau đó đã cố gắng làm:

$array = array(
    'hook_name_one'
);

$hooks = new AisisCore_Hooks($array);

function test() {
    echo "Tôi là một thử nghiệm cho ý tưởng này";
}

add_action('hook_name_one', 'test');

Nhưng sớm nhận ra rằng tôi đang làm một hành động không có gì được gắn vào nó. Vì vậy câu hỏi của tôi là: Tôi, trong lớp của tôi, muốn truyền vào một tên hành động và một hàm và làm thêm hành động và sau đó bên ngoài gọi do_action ();? vì vậy:

protected function _setup_hooks($hooks) {
    foreach ($hooks as $tag => $action) {
        add_action($tag, $action);
    }
}

sau đó làm: do_action(// bất cứ điều gì là thẻ);

dbDelta không tạo ra bảng Tôi đã kiểm tra rất nhiều các bài viết, trang codex và cố gắng can thiệp vào nhiều thứ nhưng mã của tôi không tạo ra bảng. Tôi không thể tìm ra lỗi ở đâu. Tôi đã kiểm tra booking_db_version trong cơ sở dữ liệu, nó được cập nhật khi tôi cập nhật nó trong tập tin. Đây là mã:

global $booking_db_version;
$booking_db_version = "1.0.0";

function booking_install() {
global $wpdb;
global $booking_db_version;
global $tableprefix;
$installed_version = get_option('booking_db_option');

$tableprefix = $wpdb->prefix . 'booking_';
require_once(ABSPATH . 'wp-admin/includes/upgrade.php');

if ( $installed_version != $booking_db_version ) {
/* Tạo bảng cho gói */
$packagetable = $tableprefix . 'packages';
$sql = "create table  $packagetable (
id mediumint(9) NOT NULL AUTO_INCREMENT,
name text NOT NULL,
description text NOT NULL,
city1 text NOT NULL,
city2 text NOT NULL,
PRIMARY KEY  (id)
);";
dbDelta($sql);

/* Tạo bảng cho khách sạn */
$hoteltable = $tableprefix . 'hotels';
$sql = "create table $hoteltable (
id mediumint(9) NOT NULL AUTO_INCREMENT,
name text NOT NULL,
city text NOT NULL,
price decimal(10,2) NOT NULL,
PRIMARY KEY  (id)
);";
dbDelta($sql);

/* Tạo bảng cho addon */
$addontable = $tableprefix . 'addons';
$sql = "create table $addontable (
id mediumint(9) NOT NULL AUTO_INCREMENT,
name text NOT NULL,
addongroup text NOT NULL,
price decimal(10,2) NOT NULL,
PRIMARY KEY  (id)
);";
dbDelta($sql);

/* Tạo bảng cho nhóm addon */
$addongrouptable = $tableprefix . 'addon_groups';
$sql = "create table $addongrouptable (
id mediumint(9) NOT NULL AUTO_INCREMENT,
name text NOT NULL,
perhead text NOT NULL,
PRIMARY KEY  (id)
);";
dbDelta($sql);

update_option('booking_db_version', $booking_db_version);
}
