function ag_get_posts() {
    global $post;
    $args = array(
        'post_type' => 'post',
        'posts_per_page' => 12,
        'post_status' => 'publish',
    );
    query_posts( $args );
    while ( have_posts() ) : the_post();
        locate_template( 'post.php', TRUE, TRUE );
    endwhile;
    wp_reset_query();
    exit;
}
