Ẩn danh mục từ phía trước, nhưng không phải là quản trị viên / biên tập bài viết Tôi đang sử dụng mã sau, được đặt trong functions.php của chủ đề của tôi, để ẩn một số danh mục được sử dụng để sắp xếp bài viết và tạo ra các trình chiếu từ chính các bài viết và danh sách danh mục của chúng:

function the_category_filter($thelist,$separator=' ') {
// liệt kê các ID của các danh mục để loại trừ
$exclude = array(1,32,42,4);
// tạo một mảng rỗng
$exclude2 = array();
// lặp qua các ID bị loại trừ và nhận được tên thực của chúng
foreach($exclude as $c) {
// lưu trữ tên trong mảng thứ hai
$exclude2[] = get_cat_name($c);
}
// nhận được danh sách các danh mục cho bài viết hiện tại
$cats = explode($separator,$thelist);
// tạo một mảng rỗng khác
$newlist = array();
foreach($cats as $cat) {
// loại bỏ các thẻ từ mỗi danh mục
$catname = trim(strip_tags($cat));
// kiểm tra đối với các danh mục bị loại trừ
if(!in_array($catname,$exclude2))
// nếu không có trong danh sách đó, thêm vào mảng mới
$newlist[] = $cat;
}
// trả về danh sách mới, rút gọn
return implode($separator,$newlist);
}
// thêm bộ lọc vào thẻ 'the_category'
add_filter('the_category','the_category_filter', 1, 32, 42, 4);

Nó hoạt động tốt, nhưng nó cũng ẩn các danh mục trong cửa sổ chỉnh sửa bài viết. Tôi có thể nhìn thấy hộp đánh dấu, nhưng tên của danh mục bị ẩn. Có ai có thể gợi ý điều chỉnh mã trên để giữ chức năng ẩn các danh mục trên phía trước, nhưng giữ cho các danh mục hiển thị trong cửa sổ chỉnh sửa bài viết / phía sau của WP?

