class account_internet extends WP_Widget {

public function __construct() {

parent::WP_Widget( 'account_internet', 'Account internet', array('description' => 'Mô tả cho widget sẽ hiển thị ở đây'));

}

public function form( $instance ) {

$defaults = array(

'title' => 'Creazione account internet'

);

$instance = wp_parse_args( (array) $instance, $defaults ); ?>

<p>

<label for="<?php echo $this->get_field_id( 'title' ); ?>">

Tiêu đề:

</label>

<input class="widefat" type="text" id="<?php echo $this->get_field_id( 'title' ); ?>" name="<?php echo $this->get_field_name( 'title' ); ?>" value="<?php echo $instance['title']; ?>" />

</p>

<?php

}

public function widget( $args, $instance ) {

extract( $args );

$title = apply_filters('widget_title', $instance['title'] );

echo $before_widget;

echo $before_title . $title . $after_title;

?>

<iframe height="300px" width="150px" src="http://www.google.com"></iframe>

<?php

echo $after_widget;

}

public function update( $new_instance, $old_instance ) {

$instance = $old_instance;

$instance['title'] = strip_tags( $new_instance['title'] );

return $instance;

}

}

function account_internet_register_widgets() {

register_widget( 'account_internet' );

}

add_action( 'widgets_init', 'account_internet_register_widgets' );

