Plugin WordPress: Cập Nhật Toàn Cầu Xin chào, Tôi muốn tạo một plugin sẽ kiểm tra các bản cập nhật cho các plugin khác mà tôi đã phát triển từ một địa điểm duy nhất. Trong file plugin chính của tôi có

include_once( 'class-login-slider-updater.php' );
$login_slider_updater = new Login_Slider_Updater( 'http://wp-creation.com/api/plugins/login-slider/',plugins_url('login-slider', 'login-slider').'login-slider.php');
Trong file class-login-slider-updater.php của tôi tôi có mã sau đây. File này gọi API chỉ định tất cả các thông tin nó cần giống như WordPress.org sử dụng.

class Login_Slider_Updater
{
private $api_url = 'http://wp-creation.com/api/plugins/login-slider/';
private $api_data = array();
private $name = 'login-slider';
private $slug = 'login-slider.php';
/**
* Class constructor.
*
* @uses plugin_basename()
* @uses hook()
*
* @param string $_api_url The URL pointing to the custom API endpoint.
* @param string $_plugin_file Path to the plugin file.
* @param array $_api_data Optional data to send with API calls.
* @return void
*/
function __construct( $_api_url, $_plugin_file, $_api_data = null )
{
$this->api_url = $_api_url;
$this->api_data = $_api_data;
$this->name = plugin_basename( $_plugin_file );
$this->slug = basename( $_plugin_file, '.php');
// Set up hooks.
$this->hook();
}
/**
* Set up Wordpress filters to hook into WP's update process.
*
* @uses add_filter()
*
* @return void
*/
private function hook()
{
add_filter( 'pre_set_site_transient_update_plugins', array( &$this, 'pre_set_site_transient_update_plugins_filter' ) );
add_filter( 'plugins_api', array( &$this, 'plugins_api_filter' ), 10, 3);
}
/**
* Check for Updates at the defined API endpoint and modify the update array.
*
* This function dives into the update api just when Wordpress creates its update array,
* then adds a custom API call and injects the custom plugin data retrieved from the API.
* It is reassembled from parts of the native Wordpress plugin update code.
* See wp-includes/update.php line 121 for the original wp_update_plugins() function.
*
* @uses api_request()
*
* @param array $_transient_data Update array build by Wordpress.
* @return array Modified update array with custom plugin data.
*/
function pre_set_site_transient_update_plugins_filter( $_transient_data )
{
if( empty( $_transient_data ) ) return $_transient_data;
$to_send = array( 'slug' => $this->slug );
$api_response = $this->api_request( 'plugin_latest_version', $to_send );
if( false !== $api_response && version_compare( $_transient_data->checked[$this->name], $api_response->new_version, '<' ) ) $_transient_data->response[$this->name] = $api_response;
return $_transient_data;
}
/**
* Updates information on the "View version x.x details" page with custom data.
*
* @uses api_request()
*
* @param mixed $_data
* @param string $_action
* @param object $_args
* @return object $_data
*/
function plugins_api_filter( $_data, $_action = '', $_args = null )
{
if ( ( $_action != 'plugin_information' ) || !isset( $_args->slug ) || ( $_args->slug != $this->slug ) ) return $_data;
$to_send = array( 'slug' => $this->slug );
$api_response = $this->api_request( 'plugin_information', $to_send );
if ( false !== $api_response ) $_data = $api_response;
return $_data;
}
/**
* Calls the API and, if successfull, returns the object delivered by the API.
*
* @uses get_bloginfo()
* @uses wp_remote_post()
* @uses is_wp_error()
*
* @param string $_action The requested action.
* @param array $_data Parameters for the API action.
* @return false|object
*/
private function api_request( $_action, $_data )
{
global $wp_version;
$data = array_merge( $this->api_data, $_data );
$options = array(
'timeout' => ( ( defined('DOING_CRON') && DOING_CRON ) ? 30 : 3),
'body' => array( 'action' => $_action, 'data' => serialize( $data ) ),
'user-agent' => 'WordPress/' . $wp_version . '; ' . get_bloginfo( 'url' ) // Do not change this line.
);
// Call the custom API.
$raw_response = wp_remote_post( $this->api_url, $options );
if ( !is_wp_error( $raw_response ) && ( 200 == $raw_response['response']['code'] ) ):
return unserialize( $raw_response['body'] );
else:
return false;
endif;
}
}
Vậy điều tôi muốn làm là để tạo cho plugin này kiểm tra các bản cập nhật cho các plugin khác mà tôi đã phát triển bằng cách gọi API. Hoặc bạn có thể chỉ cho tôi hướng dẫn tốt cho việc này vì tôi không thể tìm thấy bất kỳ hướng dẫn nào giải thích cách thực hiện điều này.

