function ajax_callback() {
    //Submenu
    echo '<div id="submenu">';
    if( $sPostType !== '' ) {
        if( $sPostType == -1 ) {
            $allCategories = get_categories();
            foreach( $allCategories as $cat ) {
                echo '<li class="type-category"><a href="' . get_permalink( $cat->cat_ID ) . '">' . $cat->name . '</a></li>';
            }
        } else {
            global $wpdb;
            // set the target relationship here
            $post_type = $sPostType;
            $taxonomy = 'category';
            $terms_ids = $wpdb->get_col( $wpdb->prepare( "
                SELECT
                    tt.term_id
                FROM
                    {$wpdb->term_relationships} tr,
                    {$wpdb->term_taxonomy} tt,
                    {$wpdb->posts} p
                WHERE 1=1
                    AND tr.object_id = p.id
                    AND p.post_type = '%s'
                    AND p.post_status = 'publish'
                    AND tr.term_taxonomy_id = tt.term_taxonomy_id
                    AND tt.taxonomy ='%s'
            ", $post_type, $taxonomy ) );
            $terms = get_terms( $taxonomy, array(
                'include' => $terms_ids,
                'orderby' => 'name',
                'order' => 'ASC'
            ) );
            foreach( $terms as $cat ) {
                echo '<li class="type-category"><a href="' . get_permalink( $cat->term_id ) . '">' . $cat->name . '</a></li>';
            }
        }
    } else {
        echo '<li class="type-category" style="color: transparent">Sin categorías</li>';
    }
    echo '</div>';
}

add_action( 'wp_enqueue_scripts', 'theme_name_scripts' );
add_action('wp_ajax_ajax', 'ajax_callback');
add_action('wp_ajax_nopriv_ajax', 'ajax_callback');
