Sắp xếp mặc định trên các cột quản trị với giá trị ngày trống ẩn bài viết dự thảo Tôi có một loại bài viết tùy chỉnh "gigs" và một metabox (dùng plugin meta-box) với ngày và thời gian sự kiện được lưu như sau: 2013-11-29 20:30. Nếu tôi lưu bản nháp mà không đặt thời gian/ngày thì nó hiển thị trong cột bài viết đã đăng hoặc đang chờ duyệt như mong đợi. Tuy nhiên khi tôi cố gắng sắp xếp màn hình mặc định để các sự kiện trong tương lai ở trên cùng thì các sự kiện chưa có ngày không hiển thị trong danh sách, mặc dù có thêm một sự kiện vào số lượng của "tất cả" và "bản nháp" trong hàng trạng thái chọn ở phía trên. Tôi đang sử dụng đoạn mã sau đây (dựa trên http://wordpress.stackexchange.com/a/66478/7401 )

/* Sắp xếp bài viết trong wp_list_table theo cột tăng dần hoặc giảm dần */

function custom_post_order($query){
global $prefix;

/* Thiết lập loại bài viết
_builtin => true trả về các loại bài viết mặc định của WordPress
_builtin => false trả về các loại bài viết tùy chỉnh đã đăng ký */

$post_types = get_post_types(array('_builtin' => false), 'names');

/* Loại bài viết hiện tại */

$post_type = $query->get('post_type');

/* Kiểm tra loại bài viết */

if(in_array($post_type, $post_types) && $post_type == 'gigs'){

/* Cột bài viết: ví dụ tiêu đề */

if($query->get('orderby') == ''){
$query->set('orderby', 'meta_value');
}

if($query->get('meta_key') == ''){
