function my_meta_setup()
{
    global $post;

    // sử dụng dấu gạch dưới để ngăn không cho biến meta hiển thị trong phần trường tùy chỉnh
    $meta = get_post_meta($post->ID,'_my_meta',TRUE);

    // thay vì viết HTML ở đây, chúng ta sẽ thực hiện một việc bao gồm
    include(MY_THEME_FOLDER . '/custom/events.php');

    // tạo một nonce tùy chỉnh để xác minh gửi sau này
    echo '<input type="hidden" name="my_meta_noncename" value="' . wp_create_nonce(__FILE__) . '" />';
}

function my_meta_save($post_id)
{
    // kiểm tra xác thực

    // đảm bảo dữ liệu đến từ hộp meta của chúng tôi
    if (!wp_verify_nonce($_POST['my_meta_noncename'],__FILE__)) return $post_id;

    // kiểm tra quyền của người dùng
    if ($_POST['post_type'] == 'page')
    {
        if (!current_user_can('edit_page', $post_id)) return $post_id;
    }
    else
    {
        if (!current_user_can('edit_post', $post_id)) return $post_id;
    }

    // xác thực đã vượt qua, lưu dữ liệu

    // các kiểu biến

    // kiểu đơn: _my_meta[var]
    // kiểu mảng: _my_meta[var][]
    // mảng nhóm: _my_meta[var_group][0][var_1], _my_meta[var_group][0][var_2]

    $current_data = get_post_meta($post_id, '_my_meta', TRUE);
    $new_data = $_POST['_my_meta'];

    my_meta_clean($new_data);

    if ($current_data)
    {
        if (is_null($new_data)) delete_post_meta($post_id,'_my_meta');
        else update_post_meta($post_id,'_my_meta',$new_data);
    }
    elseif (!is_null($new_data))
    {
        add_post_meta($post_id,'_my_meta',$new_data,TRUE);
    }

    return $post_id;
}

function my_meta_clean(&$arr)
{
    if (is_array($arr))
    {
        foreach ($arr as $i => $v)
        {
            if (is_array($arr[$i]))
            {
                my_meta_clean($arr[$i]);
                if (!count($arr[$i]))
                {
                    unset($arr[$i]);
                }
            }
            else
            {
                if (trim($arr[$i]) == '')
                {
                    unset($arr[$i]);
                }
            }
        }
        if (!count($arr))
        {
            $arr = NULL;
        }
    }
}

