Menu tùy chỉnh - menu phụ khác nhau cho mục đầu tiên. Tôi đã tạo một menu tùy chỉnh với các mục thả xuống (chỉ CSS không JavaScript). Tôi cũng đã thêm một lớp CSS tùy chỉnh cho mục đầu tiên trong menu. Cho đến nay mọi thứ đều tốt. Điểm mà tôi bị mắc kẹt là thêm một mục thả xuống tùy chỉnh chỉ dành cho mục đầu tiên trong menu, khác với các mục thả xuống khác. Ngoài ra, tôi muốn thiết lập một kiểu has-children khác nhau cho mục đầu tiên. Có ai biết cách thực hiện điều này không? Đây là bộ đi bộ tùy chỉnh của tôi:

class topmenu_walker_nav_menu extends Walker_Nav_Menu {
function display_element( $element, &$children_elements, $max_depth, $depth=0, $args, &$output ) {
$id_field = $this->db_fields['id'];
if ( !empty( $children_elements[$element->$id_field] ) && ( depth == 0 ) ) {
$element->classes[] = 'has-children'; // Sử dụng bất kỳ tên lớp nào bạn thích
}
Walker_Nav_Menu::display_element( $element, $children_elements, $max_depth, $depth, $args, $output );
}

function start_lvl( &$output, $depth ) {
// Các lớp phụ thuộc vào độ sâu
$indent = ( $depth > 0  ? str_repeat( "\t", $depth ) : '' ); // dấu ngắt dòng
$display_depth = ( $depth + 1); // vì nó tính toán mức phụ đầu tiên là 0
$classes = array(
'subnav',
( $display_depth % 2  ? 'menu-odd' : 'menu-even' ),
( $display_depth >=2 ? 'sub-sub-menu' : '' ),
'menu-depth-' . $display_depth
);
$class_names = implode( ' ', $classes );

// Xây dựng HTML
$output .= "\n" . $indent . '<ul class="' . $class_names . '">' . "\n";
}

function start_el( &$output, $item, $depth, $args ) {
global $wp_query;
$indent = ( $depth > 0 ? str_repeat( "\t", $depth ) : '' ); // dấu ngắt dòng

// Các lớp phụ thuộc vào độ sâu
$depth_classes = array(
( $depth == 0 ? 'main-menu-item' : 'sub-menu-item' ),
( $depth >=2 ? 'sub-sub-menu-item' : '' ),
( $depth % 2 ? 'menu-item-odd' : 'menu-item-even' ),
'menu-item-depth-' . $depth
);
$depth_class_names = esc_attr( implode( ' ', $depth_classes ) );

$classes = empty( $item->classes ) ? array() : (array) $item->classes;
$class_names = esc_attr( implode( ' ', apply_filters( 'nav_menu_css_class', array_filter( $classes ), $item ) ) );

$output .= $indent . '<li id="nav-menu-item-'. $item->ID . '" class="' . $depth_class_names . ' ' . $class_names . '">';

// Thuộc tính liên kết
$attributes  = ! empty( $item->attr_title ) ? ' title="'  . esc_attr( $item->attr_title ) .'"' : '';
$attributes .= ! empty( $item->target )     ? ' target="' . esc_attr( $item->target     ) .'"' : '';
$attributes .= ! empty( $item->xfn )        ? ' rel="'    . esc_attr( $item->xfn        ) .'"' : '';
$attributes .= ! empty( $item->url )        ? ' href="'   . esc_attr( $item->url        ) .'"' : '';
$attributes .= ' class="menu-link ' . ( $depth > 0 ? 'sub-menu-link' : 'main-menu-link' ) . '"';

$item_output = sprintf( '%1$s<a%2$s>%3$s%4$s%5$s</a>%6$s',
$args->before,
$attributes,
$args->link_before,
apply_filters( 'the_title', $item->title, $item->ID ),
$args->link_after,
$args->after
);

// Xây dựng HTML
$output .= apply_filters( 'walker_nav_menu_start_el', $item_output, $item, $depth, $args );
}
}

add_filter( 'wp_nav_menu_objects', 'tgm_filter_menu_class', 10, 2 );

/**
* Lọc các đối tượng menu điều hướng đầu tiên và cuối cùng trong menu của bạn
* để thêm các lớp tùy chỉnh.
*
* @since 1.0.0
*
* @param object $objects Một mảng đối tượng menu điều hướng
* @param object $args Đối số đối tượng menu điều hướng
* @return object $objects Mảng được sửa đổi của các đối tượng menu điều hướng với lớp mới
*/
function tgm_filter_menu_class( $objects, $args ) {
// Chỉ áp dụng các lớp cho menu điều hướng chính
if ( isset( $args->theme_location ) )
if ( 'main-menu' !== $args->theme_location )
return $objects;

// Thêm lớp "first-menu-item" cho đối tượng menu đầu tiên
$objects[1]->classes[] = 'settingsitem';

// Thêm lớp "last-menu-item" cho đối tượng menu cuối cùng
$objects[count( $objects )]->classes[] = 'last-menu-item';

// Trả về các đối tượng menu
return $objects;
}

