> include('js/superfish.js');
> include('js/switcher.js');
> include('js/jquery.mousewheel.min.js');

Tôi chỉ muốn biết liệu có cách nào để tạo đường dẫn mẫu cho các tập tin .js được bao gồm bên trong tập tin 'scripts.js' không? Tôi là người mới bắt đầu với WordPress. Tôi đã tìm thấy ý tưởng cho đoạn mã sau nhưng không biết cách thực hiện:

<script type="text/javascript">
var templateUrl = '<?= get_bloginfo( 'template_directory' ) . '/'; ?>';
</script>

