Tạo liên kết cho các bài viết tùy chỉnh cá nhân Tôi đang cố tìm cách điều chỉnh mã tạo bài viết ngẫu nhiên để hoạt động cho từng loại bài viết tùy chỉnh của tôi ngoài loại tôi đã có là loại sắp xếp qua tất cả các loại bài viết tùy chỉnh của tôi. Đây là mã tôi đã thêm vào tệp functions.php để nó hoạt động cho tất cả 7 loại bài viết tùy chỉnh (bài viết, câu hỏi, video, phim tài liệu, bài nói chuyện TED, meme và âm nhạc):

add_action('init','random_add_rewrite');

function random_add_rewrite() {
global $wp;
$wp->add_query_var('random');
add_rewrite_rule('random/?$', 'index.php?random=1', 'top');
}

add_action('template_redirect','random_template');

function random_template() {
if (get_query_var('random') == 1) {
$posts =
get_posts('post_type[]=articles&post_type[]=questions&post_type[]=videos&post_type[]=documentaries&post_type[]=ted-talks&post_type[]=memes&post_type[]=music&orderby=rand&numberposts=1');
foreach($posts as $post) {
$link = get_permalink($post);
}
wp_redirect($link,307);
exit;
