// Lưu giá trị hộp Meta
function meta_box_save( $post_id ) {
    // Dừng kịch bản khi thực hiện tự động lưu
    if( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) return;

    // Xác minh nonce. Nếu không tồn tại, dừng kịch bản
    if( !isset( $_POST['meta_box_nonce'] ) || !wp_verify_nonce( $_POST['meta_box_nonce'], 'my_meta_box_nonce' ) ) return;

    // Dừng kịch bản nếu người dùng không có quyền chỉnh sửa
    if( !current_user_can( 'edit_post' ) ) return;

    // Lưu trường văn bản
    if( isset( $_POST['textfield'] ) )
        update_post_meta( $post_id, 'textfield', esc_attr( $_POST['textfield'] ) );
}
add_action( 'save_post', 'meta_box_save' );

