// Xác minh trường email.
if(isset($_REQUEST['email']) && !empty($_REQUEST['email'])) {
if(preg_match("/(%0A|%0D|\n+|\r+|:)/i",$_REQUEST['email'])){$errors[] = "Địa chỉ email không được chứa một dòng mới hoặc dấu hai chấm";}
$_REQUEST['email'] = trim($_REQUEST['email']);
if(substr_count($_REQUEST['email'],"@") != 1 || stristr($_REQUEST['email']," ")){$errors[] = "Địa chỉ email không hợp lệ";}else{$exploded_email = explode("@",$_REQUEST['email']);if(empty($exploded_email[0]) || strlen($exploded_email[0]) > 64 || empty($exploded_email[1])){$errors[] = "Địa chỉ email không hợp lệ";}else{if(substr_count($exploded_email[1],".") == 0){$errors[] = "Địa chỉ email không hợp lệ";}else{$exploded_domain = explode(".",$exploded_email[1]);if(in_array("",$exploded_domain)){$errors[] = "Địa chỉ email không hợp lệ";}else{foreach($exploded_domain as $value){if(strlen($value) > 63 || !preg_match('/^[a-z0-9-]+$/i',$value)){$errors[] = "Địa chỉ email không hợp lệ"; break;}}}}}}
}
// Kiểm tra người gửi tham chiếu từ cùng một trang web.
if(!(isset($_SERVER['HTTP_REFERER']) && !empty($_SERVER['HTTP_REFERER']) && stristr($_SERVER['HTTP_REFERER'],$_SERVER['HTTP_HOST']))){$errors[] = "Bạn phải bật ghi nhật ký người gửi để sử dụng biểu mẫu";}
// Kiểm tra biểu mẫu trống.
function recursive_array_check_blank($element_value) {
global $set;
if(!is_array($element_value)){if(!empty($element_value)){$set = 1;}}
else
{
foreach($element_value as $value){if($set){break;} recursive_array_check_blank($value);}
}
}
recursive_array_check_blank($_REQUEST);
if(!$set){$errors[] = "Bạn không thể gửi biểu mẫu trống";}
unset($set);
// Hiển thị bất kỳ lỗi nào và thoát nếu có lỗi.
if(count($errors)){foreach($errors as $value){print "$value<br>";} exit;}
if(!defined("PHP_EOL")){define("PHP_EOL", strtoupper(substr(PHP_OS,0,3) == "WIN") ? "\r\n" : "\n");}
// Xây dựng tin nhắn.
function build_message($request_input){if(!isset($message_output)){$message_output ="";}if(!is_array($request_input)){$message_output = $request_input;}else{foreach($request_input as $key => $value){if(!empty($value)){if(!is_numeric($key)){$message_output .= str_replace("_"," ",ucfirst($key)).": ".build_message($value).PHP_EOL.PHP_EOL;}else{$message_output .= build_message($value).", ";}}}}return rtrim($message_output,", ");}
$message = build_message($_REQUEST);
$message = $message . PHP_EOL.PHP_EOL."-- ".PHP_EOL."";
$message = stripslashes($message);
$subject = "Biểu mẫu tìm kiếm đại lý từ site.com";
$headers = "Từ: site.com" . $_REQUEST['Name'];
mail($my_email,$subject,$message,$headers);
